INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('33001f3b-215f-53fc-a2e2-2b23e4a7ed17', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 13, 13, 'ነገር ግን የሕዝቡ ቍጥር ብዙ ነው፤ ጊዜውም የትልቅ ዝናብ ጊዜ ነው፤ በሜዳም ልንቆም አንችልም፤ በዚህም ነገር እጅግ በድለናልና ይህ ሥራ የአንድ ወይም የሁለት ቀን ሥራ አይደለም።'),
  ('e412ecdf-e7c0-5cc2-a218-9f85b066a935', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 14, 14, 'አለቆቻችንም በጉባኤው ፋንታ ሁሉ ይቁሙ፤ ስለዚህም ነገር የአምላካችን ጽኑ ቍጣ ከእኛ ይመለስ ዘንድ እንግዶቹን ሴቶች ያገቡት በከተሞቻችን ያሉት ሁሉ በተቀጠረው ጊዜ ይምጡ፤ ከእነርሱም ጋር የከተማው ሁሉ ሽማግሌዎችና ፈራጆች ይምጡ።”'),
  ('45887d62-987e-54e5-a38f-4b350e8b881f', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 15, 15, 'ነገር ግን የአሣሄል ልጅ ዮናታንና የቴቁዋ ልጅ የሐዝያ ስለዚህ ነገር ከእኔ ጋር ናቸው፤ ሜሱላምና ሌዋዊው ሰባታይም ይረዱአቸው ነበር።'),
  ('2242dbd2-fefb-5d69-a205-b8d1ce6eb18f', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 16, 16, 'የስደተኞቹም ልጆች እንዲህ አደረጉ፤ ካህኑ ዕዝራ፥ የአባቶችም ቤቶች አለቆች በየአባቶቻቸው ቤቶች ሁሉም በየስማቸው ተለዩ፤ በዐሥረኛውም ወር በመጀመሪያው ቀን ነገሩን ይመረምሩ ዘንድ ተቀመጡ።'),
  ('c9f298cc-b4ca-5a18-a837-36255046def9', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '929959c2-84c2-5ebe-ac19-c5979fdb6141', 17, 17, 'እስከ መጀመሪያውም ወር እስከ መጀመሪያው ቀን ድረስ ሠርተው እንግዶቹን ሴቶች ያገቡትን ሰዎች ሁሉ መርምረው ጨረሱ።'),
  ('2a12a95b-512c-513c-a74c-49369c54e012', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 1, 18, 'ከካህናቱም ወገን ልጆች እንግዶቹን ሴቶች ያገቡ ሰዎች ተገኙ፤ ከኢዮሴዴቅ ልጅ ከኢያሱ ልጆችና ከወንድሞቹ ማዓሥያ፥ አልዓዛር፥ ኦሬም፥ ገዳልያ።'),
  ('12b60112-2616-5c6b-a218-ecf77a807ca0', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 2, 19, 'ሚስቶቻቸውን ይፈቱ ዘንድ እጃቸውን ሰጡ፤ ስለ በደላቸውም ከመንጋው አንድ አውራ በግ ለበደል መሥዋዕት አቀረቡ።'),
  ('ae6c6751-bd35-5628-a935-08d6d58392a9', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 3, 20, 'ከኢሚር ልጆችም አናኒና ዝብድያ።'),
  ('a0e10ddd-342c-5b72-a559-aadd8bdd9865', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 4, 21, 'ከኤራም ልጆችም መሳሔል፥ ኤልያ፥ ሴሚያ፥ ያሔል፥ ዖዝያ።'),
  ('45a45f64-74c1-5654-ad3b-6a5499b3b25d', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 5, 22, 'ከጳሰኮር ልጆችም ኤልዮና፥ መሐሰዓ፥ ይስማኤል፥ ናትናኤል፥ ኢዮዛባድ፥ ኤልሣ።'),
  ('822ff17e-ee8d-5bab-a9a4-1dd6878a1b7c', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 6, 23, 'ከሌዋውያንም ኢዮዛባድ፥ ሰሜኢ፥ ቆሊጣስ የሚባል ቆልያ፥ ፈዲሓ፥ ይሁዳ፥ አልዓዛር።'),
  ('17c53baa-1dc1-5a77-a0bb-062bbdc63f34', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 7, 24, 'ከመዘምራንም ኤልያሴብ፤ ከበረኞችም ሰሎም፥ ጤሎም፥ ኡሪ።'),
  ('9922b295-a316-5cb2-ac5d-b18f3ba2fd78', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 8, 25, 'ከእስራኤልም ከፋሮስ ልጆች ራምያ፥ ዖዝያ፥ መልክያ፥ ሚያሚን፥ አልዓዛር፥ መልክያ፥ ቤንያህ።'),
  ('acae0ebe-1bde-5787-aa60-018c3aff805a', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 9, 26, 'ከኤላም ልጆችም መታንያ፥ ዘካርያስ፥ ኢያኤል፥ አብዲ፥ ይሬሞት፥ ኤልያ።'),
  ('90c058e1-0cb7-5945-a1f1-0427fc8c68f1', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 10, 27, 'ከዛቱ ልጆችም ዔሊዔናይ፥ ኤልያሴብ፥ መታንያ፥ ኤርሞት፥ ዛባድ፥ ዓዚዛ።'),
  ('72708ff2-7790-5b11-a43e-627a8aef6969', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 11, 28, 'ከቤባይ ልጆችም ዮሐናን፥ ሐናንያ፥ ዘባይ፥ አጥላይ።'),
  ('54d4e732-78cd-5c61-acc9-8f7c08104962', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 12, 29, 'ከባኒ ልጆችም ሜሱላም፥ መሉክ፥ ዓዳያ፥ ያሱብ፥ ሳዓል፥ ራሞት።'),
  ('6a344aaf-b6b3-5da8-ad5e-bf6f8151f8cd', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 13, 30, 'ከፈሐት ሞዓብ ልጆችም ዓድና፥ ክላል፥ በናያስ፥ ማዕሴያ፥ መታንያ፥ ባስልኤል፥ በነዊ፥ ምናሴ።'),
  ('761293e8-a0be-5343-a40c-3725ee47413a', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 14, 31, 'ከኤራም ልጆችም አልዓዛር፥ ይሲያ፥ ሚልክያ፥ ሰማያ፥ ስምዖን፥'),
  ('f56d8bfe-4651-543b-a786-6c3f109a5cf7', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 15, 32, 'ብንያም፥ መሉክ፥ ሰማርያ።'),
  ('aa5a61d8-5145-5105-a3f3-0ee51f61f3df', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 16, 33, 'ከሐሱም ልጆችም መታንያ፥ መታታ፥ ዛባድ፥ ኤሊፋልጥ፥ ይሬማይ፥ ምናሴ፥ ሰሜኢ።'),
  ('3c417efe-d41f-5463-abc7-6d924b3da968', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 17, 34, 'ከባኒ ልጆችም ማዕዳይ፥ ዓምራም፥ ኡኤል፥'),
  ('3d455a12-4009-588a-a717-95e66c16c316', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 18, 35, 'በናያስ፥ በዳያ፥ ኬልቅያ፥'),
  ('4e0f31f5-d512-52bb-aa42-83069d5983e0', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 19, 36, 'ውንያ፥ መሪሙት፥ ኤልያሴብ፤'),
  ('aef8d920-2712-5d64-a25a-a9e236b49f96', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 20, 37, 'መታንያ፥ መትናይ፥ የዕሡ፤'),
  ('9fab70f8-7a2f-5ee0-a84d-e8ff98b7ac14', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 21, 38, 'የባኔይ ልጆችና የሰሜይ ልጆች፤'),
  ('8bf95cfa-bd8d-5661-ab7f-2ef3bb300f90', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 22, 39, 'ሰሌምያ፥ ናታን፥ ሐዳያ፤'),
  ('c8bd434c-9b96-56c7-aca2-c41043eeed73', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 23, 40, 'መክነድባይ፥ ሴሴይ፥ ሰራይ፤'),
  ('502124e0-d4f5-50ef-ac38-9495bb60aac7', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 24, 41, 'ኤዛርኤል፥ ሰሌምያ፥ ሰማርያ፥'),
  ('6d5f94d4-9b0d-561b-abfe-ccc6695f9c21', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 25, 42, 'ሰሎም፥ አማርያ፥ ዮሴፍ።'),
  ('991494e2-f08e-54cd-a9f6-e86120971800', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 26, 43, 'ከናቡ ልጆችም ይዒኤል፥ መታትያ፥ ዛባድ፥ ዛብንያ፥ ያዳይ፥ ኢዮኤል፥ በናያስ።'),
  ('2b091dca-646e-50f4-a6c5-694b9609e218', '8fde9cce-05d9-5ad0-a4ed-9d451e173afc', '84d0669c-c9d0-5bfa-a63c-d9a0cbe1c531', 27, 44, 'እነዚህ ሁሉ እንግዶቹን ሚስቶች አግብተው ነበር፤ ከእነዚህም ሚስቶች ዐያሌዎቹ ልጆችን ወልደው ነበር።'),
  ('1d0a28f8-7055-5b2b-a064-18f16c9a933f', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 1, 1, 'የኬልቅያ ልጅ የነህምያ ቃል።'),
  ('410a36d9-9e4c-59a2-a00e-77ff1159a0ce', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 2, 2, 'ከወንድሞች አንዱ ሐናኒ፥ ከእርሱም ጋር ሌሎች ሰዎች ከይሁዳ መጡ፤ እኔም የዳኑትን፥ ከምርኮም የተረፉትን የአይሁድን ነገር፥ የኢየሩሳሌምንም ነገር ጠየቅኋቸው።'),
  ('81e2cfe0-38c8-5d56-a913-70561e811840', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 3, 3, 'እነርሱም፥ “በዚያ ስፍራ ያሉት ከምርኮ የተረፉት ቅሬታዎች በታላቅ መከራና ስድብ አሉ፤ የኢየሩሳሌምም ቅጥር ፈርሶአል፥ በሮችዋም በእሳት ተቃጥለዋል” አሉኝ።'),
  ('1eec6cc0-cd73-5219-a67e-865ade30f713', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 4, 4, 'ይህንም ቃል በሰማሁ ጊዜ ተቀምጬ አለቀስሁ፤ አያሌ ቀንም አዝን ነበር፤ በሰማይም አምላክ ፊት እጾምና እጸልይ ነበር፤ እንዲህም አልሁ፦'),
  ('683e8b29-89f9-5f9e-acb0-1326f8d58ee5', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 5, 5, '“አቤቱ የሰማይ አምላክ ሆይ፥ ለሚወድዱህና ትእዛዝህን ለሚያደርጉ ቃል ኪዳንንና ምሕረትን የምትጠብቅ፥ ታላቅና የተፈራህ አምላክ ሆይ፥'),
  ('20b52c8e-75ff-5e22-a3d8-f5ab332ccba4', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 6, 6, 'እኔ ባሪያህ ዛሬ በፊትህ ስለ ባሪያዎችህ ስለ እስራኤል ልጆች ሌሊትና ቀን የምጸልየውን ጸሎት ትሰማ ዘንድ ጆሮዎችህ ያድምጡ፤ ዐይኖችህም ይከፈቱ፤ በአንተ ላይም ያደረግነውን የእስራኤልን ልጆች ኀጢአት ለአንተ እንናዘዛለን፤ እኔም፥ የአባቴም ቤት በድለናል።'),
  ('736d6977-a701-51f9-a6b6-78e1ccee1505', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 7, 7, 'እኛም በአንተ ላይ እጅግ ክፉ ሠርተናል፤ ለባሪያህም ለሙሴ ያዘዝኸውን ትእዛዝና ሥርዐት፥ ሕጉንም አልጠበቅንም።'),
  ('07164f3e-96bd-570c-a0f5-22199bfbb917', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 8, 8, '“አሁንም ለሙሴ ለባሪያህ እንዲህ ስትል ያዘዝሃትን ነገር አስብ። ብትበድሉም በአሕዛብ መካከል እበትናችኋለሁ።'),
  ('a742ad18-40d2-5e8f-a2ca-eb923b92e5b3', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 9, 9, 'ወደ እኔ ብትመለሱ ግን፥ ትእዛዜንም ብትጠብቁ፥ ብታደርጓትም ምንም ከእናንተ ሰዎች እስከ ሰማይ ዳርቻ ቢበተኑ፥ ከዚያ እሰበስባቸዋለሁ፤ ስሜም ይኖርበት ዘንድ ወደ መረጥሁት ስፍራ አመጣቸዋለሁ።'),
  ('f598e871-ebe3-57ab-a99b-0b5e6f48ab68', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 10, 10, '“እነዚህም በታላቅ ኀይልህና በብርቱ እጅህ የተቤዥሃቸው ባሪያዎችህና ሕዝብህ ናቸው።'),
  ('f88545f8-d680-5e1a-a423-ebe294498113', '88a47b00-f0a8-5b11-a5d9-0e04007c3d56', '60d01ab5-9ae8-5145-a888-8a8e9bf80d50', 11, 11, 'ጌታ ሆይ፥ ጆሮህ የባሪያህን ጸሎት፥ ስምህንም ይፈሩ ዘንድ የሚወድዱትን የባሪያዎችህን ጸሎት ያድምጥ፤ ዛሬም ለባሪያህ አከናውንለት፤ በዚህም ሰው ፊት ምሕረትን ስጠው።” እኔም ለንጉሡ ጠጅ አሳላፊ ነበርሁ።'),
  ('d022bd46-2ef4-55f9-a5bc-12dab5ccb1dd', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 1, 1, 'በንጉሡ በአርተሰስታ በሃያኛው ዓመተ መንግሥት በኔሳን ወር የወይን ጠጅ በፊቱ ነበር፤ ጠጁንም አንሥቼ ለንጉሡ ሰጠሁት። በፊቱም ሌላ ሰው አልነበረም።'),
  ('758963ce-dcb3-53c7-a0dd-44b2d2e2c28c', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 2, 2, 'ንጉሡም፥ “ሳትታመም ፊትህ ለምን አዘነ? ይህ የልብ ኀዘን ነው እንጂ ሌላ አይደለም” አለኝ። እጅግም ብዙ አድርጌ ፈራሁ።'),
  ('903e38a3-f78d-57a8-a94c-0f1a3cb4b582', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 3, 3, 'ንጉሡንም፥ “ንጉሡ ለዘለዓለም ይኑር፤ የአባቶች መቃብር ያለባት ከተማ ተፈትታለችና፥ በሮችዋም በእሳት ተቃጥለዋልና ፊቴ ስለ ምን አያዝን?” አልሁት።'),
  ('f810ee0b-ac0c-54cd-ab24-9db2bb286556', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 4, 4, 'ንጉሡም፥ “ምን ትለምነኛለህ?” አለኝ። እኔም ወደ ሰማይ አምላክ ጸለይሁ።'),
  ('00509a3a-451e-5488-a3bc-abf6144aff33', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 5, 5, 'ንጉሡንም፥ “ንጉሡን ደስ ቢያሰኝህ፥ ባሪያህም በፊትህ ሞገስ ቢያገኝ፥ እሠራው ዘንድ ወደ ይሁዳ ወደ አባቶች መቃብር ከተማ ስደደኝ” አልሁት።'),
  ('554f69fe-f3ae-5b85-a814-73ab5d98043e', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 6, 6, 'ንግሥቲቱም፦ በአጠገቡ ተቀምጣ ሳለች ንጉሡ፥ “መንገድህ እስከ መቼ ድረስ ይሆናል? መቼስ ትመለሳለህ?” አለኝ። ንጉሡም ይሰድደኝ ዘንድ ደስ አለው፤ እኔም ጊዜውን ነገርሁት፤ እርሱም አሰናበተኝ።'),
  ('654f02a8-a731-512f-a508-dc21d4db9d9d', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 7, 7, 'ንጉሡንም፥ “ንጉሥ ደስ ቢለው፥ እስከ ይሁዳ ሀገር እንዲያደርሱኝ በወንዝ ማዶ ላሉት ገዦች ደብዳቤ ይስጠኝ፤'),
  ('1df8a4dc-52a7-59a8-a162-23f225e334d2', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 8, 8, 'በቤቱም አጠገብ ላለው ለግንብ በሮች፥ ለከተማውም ቅጥር፥ ለምገባበትም ቤት እንጨት እንዲሰጠኝ ለንጉሡ ዱር ጠባቂ ለአሳፍ ደብዳቤ ይሰጠኝ” አልሁት። ንጉሡም ሁሉን ሰጠኝ። የከበረች የአምላኬ እጅ ከእኔ ጋር ነበረችና።'),
  ('02349807-acae-5e24-a0e0-29dc678ac0fb', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 9, 9, 'በወንዙም ማዶ ወዳሉት ሀገረ ገዦች መጥቼ የንጉሡን ደብዳቤዎች ሰጠኋቸው። ንጉሡም ከእኔ ጋር የሠራዊቱን አለቆችና ፈረሰኞች ልኮ ነበር።'),
  ('a0a5bbe0-5b80-527a-ab3d-2f202f6643bc', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 10, 10, 'ሖሮናዊውም ሰንባላጥና አገልጋዩ አሞናዊው ጦብያ ለእስራኤል ልጆች መልካምን ነገር የሚሻ ሰው እንደ መጣ በሰሙ ጊዜ እጅግ ተበሳጩ።'),
  ('b4a0610e-47a6-5326-ae93-5ff42a56c5dc', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 11, 11, 'ወደ ኢየሩሳሌምም ደረስሁ፤ በዚያም ሦስት ቀን ተቀመጥሁ።'),
  ('2b0b0878-76a0-566c-abf3-673808849af4', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 12, 12, 'በሌሊትም ተነሣሁ፤ ከእኔም ጋር ጥቂት ሰዎች ነበሩ፤ እግዚአብሔርም ለኢየሩሳሌም አደርገው ዘንድ በልቤ ያኖረውን ለማንም አላስታወቅሁም፤ ተቀምጬበት ከነበረው እንስሳ በቀር ከእኔ ጋር ምንም እንስሳ አልነበረም።'),
  ('558caad2-e145-55ac-a6ca-804a94f6e562', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 13, 13, 'በሸለቆውም በር ወጣሁ፤ ወደ በለስም ምንጭና ወደ ጕድፍ መጣያው በር ሄድሁ፤ የፈረሰውንም የኢየሩሳሌምን ቅጥር፥ በእሳትም የተቃጠሉትን በሮችዋን ተመለከትሁ።'),
  ('257ba32a-ffeb-59f8-af7d-e9b040e4f2d9', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 14, 14, 'ወደ ምንጩም በርና ወደ ንጉሡም መዋኛ አለፍሁ፤ ተቀምጬበት የነበረው እንስሳም የሚያልፍበት ስፍራ አልነበረም።'),
  ('831161be-93e2-5e8e-a81c-228e28430976', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 15, 15, 'በሌሊትም በፈፋው በኩል ወጥቼ ቅጥሩን ተመለከትሁ፤ በሸለቆውም በር ገባሁ፤ እንዲሁም ተመለስሁ።'),
  ('2e9eea84-54b1-5071-a86d-1967678119f5', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 16, 16, 'ጠባቆች ግን ወዴት እንደ ሄድሁ፥ ምን እንዳደረግሁም አላወቁም ነበር፤ ለአይሁድና ለካህናቱ፥ ለታላላቆችና ለሹሞቹም፥ ሥራም ይሠሩ ለነበሩት ለሌሎች እስከዚያ ጊዜ ገና አልተናገርሁም ነበር።'),
  ('7163ba37-2c09-5208-ad30-ab13288f35fe', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 17, 17, 'እኔም፥ “እኛ ያለንበትን ጕስቍልና፥ ኢየሩሳሌም እንደ ፈረሰች፥ በሮችዋም በእሳት እንደ ተቃጠሉ ታያላችሁ። አሁንም ከእንግዲህ ወዲህ መሳለቂያ እንዳንሆን ኑና የኢየሩሳሌምን ቅጥር እንሥራ” አልኋቸው።'),
  ('ccf55938-5879-5de8-adeb-46481d02c56b', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 18, 18, 'የአምላኬም እጅ በእኔ ላይ መልካም እንደ ሆነች፥ ንጉሡም የነገረኝን ቃል ነገርኋቸው። “ተነሡ እንሥራ” አልኋቸው። እጆቻቸውንም ለበጎ ሥራ አበረቱ።'),
  ('367408c7-447d-5b64-a114-f9763060d21a', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 19, 19, 'ሖሮናዊውም ሰንባላጥ፥ አገልጋዩም አሞናዊው ጦቢያ፥ ዓረባዊውም ጌሳም በሰሙ ጊዜ በንቀት ሳቁብን፤ ቀላል አድርገውንም ወደ እኛ መጡና፥ “ይህ የምታደርጉት ነገር ምንድን ነው? በውኑ በንጉሡ ላይ ትሸፍቱ ዘንድ ትወድዳላችሁን?” አሉ።'),
  ('a5463088-6091-5c8b-a803-512dd3b24fb4', '76fa970b-9b7f-5cb3-aed8-07ec85d704cc', 'bf2d765c-caa8-547b-a3bd-7f535b350f37', 20, 20, 'እኔም መልሼ፥ “የሰማይ አምላክ ያከናውንልናል፤ እኛም ንጹሓን ባሪያዎቹ ተነሥተን እንሠራለን፤ እናንተ ግን በኢየሩሳሌም ዕድል ፋንታና መብት፥ መታሰቢያም የላችሁም” አልኋቸው።'),
  ('fd4c6da1-7494-5a80-aa23-ca811a26b0ec', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 1, 1, 'ታላቁም ካህን ኤልያሴብና ወንድሞቹ ካህናት ተነሥተው የበግ በር ሠሩ፤ ቀደሱትም፤ ሳንቃዎቹንም አቆሙ፤ እስከ መቶ ግንብና እስከ ሐናንኤል ግንብ ድረስ ቀደሱት።'),
  ('92d3e178-aaa2-54d6-a329-8c8567ee6ab7', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 2, 2, 'በአጠገቡም የኢያሪኮ ሰዎች ሠሩ፤ በአጠገባቸውም የአምሪ ልጅ የዘኩር ልጆች ሠሩ።'),
  ('bcc86235-47d5-568e-a406-3e6d7ed7ce4a', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 3, 3, 'የአስናሃ ልጆችም የዓሣ በር ሠሩ፤ ሠረገሎቹንም አኖሩ፤ ሳንቃዎቹንም አቆሙ፥ ቍልፎቹንና መወርወሪያዎቹንም አደረጉ።'),
  ('84101268-2126-52bf-a814-36cfa1ef0fd1', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 4, 4, 'በአጠገባቸውም የቆስ ልጅ የኡርያ ልጅ ሚራሞት ይሠራ ጀመረ። በአጠገባቸውም የሜሴዜቤል ልጅ የበራክያ ልጅ ሜሱላም ይሠራ ጀመረ። በአጠገባቸውም የበሃና ልጅ ሳዶቅ ይሠራ ጀመረ።'),
  ('8ea90a7e-fd6a-5654-ac82-90e6bfe09fd0', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 5, 5, 'በአጠገባቸውም ቴቁሓውያን ይሠሩ ጀመሩ፤ ታላላቆቻቸው ግን ለሥራው አንገታቸውን አላዋረዱም።'),
  ('5f59c1b9-1428-5c7d-aae8-ca5753b9ac97', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 6, 6, 'የፋሴሓ ልጅ ኢዮዳሄና የበሶድያ ልጅ ሜሱላም አሮጌውን በር አደሱ፤ ሰረገሎቹን አኖሩ፤ ሳንቃዎቹንም አቆሙ፤ ቍልፎቹንና መወርወሪያዎቹንም አደረጉ።'),
  ('4ef38fab-61ad-59ec-ab16-b4422b9c8a6b', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 7, 7, 'በአጠገባቸውም ገባዖናዊው መልጥያና ሜሮናታዊው ያዴን፥ እስከ ወንዙም ማዶ አለቃ ግዛት የሆኑ የገባዖንና የመሴፋ ሰዎች ሠሩ።'),
  ('7077123c-f237-5c5a-abc9-ae909cc4edaa', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 8, 8, 'በአጠገባቸውም ወርቅ አንጥረኛው የሐሬህያ ልጅ ዑዝኤል ሠራ። በአጠገቡም ከሽቱ ቀማሚዎች የነበረ ሐናንያ ሠራ፤ እስከ ሰፊው ቅጥር ድረስ ኢየሩሳሌምን ጠገኑ።'),
  ('9fd8d6e4-9d25-5791-ad5f-335314621c1c', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 9, 9, 'በአጠገባቸውም የኢየሩሳሌም ግዛት እኩሌታ አለቃ የሆር ልጅ ረፋያ ሠራ።'),
  ('c9244277-9de3-5e39-aa53-dec2574121b3', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 10, 10, 'በአጠገባቸውም የኤርማፍ ልጅ ይዳያ በቤቱ አንጻር ያለውን ሠራ። በአጠገቡም የአሰብንብሔም ልጅ ሐጡስ ሠራ።'),
  ('05677987-db57-5bd1-aedb-a2a6743d383d', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 11, 11, 'የካሪም ልጅ መልክያ፥ የፈሐት ሞዓብ ልጅም አሱብ ሌላውን ክፍልና የእቶኑን ግንብ ሠሩ።'),
  ('1826da3c-31ee-5cd0-ae49-f454fb91d236', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 12, 12, 'በአጠገባቸውም የኢየሩሳሌም ግዛት እኩሌታ ገዢ የአሎኤስ ልጅ ሰሎምና ሴቶች ልጆቹ ሠሩ።'),
  ('765ee0c6-b882-5d2c-a5a7-636aca6c6046', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 13, 13, 'ሐኖንና የዘናን ሰዎችም የሸለቆውን በር አደሱ፤ ሠሩት፤ ሳንቃዎቹንም አቆሙ፥ ቍልፎቹንና መወርወሪያዎቹንም አደረጉ፤ ደግሞም እስከ ጕድፍ መጣያ በር ድረስ አንድ ሺህ ክንድ የሚሆን ቅጥር ሠሩ።'),
  ('bf519813-5663-50c7-a5d7-b988334a07e4', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 14, 14, 'የቤትሐካሪምም ግዛት ገዢ የሬካብ ልጅ መልክያ ከወንድሞቹና ከልጆቹ ጋር የጕድፍ መጣያውን በር ሠራ፤ ከደነው፤ ሳንቃዎቹንም አቆመ፤ ቍልፎቹንና መወርወሪያዎቹንም አደረገ።'),
  ('167cf878-00e0-5de2-aa80-732bded22233', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 15, 15, 'የመሴፋም ገዢ የኮልሐዜ ልጅ ሰሎም የምንጩን በር አደሰ፤ ሠራው፤ ከደነውም፤ ሳንቃዎቹንም አቆመ፤ ቍልፎቹንና መወርወሪያዎቹንም አደረገ፤ ከዳዊትም ከተማ እስከሚወርደው ደረጃ ድረስ በንጉሡ አትክልት አጠገብ ያለውን የመዋኛ ቅጥር ሠራ።'),
  ('370dcae2-55f4-58ae-a96f-86d17d399f03', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 16, 16, 'ከእርሱም በኋላ የቤሶር ግዛት እኩሌታ ገዢ የዓዛቡህ ልጅ ነህምያ በዳዊት መቃብር አንጻር እስካለው ስፍራ፥ እስከ ተሠራውም መዋኛ፥ እስከ ኀያላኑም ቤት ድረስ ሠራ።'),
  ('293add05-bf6d-5cf5-a6bb-b959dce04b7e', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 17, 17, 'ከእርሱም በኋላ ሌዋውያንና የባኒ ልጅ ሬሁም ሠሩ። በአጠገባቸውም የቅዒላ ግዛት እኩሌታና የአውራጃዎችዋ ገዢ አሰብያ ሠራ።'),
  ('789e6044-40f1-59e1-aacd-1187856a4653', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 18, 18, 'ከእርሱም በኋላ የቅዔላ ግዛት እኩሌታ ገዢ የኤንሐዳድ ልጅ ቤኒይና ወንድሞቹ ሠሩ።'),
  ('dda8bdcc-6b10-5851-a1f1-a56076942e44', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 19, 19, 'በአጠገቡም የመሴፋ ገዢ የኢያሱ ልጅ አዙር በማዕዘኑ አጠገብ በመወጣጫው ግንብ አንጻር ያለውን ሌላውን ክፍል ሠራ።'),
  ('416c237d-0933-5bd8-adee-31d319aaf888', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 20, 20, 'ከእርሱም በኋላ የዘቡር ልጅ ባሮክ ከማዕዘኑ ጀምሮ እስከ ታላቁ ካህን እስከ ኤልያሴብ ቤት መግቢያ ድረስ ሌላውን ክፍል ተግቶ ሠራ።'),
  ('a581dfac-aa2e-538e-ae78-79c5e3098818', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 21, 21, 'ከእርሱም በኋላ የአቆስ ልጅ የኡርያ ልጅ ሚራሞት ከኤልያሴብ ቤት መግቢያ ጀምሮ እሰከ ኤልያሴብ ቤት መጨረሻ ድረስ ሌላውን ክፍል ሠራ።'),
  ('8ec3c5d9-b70f-5c9f-a034-e5dd8426f4f8', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 22, 22, 'ከእርሱም በኋላ የአካባቢው ሰዎች ካህናቱ ሠሩ።'),
  ('eb2b8562-91ae-5945-a462-716c93d5f271', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 23, 23, 'ከእነርሱም በኋላ ብንያምና አሴብ በቤታቸው አንጻር ያለውን ሠሩ። ከእነርሱም በኋላ የሐናንያ ልጅ የመዓስያ ልጅ ዓዛርያስ በቤቱ አጠገብ ያለውን ሠራ።'),
  ('e7b59582-7017-509a-a531-a145006101de', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 24, 24, 'ከእርሱም በኋላ የኢንሓዳድ ልጅ ባኒ ከዓዛርያስ ቤት ጀምሮ እስከ ማዕዘኑ እስከ ግንቡመዞሪያ ድረስ ያለውን ሌላውን ክፍል ሠራ።'),
  ('27068199-1215-543d-ac92-d7b7df9ee7e7', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 25, 25, 'የኡዛይ ልጅ ፋልል በማዕዘኑ አንጻር ያለውንና በዘበኞች አደባባይ አጠገብ ከላይኛው የንጉሡ ቤት ወጥቶ የቆመውን ግንብ ሠራ። ከእርሱም በኋላ የፋሮስ ልጅ ፈዳያ ሠራ።'),
  ('4f0bd6bd-df89-5842-a85a-03f97236a02d', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 26, 26, 'ናታኒምም በዖፌል በውኃው በር አንጻር በምሥራቅ በኩል ወጥቶ በቆመው ግንብ አጠገብ እስካለው ስፍራ ድረስ ተቀመጡ።'),
  ('6ce20629-04ca-5914-add1-a6e4dfa20c4f', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 27, 27, 'ከእርሱም በኋላ ቴቁሐውያን ወጥቶ በቆመው በታላቁ ግንብ አንጻር ያለውን እስከ ዖፌል ቅጥር ድረስ ሌላውን ክፍል ሠሩ።'),
  ('01aed47b-53e1-5a05-a7a9-35cb7cdd6cc0', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 28, 28, 'ከፈረሶች በር በላይ ካህናቱ እያንዳንዳቸው በየቤታቸው አንጻር ሠሩ።'),
  ('c87053f5-a7a9-54e4-aa91-2ed20d9fa2de', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 29, 29, 'ከዚያም በኋላ የሄሜር ልጅ ሳዶቅ በቤቱ አንጻር ያለውን ሠራ። ከእርሱም በኋላ የምሥራቁ በር ጠባቂ የሴኬንያ ልጅ ሰማያ ሠራ።'),
  ('166c4acf-b004-5498-a23e-beb793a96b7a', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 30, 30, 'ከእርሱም በኋላ የሰሎምያ ልጅ ሐናንያና የሴሌፍ ስድስተኛው ልጁ ሐኖን ሌላውን ክፍል ሠሩ። ከዚያም በኋላ የበራክያ ልጅ ሜሱላም በሙዳየ ምጽዋቱ አንጻር ያለውን ሠራ።'),
  ('dbe9c7aa-22a5-5bfb-a4e7-ec105c0f1da9', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 31, 31, 'ከእርሱም በኋላ የሰራፊ ልጅ መልክያ እስከ ናታኒምና እስከ ነጋዴዎቹ ቤት ድረስ በሐሜፍቃድ በር አንጻር ያለውን እስከ ማዕዘኑ መውጫ ድረስ ሠራ።'),
  ('8b56a951-6273-5aa2-ab7e-8636fa5feb31', '26418710-63ce-548d-a059-e05b8542317d', 'da89902c-d2a2-5365-a5b1-8e4824d8c596', 32, 32, 'ከማዕዘኑም መውጫ ጀምረው እስከ በጎች በር ድረስ ወርቅ አንጥረኞችና ነጋዴዎች ሠሩ።'),
  ('8b0d4804-0399-5295-af34-a712fae0644a', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 1, 1, 'ሰንባላጥም ቅጥሩን እንደ ሠራን በሰማ ጊዜ እጅግ ተቈጣ፤ ተበሳጨም፤ በአይሁድም ሳቀባቸው።'),
  ('8250061c-6a8c-5467-a558-db2aa5bb5cbc', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 2, 2, 'በወንድሞቹና በሰማርያ ሠራዊትም ፊት፥ “ከተማቸውን የሚሠሩ እነዚህ ደካሞች አይሁድ ኀይላቸው ምንድን ነው? ይተዉላቸዋልን? ይሠዋሉን? በአንድ ቀንስ ይጨርሳሉን? የተቃጠለውንስ ድንጋይ ከፍርስራሹ መልሰው ያድኑታልን?” ብሎ ተናገረ።'),
  ('765e3b56-86c2-5594-a769-9fdae018d43a', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 3, 3, 'አሞናዊውም ጦቢያ ወደ እርሱ ቀርቦ፥ “በድንጋይ በሚሠሩት ቅጥራቸው ላይ ቀበሮ ቢወጣበት ያፈርሰዋል” አለ።'),
  ('aa454e84-4ca8-597e-ad83-b381f590633c', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 4, 4, 'አምላካችን ሆይ፥ ተንቀናልና ስማ፤ ስድባቸውን በራሳቸው ላይ መልስባቸው፤ በምርኮ ሀገር ለብዝበዛ አሳልፈህ ስጣቸው።'),
  ('8d152ec6-ff3f-51ec-a3f5-7053f1d20f4f', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 5, 5, 'በደላቸውንም አትክደን፤ ኀጢአታቸውም ከፊትህ አይደምሰስ፤ በሠራተኞች ፊት አስቈጥተውሃልና።'),
  ('0d74fd55-89d2-58cf-a343-57ff27ec0b77', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 6, 6, 'ቅጥሩንም ሠራን፤ ቅጥሩም ሁሉ እስከ እኩሌታው ድረስ ተጋጠመ፤ ሕዝቡ ከልብ ይሠራ ነበርና።'),
  ('b1324672-4cd5-5212-ac4b-4d7d738b77f4', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 7, 7, 'ሰንባላጥና ጦብያም፥ ዓረባውያንም፥ አሞናውያንም፥ አዛጦናውያንም የኢየሩሳሌም ቅጥር እየታደሰ እንደ ሄደ፥ የፈረሰውም ሊጠገን እንደ ተጀመረ በሰሙ ጊዜ እጅግ ተቈጡ።'),
  ('5a533f5f-cb1d-5d08-a538-235303537256', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 8, 8, 'መጥተውም ኢየሩሳሌምን ይወጉና ያፈርሷት ዘንድ ሁሉም በአንድነት ተሰበሰቡ።'),
  ('5b17671a-5244-5907-a137-cd2df6170b9d', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 9, 9, 'እኛም ወደ አምላካችን ጸለይን፤ ከእነርሱም የተነሣ በአንጻራቸው ተጠባባቂዎችን በሌሊትና በቀን አደረግን።'),
  ('7e45cee6-aabb-5a96-a636-2eb62f80a8ef', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 10, 10, 'ይሁዳም፥ “የተሸካሚዎች ኀይል ደከመ፤ ፍርስራሹም ብዙ ነው፤ ቅጥሩንም እንሠራ ዘንድ አንችልም” አሉ።'),
  ('f913eef5-8767-52d9-a0aa-a8a8a432b98f', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 11, 11, 'ጠላቶቻችንም፥ “ወደ መካከላቸው እስክንመጣና እስክንገድላቸው ድረስ፥ ሥራቸውንም እስክናስተጓጕል ድረስ አያውቁም፤ አያዩም” አሉ።'),
  ('62eff03c-e4bb-5b87-a2db-8b0118791d3c', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 12, 12, 'በአጠገባቸውም የተቀመጡት አይሁድ መጥተው፥ “ከስፍራው ሁሉ ይመጡብናል ብለው ዐሥር ጊዜ ነገሩን።”'),
  ('76f43782-9dea-593d-a9e5-e10432e97b7d', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 13, 13, 'ከቅጥሩም በስተኋላ በኩል ባለው በታችኛው ክፍል በሰዋራ ስፍራ ሰይፋቸውንና ጦራቸውን፥ ቀስታቸውንም አስይዤ ሕዝቡን በየወገናቸው አቆምኋቸው፤'),
  ('f4f6e3dd-1f21-5ae8-a53e-d127f9e58e25', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 14, 14, 'አይችም ተነሣሁ፤ ታላላቆቹንና ሹሞቹንም፥ የቀሩትንም ሕዝብ፥ “አትፍሩአቸው፤ ታላቁንና የተፈራውን አምላካችንን አስቡ፤ ስለ ወንድሞቻችሁም፥ ስለ ወንዶችና ሴቶች ልጆቻችሁም፥ ስለ ሚስቶቻችሁም፥ ስለ ቤቶቻችሁም ተዋጉ” አልኋቸው።'),
  ('0f8df5f4-8fe5-5448-ad4e-51db2b63deda', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 15, 15, 'ጠላቶቻችንም እንደ ዐወቅንባቸው፥ እግዚአብሔርም ምክራቸውን ከንቱ እንዳደረገው ሰሙ፤ እኛም ሁላችን ወደ ቅጥሩ እያንዳንዳችን ወደ ሥራችን ተመለስን።'),
  ('e46f83c5-dd7d-5962-a288-a6058ac5410d', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 16, 16, 'ከዚያም ቀን ጀምሮ እኩሌቶቹ ብላቴኖች ሥራ ይሠሩ ነበር፤ እኩሌቶቹም ጋሻና ጦር፥ ቀስትና ጥሩርም ይዘው በፊትና በኋላ ይጠብቁ ነበር፤ አለቆቹም ከይሁዳ ቤት ሁሉ በኋላ ይቆሙ ነበር።'),
  ('301ac7a6-ec5e-57f7-add1-6d8c7bfbdbbb', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 17, 17, 'ቅጥሩንም የሚሠሩትና ሸክም ተሸካሚዎቹ በአንድ እጃቸው ይሠሩ ነበር፤ በአንድ እጃቸውም የጦር መሣሪያቸውን ይይዙ ነበር።'),
  ('b298ef46-8d81-5968-a891-3c5dd0c0687b', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 18, 18, 'አናጢዎቹም ሁሉ እያንዳንዱ ሰይፉን በወገቡ ታጥቆ ይሠራ ነበር፤ ቀንደ መለከትም የሚነፋ በአጠገቤ ነበረ።'),
  ('eb9312a4-05db-55d2-a0fc-facd80889569', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 19, 19, 'ታላላቆቹንና ሹሞቹን፥ የቀሩትንም ሕዝብ፥ “ሥራው ታላቅና ሰፊ ነው፤ እኛም በቅጥሩ ላይ ተበታትነናል፤ አንዱም ከሁለተኛው ርቆአል፤'),
  ('86c3c2e2-6dac-5f13-a4db-96f09d68ca3e', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 20, 20, 'የቀንደ መለከቱን ድምፅ ወደምትሰሙበት ስፍራ ወደዚያ ወደ እኛ ተሰብሰቡ፤ አምላካችን ስለ እኛ ይዋጋል” አልኋቸው።'),
  ('a90c87ce-dfbf-568e-a460-140ccb13d573', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 21, 21, 'ሥራውንም እንሠራ ነበር፤ ከማለዳ ወገግታም ጀምሮ ከዋክብት እስኪወጡ ድረስ እኩሌቶቹ ጦር ይይዙ ነበር።'),
  ('f59c5829-1e59-5dd5-ac56-fd71e352cd0c', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 22, 22, 'ደግሞም በዚያ ጊዜ ሕዝቡን፥ “ሁላችሁ ከብላቴኖቻችሁ ጋር በኢየሩሳሌም ውስጥ እደሩ፤ በሌሊትም ጠባቂዎች ሁኑልን፤ በቀንም ሥሩ” አልኋቸው።'),
  ('776faba5-65ba-5bc7-af3c-defb85ec4ba1', 'd19254d1-d5a2-59eb-aadf-4d634a01c54b', '8b284fa5-2c6c-545f-aaeb-e4f4ae20cb1e', 23, 23, 'እኔና ወንድሞችም፥ ብላቴኖችም በኋላዬም የነበሩት ጠባቂዎች ልብሳችንን አናወልቅም ነበር። ወደ ውኃም ስንሄድ መሣሪያችንን እንደታጠቅን እንሄድ ነበር።'),
  ('c959b2b9-103f-5c2e-ae24-1f25d1bd00b3', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 1, 1, 'በወንድሞቻቸውም በአይሁድ ላይ ትልቅ የሕዝቡና የሚስቶቻቸው ጩኸት ሆነ።'),
  ('c3d5e0b9-de76-55ca-af8e-a223e7fb33b2', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 2, 2, '“ከወንዶችና ሴቶች ልጆቻችን ጋር ብዙዎች ነን፤ በልተንም በሕይወት እንድንኖር እህልን እንሸምት” የሚሉ ነበሩ።'),
  ('f86127ae-3402-50b4-a3a9-37cb7a50d553', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 3, 3, '“ከራብ የተነሣም እህልን እንሸምት ዘንድ እርሻችንንና ወይናችንን፥ ቤታችንንም አስይዘናል” የሚሉ ነበሩ።'),
  ('5ffcbc9e-a9ec-5c0c-af02-b5f8c3faec0c', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 4, 4, 'ሌሎቹም “ለንጉሡ ግብር እርሻችንንና ወይናችንን አስይዘን ገንዘብ ተበድረናል፤'),
  ('9e0b352a-b5bb-5335-a936-ae21e8799ad5', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 5, 5, 'አሁንም ሥጋችን እንደ ወንድሞቻችን ሥጋ፥ ልጆቻችንም እንደ ልጆቻቸው ናቸው፤ እነሆም ወንዶችና ሴቶች ልጆቻችን ባሪያዎች ይሆኑ ዘንድ ሰጥተናል፤ ከሴቶችም ልጆቻችን ባሪያዎች ሆነው የሚኖሩ አሉ፤ ታላላቆችም እርሻችንንና ወይናችንን ይዘዋልና ልናድናቸው አንችልም” የሚሉ ነበሩ።'),
  ('0c629ea9-a075-59db-a1a4-281881938c51', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 6, 6, 'እኔም ጩኸታቸውንና ይህን ቃል በሰማሁ ጊዜ እጅግ ዐዘንሁ።'),
  ('6af330b8-984a-5a68-ab4f-dcf7e04b59e8', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 7, 7, 'በልቤም አሰብሁ፤ ታላላቆቹንና ሹሞቹንም፥ “ሁላችሁ እያንዳንዳችሁ ወለድ ትወስዳላችሁ” ብዬ ተጣላኋቸው፤ ትልቅም ጉባኤ ሰበሰብሁባቸው።'),
  ('1d2d74c6-c0f6-5822-a6b5-d79bf35d2077', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 8, 8, 'እኔም፥ “ለአሕዛብ የተሸጡትን ወንድሞቻችንን አይሁድን በፈቃዳችን ተቤዠን፤ እናንተስ ወንድሞቻችሁን ትሸጣላችሁን? እነርሱስ ለእኛ የተሸጡ ይሆናሉን?” አልኋቸው። እነርሱም ዝም አሉ፤ መልስም አላገኙም።'),
  ('073f2f94-7777-5dc3-a8eb-64c013c8c47c', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 9, 9, 'ደግሞም አልሁ፥ “የምታደርጉት ነገር መልካም አይደለም፤ ጠላቶቻችን አሕዛብ እንዳይሰድቡን አምላካችንን በመፍራት ትሄዱ ዘንድ አይገባችሁምን?'),
  ('6bb15798-6d41-5ffc-a871-cfe29c75e42e', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 10, 10, 'እኔ ደግሞ፥ ወንድሞችም፥ ብላቴኖችም ገንዘብና እህል ለእነርሱ አበድረናል፤ እባካችሁ፥ ይህን ወለድ እንተውላቸው።'),
  ('f9b7e9f2-80f3-52da-a8be-a38f7b31f9d3', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 11, 11, 'እርሻቸውን፥ የወይናቸውንና የወይራቸውን ቦታ፥ ቤታቸውንም፥ ከእነርሱም የወሰዳችሁትን ገንዘቡንና እህሉን፥ ወይን ጠጁንና ዘይቱን እባካችሁ ዛሬ መልሱላቸው።”'),
  ('06ef0d45-9c78-5d44-adcc-d73dace5a7f8', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 12, 12, 'እነርሱም፥ “እንመልስላቸዋለን፤ ከእነርሱም ምንም አንሻም፤ እንደተናገርህ እንዲሁ እናደርጋለን” አሉ። ካህናቱንም ጠርቼ እንደዚህ ነገር ያደርጉ ዘንድ አማልኋቸው።'),
  ('7358eb34-6944-56df-a0ff-341f73bfa7e2', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 13, 13, 'ደግሞም ልብሴን አራገፍሁና፥ “ይህን ነገር የማያደርገውን ሰው ከቤቱና ከሥራው እንዲሁ እግዚአብሔር ያራግፈው፤ እንዲሁ የተራገፈና ባዶ ይሁን” አልሁ። ጉባኤውም ሁሉ፥ “አሜን” አሉ፤ እግዚአብሔርንም አመሰገኑ፤ ሕዝቡም እንደዚህ ነገር አደረጉ።'),
  ('6ff76d2d-303d-5d08-a598-f822af28f0a0', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 14, 14, 'ንጉሡም በይሁዳ ምድር ላይ አለቃ እሆን ዘንድ ካዘዘኝ ጊዜ ጀምሮ ከንጉሡ ከአርተሰስታ ከሃያኛው ዓመት እስከ ሠላሳ ሁለተኛው ዓመት ድረስ ዐሥራ ሁለት ዓመት ያህል እኔና ወንድሞች ለአለቃ የሚገባውን ቀለብ አልበላንም።'),
  ('bd4b8511-2e5c-56f2-ab50-3b58d839c72b', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 15, 15, 'ከእኔ አስቀድመው የነበሩት አለቆች ግን በሕዝቡ ላይ አክብደው ነበር፤ ስለ እንጀራውና ስለ ወይኑ አርባ ሰቅል ብር ይወስዱ ነበር፤ ሎሌዎቻቸውም ደግሞ በሕዝቡ ላይ ይሰለጥኑ ነበር። እኔ ግን እግዚአብሔርን ስለ ፈራሁ እንዲህ አላደረግሁም።'),
  ('2fb7d747-171c-58ec-a72a-f77c59ea0a29', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 16, 16, 'ደግሞም የቅጥሩን ሥራ ሠራሁ፤ እርሻም አልገዛሁም፤ ብላቴኖችም ሁሉ ወደዚያው ወደ ሥራው ተሰበሰቡ።'),
  ('ecf59b40-e515-5251-a3d2-375cdebdff72', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 17, 17, 'ደግሞም በዙሪያችን ካሉት አሕዛብ ወደ እኛ ከመጡት ሌላ ከአይሁድና ከሹሞቹ መቶ አምሳ ሰዎች በገበታዬ ነበሩ።'),
  ('13091024-1c40-5ced-a27c-f66579746b62', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 18, 18, 'ለአንድ ቀን አንድ በሬና ስድስት የሰቡ በጎች፥ አንድ ፍየልም፥ በዐሥር በዐሥር ቀንም ብዙ ልዩ ልዩ ዓይነት ወይን ጠጅ ይዘጋጅልኝ ነበር፤ ነገር ግን አገዛዝ በሕዝቡ ላይ ከብዶ ነበርና ለአለቃ የሚገባውን ቀለብ አልሻም ነበር።'),
  ('b4ee886e-ef5d-5250-af4c-3cab9601d094', '031363c0-d1dd-54a4-a2b4-5232c29120b0', '120dbc1c-252a-5ec5-ad2d-a89fbfa70738', 19, 19, 'አምላኬ ሆይ፥ ለዚህ ሕዝብ ያደረግሁትን ሁሉ ለበጎነት አስብልኝ።'),
  ('f80c47ce-861c-5aec-a08d-67d2e4310deb', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 1, 1, 'እንዲህም ሆነ፤ ቅጥሩን እንደ ሠራሁ፥ ከፍራሹም አንዳች እንዳልቀረበት ሰንባላጥና ጦቢያ ዓረባዊውም ጌሳም የቀሩትም ጠላቶቻችን ሰሙ፤ ነገር ግን እስከዚያ ጊዜ ድረስ በበሮቹ ውስጥ ሳንቃዎቹን አላቆምሁም ነበር።'),
  ('dd71df26-6ea3-576c-a9c6-9ec1f9fa8409', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 2, 2, 'ሰንባላጥና ጌሳም፥ “መጥተህ በኦኖ ቈላ ውስጥ ባሉት መንደሮች እንገናኝ” ብለው ላኩብኝ፤ ነገር ግን ክፉ ያደርጉብኝ ዘንድ ይመክሩ ነበር።'),
  ('c83fed12-aa97-530a-a4dd-a65aa4e48903', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 3, 3, 'እኔም እንዲህ ስል መልእክተኞችን ላክሁባቸው፥ “እኔ ታላቅ ሥራ እሠራለሁ፤ እወርድም ዘንድ አይቻለኝም። ስለምን ወደ እናንተ በመምጣቴና በመውረዴ ሥራው ይታጐላል? ሥራውን እንደ ፈጸምሁ እመጣለሁ።”'),
  ('ad898183-f169-5881-a086-c961fdd37a21', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 4, 4, 'እንዲህም ቃል አራት ጊዜ ላኩብኝ፤ እኔም እንደ ፊተኛው ቃል መለስሁላቸው።'),
  ('38c9bb1c-9c55-5f1a-a1c6-9a0b78a2ac52', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 5, 5, 'ሰንባላጥም እንደ ፊተኛው ብላቴናውን አምስተኛ ጊዜ ላከብኝ፤ በእጁም ውስጥ እንዲህ የሚል ግልጥ ደብዳቤ ነበረ፦'),
  ('ddbd12cc-57e4-5aa0-a2c4-20178b74bfd2', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 6, 6, '“አንተና አይሁድ ዓመፃ እንድታስቡ፥ ስለዚህም ቅጥሩን እንድትሠራ፥ ንጉሣቸውም ትሆን ዘንድ እንድትወድድ በአሕዛብ ዘንድ ተሰምቶአል።'),
  ('0b3c53a9-2b31-59b0-a559-c1b6ef803171', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 7, 7, 'ደግሞም፦ ንጉሥ በይሁዳ አለ ብለው ስለ አንተ በኢየሩሳሌም ይናገሩ ዘንድ ነቢያትን አቁመሃል፤ አሁንም ለንጉሡ ይህን ቃል ያወሩለታል፤ እንግዲህ መጥተህ በአንድነት እንማከር።”'),
  ('453f2fb2-36d2-51db-aa59-f78d6546a89a', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 8, 8, 'እኔም፥ “አንተ ከልብህ ፈጥረኸዋል እንጂ እንደ ተናገርኸው ነገር አይደለም” ብዬ ላክሁበት።'),
  ('e57245d5-8aeb-52fa-a83d-c19003b4007d', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 9, 9, 'እነርሱም ሁሉ ሥራው እንዳይፈጸም፥ “እጃቸው ይደክማል” ብለው አስፈራሩን፤ ስለዚህም እጆችን አበረታሁ።'),
  ('9a762fe8-bff0-5341-a342-315b0ff0385d', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 10, 10, 'እኔም ወደ መሔጣብኤል ልጅ ወደ ዶልያ ልጅ ወደ ሴሜይ ቤት ገባሁ፤ እርሱም ተዘግቶ ነበርና፥ “በእግዚአብሔር ቤት በመቅደሱ ውስጥ እንግባ፤ የመቅደሱንም ደጆች እንዝጋ፤ እነርሱ በሌሊት ይገድሉህ ዘንድ ይመጣሉና” አለኝ።'),
  ('0114842e-ce9a-5169-af5d-0d29fb76f815', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 11, 11, 'እኔም፥ “እንደ እኔ ያለ ሰው የሸሸና፥ ነፍሱንስ ያድን ዘንድ ወደ መቅደስ የገባ ማን ነው? እኔስ አልገባም” አልሁት።'),
  ('4e775d4b-91ff-5b2f-af2e-d5efa371a19d', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 12, 12, 'እግዚአብሔርም ልኮት እንዳልነበረ፥ በእኔ ላይ ግን ትንቢት እንደ ተናገረ፥ እነሆ፥ ዐወቅሁ፤ ጦብያና ሰንባላጥም ገዝተውት ነበር።'),
  ('ae128d6b-ee7a-5f3b-ac9f-109aba1e51a8', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 13, 13, 'ይህንም ነገር አደርግና እበድል ዘንድ፥ በእኔም ላይ ክፋት እንዲናገሩና እንዲያላግጡ ያስፈራራኝ ዘንድ ተገዝቶ ነበር።'),
  ('79c11e68-b066-5896-afe2-637697102d98', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '66d8c5af-5d20-580d-a872-9076873d2031', 14, 14, 'አምላኬ ሆይ፥ ስለዚህ ሥራቸው ጦቢያንና ሰንባላጥን፥ ነቢይቱንም ኖዓድያን ያስፈራሩኝ ዘንድ የፈለጉትን፥ የቀሩትንም ነቢያት አስብ።'),
  ('0dfdb0a5-e4bf-54e8-ae2d-2e35971eb38b', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '914ea4b2-3be0-5f61-aa7a-f648cb205afb', 1, 15, 'ቅጥሩም በኤሉል ወር በሃያ አምስተኛው ቀን በአምሳ ሁለት ቀን ውስጥ ተጨረሰ።'),
  ('b5a495d0-de2a-533c-adff-3ae4b12dda17', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '914ea4b2-3be0-5f61-aa7a-f648cb205afb', 2, 16, 'እንዲህም ሆነ፤ ጠላቶቻችን ሁሉ ይህን በሰሙ ጊዜ በዙሪያችን የነበሩ አሕዛብ ሁሉ ፈሩ፤ አይተውም እጅግ ተደናገጡ፤ ይህም ሥራ በአምላካችን እንደ ተፈጸመ አወቁ።'),
  ('275a4cd2-201f-5885-ae7a-550b47a878d7', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '914ea4b2-3be0-5f61-aa7a-f648cb205afb', 3, 17, 'በዚያም ወራት ብዙ የይሁዳ አለቆች ወደ ጦብያ ደብዳቤዎችን ይልኩ ነበር፤ የጦብያም ደብዳቤዎች ወደ እነርሱ ይመጡ ነበር።'),
  ('fa8a6207-e4a4-58f4-a0ad-c04943c57fb1', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '914ea4b2-3be0-5f61-aa7a-f648cb205afb', 4, 18, 'ጦብያ የአራሄ ልጅ የሴኬንያ አማች ስለ ነበረ፥ ልጁም ዮሐናን የቤራክያን ልጅ የሜሱላምን ሴት ልጅ ስላገባ፥ በይሁዳ ብዙ ሰዎች ከእርሱ ጋር ተማምለው ነበርና።'),
  ('59b9ca8b-25aa-54f8-a1b4-4f729b3aba30', 'f89b48f7-ce54-58b8-a2ba-34d9ac11157a', '914ea4b2-3be0-5f61-aa7a-f648cb205afb', 5, 19, 'ደግሞም በፊቴ ስለ እርሱ መልካምነት ይናገሩ ነበር፤ የእርሱን ነገር ወደ እኔ ያመጡ ነበር፤ የእኔንም ቃል ወደ እርሱ ይወስዱ ነበር፤ ጦቢያም ሊያስፈራራኝ ደብዳቤዎችን ይልክ ነበር።'),
  ('3ea3de41-de36-5f4f-a657-127b4a144614', 'db40924a-912a-5e3a-a975-efd88cab0184', 'ffd6b93c-7aea-5b5b-a134-6a319212ac87', 1, 1, 'እንዲህም ሆነ፤ ቅጥሩ ከተሠራ በኋላ፥ ሳንቃዎቹን አቆምሁ፤ በረኞቹንና መዘምራኑን፥ ሌዋውያኑንም ሾምሁ፤'),
  ('e18abba7-3286-59b1-adf6-d8beb9ccdc6c', 'db40924a-912a-5e3a-a975-efd88cab0184', 'ffd6b93c-7aea-5b5b-a134-6a319212ac87', 2, 2, 'ወንድሜን ሃናኒንና የግንቡን አለቃ ሐናንያንም በኢየሩሳሌም ላይ ሾምኋቸው፤ እርሱም እውነተኛ ከሌሎቹም ይልቅ እግዚአብሔርን የሚፈራ ሰው ነበረ።'),
  ('6d1feeb3-1378-5bbe-a644-7a36b3321149', 'db40924a-912a-5e3a-a975-efd88cab0184', 'ffd6b93c-7aea-5b5b-a134-6a319212ac87', 3, 3, 'እኔም፥ “ፀሐይ እስኪሞቅ ድረስ የኢየሩሳሌም በሮች አይከፈቱ፤ እነርሱም ቆመው ሳሉ ደጆቹን ይዝጉ፤ ይቈልፉም፤ ከኢየሩሳሌምም ሰዎች አንዳንዱን በየተራው፥ አንዳንዱንም በየቤቱ አንጻር ጠባቂዎችን አስቀምጡ” አልኋቸው።'),
  ('dd1a7622-09e3-505f-a7c0-bb9d696298bb', 'db40924a-912a-5e3a-a975-efd88cab0184', 'ffd6b93c-7aea-5b5b-a134-6a319212ac87', 4, 4, 'ከተማዪቱም ሰፊና ታላቅ ነበረች፤ በውስጥዋ የነበሩ ሕዝብ ግን ጥቂቶች ነበሩ፤ ቤቶቹም ገና አልተሠሩም ነበር።'),
  ('d97e7312-eac8-509b-a441-0955f03247e4', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 1, 5, 'እግዚአብሔርም ታላላቆቹንና ሹሞቹን፥ ሕዝቡንም ሰብስቤ በየትውልዳቸው እቈጥራቸው ዘንድ ልቤን አነሣሣ፤ አስቀድመው የመጡትንም ሰዎች የትውልድ መጽሐፋቸውን አገኘሁ፤ በእርሱም እንደዚህ ተጽፎ አገኘሁ።'),
  ('ca9b01d1-5a23-55a6-a82c-ab15c61e1051', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 2, 6, 'የባቢሎን ንጉሥ ናቡከደነፆር ከማረካቸው ምርኮኞች ወደ ኢየሩሳሌምና ወደ ይሁዳ፥ ወደ እየከተማቸው የተመለሱት የሀገር ልጆች እነዚህ ናቸው።'),
  ('4fc76752-a015-539a-a5c8-07d3a52e73d9', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 3, 7, 'ከዘሩባቤል፥ ከኢያሱ፥ ከነህምያ፥ ከአዛርያስ፥ ከረዓምያ፥ ከሄሜኔስ፥ ከመርዶክዮስ፥ ከበልሰማ፥ ከሚስፌሬት፥ ከዕዝራ፥ ከበጉዋይ፥ ከነሑም፥ ከበዓና፥ ከመስፈር ጋር መጡ። ከእስራኤልም ሕዝብ የወንዶች ቍጥር ይህ ነው፥'),
  ('9b535b10-17d3-5bd0-a251-96d440827d7d', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 4, 8, 'የፋሮስ ልጆች ሁለት ሺህ አንድ መቶ ሰባ ሁለት።'),
