  ('e947cb61-b5f1-52d4-a64c-28f8b2062ba4', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 31, 35, 'የኤራም ልጆች ሦስት መቶ ሃያ።'),
