  ('f26b3eed-4be8-58c6-acf9-acf81725f2ec', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 33, 37, 'የሎድና ሐዲድ የሐኖም ልጆች ሰባት መቶ ሃያ አንድ።'),
  ('669e558c-8fb3-5065-a025-700680822553', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 34, 38, 'የሴናዓ ልጆች ሦስት ሺህ ዘጠኝ መቶ ሠላሳ።'),
  ('a4fbe4de-f63c-5a75-a9b8-98f8a24a1fbb', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 35, 39, 'ካህናቱ ከኢያሱ ወገን፦ የዮዳሔ ልጆች ዘጠኝ መቶ ሰባ ሦስት።'),
  ('5352df21-3c72-5fc1-a14b-9deef3db464b', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 36, 40, 'የኤሜር ልጆች ሺህ አምሳ ሁለት።'),
