  ('4e3a00b6-1b9b-5697-aae0-fb36148410c9', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 38, 42, 'የሐራም ልጆች ሺህ ዐሥራ ሰባት።'),
