  ('0a979081-d95a-5ea4-abb0-cb6bd0ddeb1c', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 40, 44, 'መዘምራኑ የአሳፍ ልጆች መቶ አርባ ስምንት።'),
  ('5a07966d-43d7-5185-a14a-d9f201d75e83', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 41, 45, 'በረኞቹ የሴሎምያ ልጆች፥ የአጤር ልጆች፥ የጤልማና ልጆች፥ የዓቁብ ልጆች፥ የሐጢጣ ልጆች፥ የሶባይ ልጆች መቶ አርባ ስምንት።'),
  ('4b2b51e2-fed1-5dda-a90e-e1abc8ff1046', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 42, 46, 'ናታኒም የሲአ ልጆች፥ የሐሡፋ ልጆች፥ የጠብዓት ልጆች፤'),
  ('adc89495-e140-5579-a0e9-0abb564d7f68', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 43, 47, 'የቄራስ ልጆች፥ የአሲያ ልጆች፥ የፋዶን ልጆች፤'),
  ('cb7a334b-1f10-52d4-ac99-857b64bb52d8', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 44, 48, 'የልባና ልጆች፥ የአጋባ ልጆች፥ የሰልማይ ልጆች፤'),
  ('6e62c0fd-96df-57bb-a75d-66725df82580', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 45, 49, 'የሐናን ልጆች፥ የጌዴል ልጆች፥ የጋኤር ልጆች፤'),
  ('94bac78c-ad5b-5818-a325-be52b258cbc3', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 46, 50, 'የርአያ ልጆች፥ የረአሶን ልጆች፥ የኔቆዳ ልጆች፤'),
  ('60f947b4-61d3-5be8-a04f-2eee09573e36', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 47, 51, 'የጋሴም ልጆች፥ የኡዚ ልጆች፥ የፋሴሓ ልጆች፤'),
  ('9d0e06f8-d243-5a37-a5ff-bf99a0ddb4e1', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 48, 52, 'የቤሳይ ልጆች፥ የምዑናውያን ልጆች፥ የኔፋሴስም ልጆች፤'),
  ('090f6c9f-6c5b-55db-a787-59c6fb3f6e3a', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 49, 53, 'የበቅቡቅ ልጆች፥ የሐቀፋ ልጆች፥ የሐሩር ልጆች፤'),
  ('09a73265-233d-5beb-ac4f-5f660ac3746a', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 50, 54, 'የበስሎት ልጆች፥ የምሒዳ ልጆች፥ የሐርሳ ልጆች፤'),
  ('20b34312-5b76-5b2d-ab1b-0d6c6ba4685e', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 51, 55, 'የበርቆስ ልጆች፥ የሲሣራ ልጆች፥ የታማህ ልጆች፥'),
  ('e2ef9cc0-4405-5d7a-ac2c-70d4ca8f1f56', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 52, 56, 'የነስያ ልጆች፥ የሐጤፋ ልጆች።'),
  ('8a19059b-e852-52ee-a756-2dfa1d51fafa', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 53, 57, 'የሰሎሞን አገልጋዮች ልጆች፤ የሦጠይ ልጆች፥ የሰፋሬት ልጆች፥ የፈሪዳ ልጆች፥'),
  ('38e3de7a-aecc-5c64-a73f-e02faa84d873', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 54, 58, 'የየዕላ ልጆች፥ የደርቆን ልጆች፥ የጌዴል ልጆች፤'),
  ('24ff1ff7-6a49-508c-aa9f-38b7f6e893a9', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 55, 59, 'የሰፋጥያስ ልጆች፥ የሐጢል ልጆች፥ የፈከራት ልጆች፥ የሰባይም ልጆች፥ የአሞን ልጆች።'),
  ('6dd277bb-404c-5021-ae6c-e3d9f38856f0', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 56, 60, 'ናታኒም ሁሉና የሰሎሞን አገልጋዮች ልጆች ሦስት መቶ ዘጠና ሁለት ነበሩ።'),
  ('12e53863-f978-5847-a4b2-3d27a49a92a0', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 57, 61, 'ከቲልሜል፥ ከቲላሬስ፥ ከኪሩብ፥ ከአዶን፥ ከኢሜር የወጡ እነዚህ ናቸው፤ ነገር ግን የአባቶቻቸውን ቤቶችና ዘራቸውን ወይም ከእስራኤል ወገን መሆናቸውን ያስታውቁ ዘንድ አልቻሉም፤'),
  ('9c54024a-f84e-5bab-a665-2e2730dafd69', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 58, 62, 'የዳላያ ልጆች፥ የጦብያ ልጆች፥ የኔቆዳ ልጆች ስድስት መቶ አርባ ሁለት።'),
  ('b8a05a8a-1843-5221-ae36-3e02498e9a97', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 59, 63, 'ከካህናቱም የአብያ ልጆች፥ የአቆስ ልጆች፥ ከገለዓዳዊው ከቤርዜሊ ልጆች ሚስት ያገባ፥ በስሙም የተጠራ የቤርዜሊ ልጆች።'),
  ('61500af9-e91d-513f-ae42-9ba33ab4dc9e', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 60, 64, 'እነዚህ በትውልድ መጽሐፍ ትውልዳቸውን ፈለጉ፤ ነገር ግን አልተገኘም፤ ከክህነትም ተከለከሉ።'),
  ('aadb385e-84b2-5aa3-a869-5fc4b7a89674', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 61, 65, 'ሐቴርሰታም፥ “በኡሪምና በቱሚም የሚፈርድ ካህን እስኪነሣ ድረስ ከተቀደሰው ነገር አትበሉም” አላቸው።'),
  ('bbb80fd0-29d8-52c1-aa51-0db87c7e436d', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 62, 66, 'ጉባኤውም ሁሉ አርባ ሁለት ሺህ ሦስት መቶ ስድሳ ነበሩ፤'),
  ('4b4b8830-fe42-57b6-af12-ad7c837a6b7d', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 63, 67, 'ይኸውም ሰባት ሺህ ሦስት መቶ ሠላሳ ሰባት ከነበሩ ከሎሌዎቻቸውና ከገረዶቻቸው ሌላ ሁለት መቶም አርባ አምስት ወንዶች መዘምራንና ሴቶች መዘምራት ነበሩአቸው።'),
  ('95293bcd-58f6-58b0-ad27-013bfc518c37', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 64, 68, 'ፈረሶቻቸውም ሰባት መቶ ሠላሳ ስድስት፥ በቅሎዎቻቸውም ሁለት መቶ አርባ አምስት፤'),
  ('da577d9e-cf39-5265-a4cd-bb8921cc852e', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 65, 69, 'ግመሎቻቸውም አራት መቶ ሠላሳ አምስት፥ አህዮቻቸውም ስድስት ሺህ ሰባት መቶ ሃያ ነበሩ።'),
  ('cdee850b-30aa-58e4-ac18-9d2603e0ea8c', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 66, 70, 'ከአባቶች ቤቶች አለቆችም ስለ ሥራው ስጦታ ሰጡ። ሐቴርሰታም አንድ ሺህ የወርቅ ዳሪክ፥ አምሳም ድስቶች፥ አምስት መቶ ሠላሳም የካህናት ልብስ በቤተ መዛግብት ውስጥ ሰጠ።'),
  ('aadf5fea-7ca9-5734-a4f2-546db4346995', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 67, 71, 'ከአባቶች ቤቶች አለቆችም ዐያሌዎቹ በሥራው ቤተ መዛግብት ውስጥ ሃያ ሺህ የወርቅ ዳሪክ፥ ሁለት ሺህ ሁለት መቶም ምናን ብር ሰጡ።'),
  ('0d2415d0-d09c-5f7d-a2b3-11ab5882eee6', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 68, 72, 'የቀሩትም ሕዝብ የሰጡት ሃያ ሺህ የወርቅ ዳሪክና ሁለት ሺህ ምናን ብር፥ ስድሳ ሰባትም የካህናት ልብስ ነበረ።'),
  ('adcbb5d9-999b-53f6-a457-99f50fbfcb6c', 'db40924a-912a-5e3a-a975-efd88cab0184', '6fccf6b4-45f9-544e-a18f-1bca91a11730', 69, 73, 'ካህናቱና ሌዋውያኑም፥ በረኞቹና መዘምራኑም፥ ከሕዝቡም ዐያሌዎቹ፥ ናታኒምም፥ እስራኤልም ሁሉ በከተሞቻቸው ተቀመጡ።'),
  ('85ed6539-d425-51fd-abfb-fd23fefa7694', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 1, 1, 'ሰባተኛውም ወር በደረሰ ጊዜ የእስራኤል ልጆች በከተሞቻቸው ነበሩ። ሕዝቡም ሁሉ በውኃው በር ፊት ወዳለው አደባባይ እንደ አንድ ሰው ሆነው ተሰበሰቡ፤ እግዚአብሔርም ለእስራኤል ያዘዘውን የሙሴን ሕግ መጽሐፍ ያመጣ ዘንድ ጸሓፊውን ዕዝራን ነገሩት።'),
  ('31d15740-f59e-511c-a5ac-fb447e200f2e', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 2, 2, 'ካህኑም ዕዝራ በሰባተኛው ወር በመጀመሪያው ቀን ሕጉን በወንዶችና በሴቶች ጉባኤ፥ አስተውለውም በሚሰሙት ሁሉ ፊት አመጣው።'),
  ('a938403d-62c7-5e7b-a32a-43b9fc290ba3', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 3, 3, 'በውኃውም በር ፊት ባለው አደባባይ ላይ ቆሞ፥ በወንዶችና በሴቶች በሚያስተውሉትም ፊት፥ ከማለዳ ጀምሮ እስከ ቀትር ድረስ አነበበው፤ የሕዝቡም ሁሉ ጆሮ የሕጉን መጽሐፍ ለመስማት ያደምጥ ነበር።'),
  ('dd6e079f-067d-58b1-a4a0-5412bd3a2623', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 4, 4, 'ጸሓፊውም ዕዝራ ስለዚህ ነገር በተሠራ በዕንጨት መረባርብ ላይ ቆሞ ነበር፤ በአጠገቡ መቲትያ፥ ሰምያ፥ ሐናንያ፤ ኦርያ፥ ሕልቅያ፥ መዕሢያ በቀኙ በኩል፥ ፈድያ፥ ሚሳኤል፥ ሚልክያ፥ ሐሱም፥ ሐስበዳና፥ ዘካርያስ፥ ሜሱላም በግራው በኩል ቆመው ነበር።'),
  ('c7f583fb-6b69-503e-ade0-b8ac62fe4d79', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 5, 5, 'ዕዝራም የሕዝቡ ሁሉ የበላይ ነበረና በሕዝቡ ሁሉ ፊት መጽሐፉን ገለጠ፤ በገለጠውም ጊዜ ሕዝቡ ሁሉ ቆሙ።'),
  ('1e15522b-b5c7-5f6e-acb3-ae675ddca709', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 6, 6, 'ዕዝራም ታላቁን አምላክ እግዚአብሔርን አመሰገነ፤ ሕዝቡም ሁሉ እጃቸውን እየዘረጉ፥ “አሜን፥ አሜን” ብለው መለሱ። ራሳቸውንም አዘነበሉ፤ በግንባራቸውም ወደ ምድር ተደፍተው ለእግዚአብሔር ሰገዱ።'),
  ('b69bb8a1-7f5c-5cb9-a884-791d1f6d6a19', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 7, 7, 'ደግሞ ኢያሱና ባኒ፥ ሰራብያ፥ ያሚን፥ ዓቁብ፥ ሳባታይ፥ ሆዲያ፥ መዕሤያ፥ ቆሊጣ፥ ዓዛርያ፥ ኢዮዛባድ፥ ሐናን፥ ፌልዕያ፥ ሌዋውያኑም ሕጉን ለሕዝቡ ያስተምሩ ነበር፤ ሕዝቡም በየስፍራቸው ቆመው ነበር።'),
  ('00b51ae8-e9f8-57ef-a6f7-bd02fea5b082', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 8, 8, 'የእግዚአብሔርንም ሕግ መጽሐፍ አነበቡ፤ ዕዝራም እግዚአብሔርን ማወቅ ያስተምርና ያስታውቅ ነበር፤ ሕዝቡም የሚነበበውን ያስተውሉ ነበር።'),
  ('2176fba7-073a-5a54-af7f-e4663c3b969d', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 9, 9, 'ሕቴርሰታ ነህምያም፥ ጸሓፊውም ካህኑ ዕዝራ፥ ሕዝቡንም የሚያስተምሩ ሌዋውያን ሕዝቡን ሁሉ፥ “ዛሬ ለአምላካችን ለእግዚአብሔር የተቀደሰ ቀን ነው፤ አትዘኑ፤ አታልቅሱም” አሉአቸው፤ ሕዝቡ ሁሉ የሕጉን ቃል በሰሙ ጊዜ ያለቅሱ ነበርና።'),
  ('c87c234a-935e-5456-a7df-944bb500f531', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 10, 10, 'እርሱም፥ “ሂዱ፤ የሰባውንም ብሉ፤ ጣፋጩንም ጠጡ፤ ለእነዚያም ምንም ለሌላቸው እድል ፈንታቸውን ላኩ፤ ዛሬ ለጌታችን የተቀደሰ ቀን ነው፤ እግዚአብሔርም ኀይላችን ነውና አትዘኑ” አላቸው።'),
  ('32aa59d7-50bb-5bb3-a11b-79038b1d50ca', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 11, 11, 'ሌዋውያንም “ቀኑ የተቀደሰ ነውና ዝም በሉ፤ አትዘኑም” እያሉ ሕዝቡን ሁሉ ጸጥ ያደርጉ ነበር።'),
  ('d48dbc29-52f7-5458-a44e-b78c27857384', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 12, 12, 'ሕዝቡም ሁሉ የተነገራቸውን ቃል አስተውለዋልና ሊበሉና ሊጠጡ፥ እድል ፈንታም ሊልኩ፥ ደስታም ሊያደርጉ ሄዱ።'),
  ('95eeba50-043a-52b9-aa89-0df8c83dc60e', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 13, 13, 'በሁለተኛውም ቀን ከሕዝቡ ሁሉ የአባቶች ቤቶች አለቆች፥ ካህናቱም፥ ሌዋውያኑም የሕጉን ቃል ይተረጕምላቸው ዘንድ ወደ ጸሓፊው ወደ ዕዝራ ተሰበሰቡ።'),
  ('0498f840-bad7-596f-a683-0c102a8d0d2d', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 14, 14, 'በሰባተኛውም ወር ባለው በዓል የእስራኤል ልጆች በዳስ ይቀመጡ ዘንድ በከተሞቻቸውና በኢየሩሳሌምም ይናገሩና ያውጁ ዘንድ እግዚአብሔር በሙሴ እጅ እንዳዘዘ በሕጉ ውስጥ ተጽፎ አገኙ።'),
  ('eec76865-6807-5737-adde-1c709d0a725b', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 15, 15, 'ዕዝራም አላቸው፥ “ወደ ተራራ ሂዱ፤ የዘይትና የበረሃ ወይራ፥ የባርሰነትም፥ የዘንባባም፥ የለመለመውንም ዛፍ ቅርንጫፍ አምጡ፤ እንደ ተጻፈውም ዳሶችን ሥሩ።”'),
  ('a4bcd9a0-fa14-5a3e-a4a5-8648de0e443f', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 16, 16, 'ሕዝቡም ወጥተው አመጡ፤ እያንዳንዱም በቤቱ ሰገነት ላይ፥ በአደባባዩም ላይ፥ በእግዚአብሔርም ቤት አደባባይ ላይ፥ በውኃውም በር አደባባይና በኤፍሬም በር አደባባይ ላይ ዳስ ሠሩ።'),
  ('9cf5df2a-4151-56cc-a059-45f1768e820a', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 17, 17, 'ከምርኮም የተመለሱት ማኅበር ሁሉ ዳስ ሠሩ፤ በዳሱም ውስጥ ተቀመጡ። ከነዌም ልጅ ከኢያሱ ዘመን ጀምሮ እስከዚያ ቀን ድረስ የእስራኤል ልጆች እንዲህ ያለ አላደረጉም ነበር። እጅግም ታላቅ ደስታ ሆነ።'),
  ('17b7bd5f-0819-586c-a770-cda0f05dad30', 'f102761d-5a0e-529e-a648-a6dceb7862c5', '696fcb0a-83d5-5b7d-ad15-a249d197556f', 18, 18, 'ከመጀመሪያውም ቀን ጀምሮ እስከ መጨረሻው ቀን ድረስ ዕለት ዕለት የእግዚአብሔርን ሕግ መጽሐፍ ያነብብ ነበር። በዓሉንም ሰባት ቀን ያህል አደረጉ፤ በስምንተኛውም ቀን እንደ ሕጋቸው ወጡ።'),
  ('e33c1ce0-4bd4-506c-ae9c-25dcdf605379', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '5281b554-57ff-501f-a463-8c23e0f4d8a6', 1, 1, 'በዚህም ወር በሃያ አራተኛው ቀን የእስራኤል ልጆች ጾመው፥ ማቅም ለብሰው፥ በራሳቸውም ላይ ትቢያ ነስንሰው ተሰበሰቡ።'),
  ('ef2be8ef-bf60-53b4-a670-eb410234e720', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '5281b554-57ff-501f-a463-8c23e0f4d8a6', 2, 2, 'የእስራኤልም ልጆች ከባዕድ ሕዝብ ሁሉ ራሳቸውን ለዩ፤ ቆመውም ኀጢአታቸውንና የአባቶቻቸውን ኀጢአት ተናዘዙ።'),
  ('9250fe77-7adb-5bc8-a9ab-1a694c8b851c', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '5281b554-57ff-501f-a463-8c23e0f4d8a6', 3, 3, 'በየስፍራቸውም ቆመው የአምላካቸውን የእግዚአብሔርን የሕግ መጽሐፍ አነበቡ፤ ለእግዚአብሔርም ተናዘዙ፤ ለአምላካቸውም ለእግዚአብሔር ሰገዱ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('9ee9b24e-48e0-5dc0-acb6-aa4141531128', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '5281b554-57ff-501f-a463-8c23e0f4d8a6', 4, 4, 'ሌዋውያኑም ኢያሱና የቀድምኤል ልጆች፥ የሰራብያ ልጅ ሴኬንያ፥ የከናኒ ልጆችም በደረጃዎች ላይ ቆመው ወደ አምላካቸው ወደ እግዚአብሔር በታላቅ ድምፅ ጮኹ።'),
  ('dd38f852-4073-57e3-a5c4-5733d56ea498', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '5281b554-57ff-501f-a463-8c23e0f4d8a6', 5, 5, 'ሌዋውያኑም ኢያሱና ቀድምኤል፥ እንዲህ አሉ፥ “ቆማችሁ ከዘለዓለም እስከ ዘለዓለም አምላካችንን እግዚአብሔርን አመስግኑ። የከበረ ስሙንም አመስግኑ፤ በበረከትና በምስጋናም ሁሉ ላይ ከፍ ከፍ አድርጉት።”'),
  ('9e5893a1-3708-54d9-ac3f-d46333d59c70', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 1, 6, 'ዕዝራም እንዲህ አለ፥ “አንተ ብቻ እግዚአብሔር ነህ፤ ሰማዩንና የሰማያት ሰማይን፥ ሠራዊታቸውንም ሁሉ፥ ምድርንና በእርስዋ ላይ ያሉትን ሁሉ፥ ባሕሮቹንና በእነርሱ ውስጥ ያለውን ሁሉ ፈጥረሃል፤ ሁሉንም ሕያው አድርገኸዋል፤ የሰማዩም ሠራዊት ለአንተ ይሰግዳሉ።'),
  ('b2874bc9-72ca-56d0-abc9-23f11fb14ce9', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 2, 7, 'አንተ እግዚአብሔር አምላክ ነህ፤ አብራምን መረጥህ፤ ከዑር ከላውዴዎንም አወጣኸው፤ ስሙንም አብርሃም አልኸው፤'),
  ('378ff5e4-4aba-57e5-a27f-54c41607bec9', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 3, 8, 'ልቡም በፊትህ የታመነ ሆኖ አገኘኸው፤ የከነዓናዊውንና የኬጤዎናዊውን፥ የአሞሬዎናዊውንም፥ የፌርዜዎናዊውንም፥ የኢያቡሴዎናዊውንም፥ የጌርጌሴዎናዊውንም ምድር ለእርሱና ለዘሩ ትሰጥ ዘንድ ከእርሱ ጋር ቃል ኪዳን አደረግህ፤ አንተም ጻድቅ ነህና ቃልህን አጸናህ።'),
  ('b32d9bd1-4f70-552c-a265-8ba4aa4cf1e1', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 4, 9, '“በግብጽም ሳሉ የአባቶቻችንን መከራ አየህ፤ በኤርትራ ባሕርም ሳሉ ጩኸታቸውን ሰማህ፤'),
  ('6cfd67ae-8ccf-5bfc-a70b-195529a229a8', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 5, 10, 'እንደ ታበዩባቸውም ዐውቀህ ነበርና በፈርዖንና በባሪያዎቹ ሁሉ፥ በምድሩም ሕዝብ ሁሉ ላይ ምልክትንና ተአምራትን አሳየህ፤ ዛሬም እንደ ሆነው ስምህን አስጠራህ።'),
  ('09695db8-5bc0-5856-ae6a-29ed03132bad', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 6, 11, 'ከፊታቸውም ባሕሩን ከፈልህ፤ በባሕሩም መካከል በደረቅ ዐለፉ፤ የተከተሉአቸውን ግን ድንጋይ በጥልቅ ውኃ እንዲጣል በቀላይ ውስጥ ጣልሃቸው።'),
  ('4f10e637-cd5b-55c7-a170-654255a8a7e6', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 7, 12, 'የሚሄዱበትንም መንገድ ታበራላቸው ዘንድ ቀን በደመና ዐምድ፥ ሌሊትም በእሳት ዐምድ መራሃቸው።'),
  ('78367f20-66a7-5d22-a44b-d1fafbba5d0b', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 8, 13, 'ወደ ሲናም ተራራ ወረድህ፤ ከሰማይም ተናገርሃቸው፤ ቅኑን ፍርድና እውነቱን ሕግ፥ መልካሙንም ሥርዐትና ትእዛዝ ሰጠሃቸው፤'),
  ('5d75d87a-ba80-5209-a0b2-0a03b033d82c', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 9, 14, 'የተቀደሰውንም ሰንበትህን አስታወቅሃቸው፤ ትእዛዝንና ሥርዐትን፥ ሕግንም በባሪያህ በሙሴ እጅ አዘዝሃቸው።'),
  ('bfc85221-1224-537d-a1f0-c46197abb24f', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 10, 15, 'ለራባቸውም ከሰማይ እንጀራን ሰጠሃቸው፤ ለጥማታቸውም ከዓለቱ ውኃን አወጣህላቸው፤ ትሰጣቸውም ዘንድ እጅህን የዘረጋህባትን ምድር ገብተው ይወርሷት ዘንድ አዘዝሃቸው።'),
  ('f40eb076-bf42-565c-a59c-0b55f14ecf13', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 11, 16, '“ነገር ግን እነርሱና አባቶቻችን ታበዩ፤ አንገታቸውንም አደነደኑ፤ ትእዛዝህንም አልሰሙም፥'),
  ('a498fa59-a07e-583c-adce-18fd376b1c02', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 12, 17, 'ለመስማትም እንቢ አሉ፤ ያደረግህላቸውንም ተአምራት አላሰቡም፤ አንገታቸውንም አደነደኑ፤ ለባርነታቸውም ወደ ግብፅ ይመለሱ ዘንድ አለቃን ሾሙ፤ አንተ ግን መሓሪና ይቅር ባይ አምላክ፥ ለቍጣም የምትዘገይ፥ ምሕረትንም የምታበዛ ነህ፤ አልተውሃቸውም።'),
  ('25bf6881-fc43-53c9-a6a6-e377239cb3f1', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 13, 18, 'ዳግመኛም ቀልጦ የተሠራውን እንቦሳ አድርገው፦ ‘ከግብፅ ያወጡን አምላኮቻችን እሊህ ናቸው’ አሉ፤ እጅግም አስቈጡህ፤'),
  ('5641b5f8-669f-53ff-a864-5669a2260058', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 14, 19, 'አንተ ግን ምሕረትህ ብዙ ነውና በምድረ በዳ አልተውሃቸውም፤ በመንገድም ይመራቸው ዘንድ የደመና ዓምድን በቀን፥ የሚሄዱበትንም መንገድ ያበራላቸው ዘንድ የእሳት ዓምድን በሌሊት ከእነርሱ አላራቅህም።'),
  ('2fabeb91-e3db-5bf9-ac96-10a6f108a40a', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 15, 20, 'ያስተምራቸውም ዘንድ መልካሙን መንፈስህን ሰጠሃቸው፤ መናህንም ከአፋቸው አልከለከልህም፤ ለጥማታቸውም ውኃን ሰጠሃቸው።'),
  ('9b45b5af-ade5-551f-a22e-ede9e025df36', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 16, 21, 'አርባ ዓመትም በምድረ በዳ መገብሃቸው፤ ምንም አላሳጣሃቸውም፤ ልብሳቸውም አላረጀም፤ እግራቸውም አላበጠም።'),
  ('d8d4c393-0470-5a96-a411-98b2af73dfae', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 17, 22, '“መንግሥታትንና አሕዛብን ዕድል ፈንታ አድርገህ ሰጠሃቸው፤ የሐሴቦንን ንጉሥ የሴዎንን ምድር፥ የባሳንንም ንጉሥ የዐግን ምድር ወረሱ።'),
  ('e003efaf-88cc-5bd4-ab38-c004684f84ec', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 18, 23, 'ልጆቻቸውንም እንደ ሰማይ ከዋክብት አበዛህ፤ ለአባቶቻቸውም ወደ ተናገርህላቸው ምድር አገባሃቸው።'),
  ('72370891-b595-503c-a984-a8709d91a49b', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 19, 24, 'እነርሱም ወረሱአት፤ በከነዓን ምድር የሚኖሩትንም ሰዎች በፊታቸው አጠፋሃቸው፤ የሚወድዱትንም ነገር ያደርጉባቸው ዘንድ እነርሱንና ነገሥታቶቻቸውን፥ የምድሩንም አሕዛብ በእጃቸው አሳልፈህ ሰጠሃቸው።'),
  ('d091e9a9-56d4-5d0e-abbb-0196869e58c1', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 20, 25, 'ምሽጎቹንም ከተሞች፥ መልካምን ነገር የሞሉትን ቤቶች፥ የተማሱትንም ጕድጓዶች፥ የወይኖቹንና የወይራዎቹን ቦታዎች፥ ብዙዎቹንም የፍሬ ዛፎች ወረሱ፤ በሉም፤ ጠገቡም፤ ወፈሩም፤ በታላቅ በጎነትህም ደስ አላቸው።'),
  ('7366f1f2-4db7-5d0c-aab3-ee9dffe39f5b', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 21, 26, '“ነገር ግን ተመልሰው ዐመፁብህ፤ ሕግህንም ወደ ኋላቸው ጣሉት፤ ወደ አንተም ይመለሱ ዘንድ የመሰከሩባቸውን ነቢያትህን ገደሉ፤ እጅግም አስቈጡህ።'),
  ('a2487d0d-0717-529c-a298-93f2941f9601', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 22, 27, 'ስለዚህ በሚያሠቃዩአቸው ሰዎች እጅ አሳልፈህ ሰጠሃቸው፤ አስጨነቋቸውም፤ በመከራቸውም ጊዜ ወደ አንተ ጮኹ፤ ከሰማይም ሰማሃቸው፤ እንደ ምሕረትህም ብዛት ታዳጊዎችን ሰጠሃቸው፤ ከሚያሠቃዩአቸውም እጅ አዳንሃቸው።'),
  ('624bb780-c6db-5d11-ac19-6db1935d1355', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 23, 28, 'ባረፉም ጊዜ ተመልሰው በፊትህ ክፉ አደረጉ፤ በጠላቶቻቸውም እጅ ተውሃቸው፤ ገዙአቸውም፤ ተመልሰውም ወደ አንተ በጮኹ ጊዜ ከሰማይ ሰማሃቸው፤ እንደ ምሕረትህም ብዛት ታደግሃቸው፤'),
  ('d58fbef5-8b08-5d65-ada6-21f3f3b19c8f', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 24, 29, 'ወደ ሕግህም ትመልሳቸው ዘንድ አስመሰከርህባቸው፤ ነገር ግን አልሰሙህም፤ ሰውም ባደረገው ጊዜ በሕይወት የሚኖርበትን ትእዛዝህንና ፍርድህን ተላለፉ፤ ጀርባቸውን ሰጡ፤ አንገታቸውንም አደነደኑ፤ አልሰሙምም።'),
  ('d9a3bd93-377e-5178-a61f-17e7d4243e19', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 25, 30, 'ነገር ግን ብዙ ዓመታት ታገሥሃቸው፤ በነቢያትህም እጅ በመንፈስህ መሰከርህባቸው፤ አላደመጡም፤ ስለዚህም በምድር አሕዛብ እጅ አሳልፈህ ሰጠሃቸው።'),
  ('072468e0-4ea6-5676-a932-5ef1fd27485a', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 26, 31, 'ነገር ግን አንተ ኀያል፥ ቸርና መሓሪ አምላክ ነህና በምሕረትህ ብዛት ፈጽመህ አላጠፋሃቸውም፤ አልተውሃቸውምም።'),
  ('80ec9377-a59b-5668-ab86-8c961839143b', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 27, 32, '“አሁንም አምላካችን ሆይ፥ ቃል ኪዳንንና ምሕረትን የምትጠብቅ ታላቅና ኀያል ጽኑዕና የተፈራኸው አምላክ ሆይ፥ ከአሦር ነገሥታት ዘመን ጀምሮ እስከ ዛሬ በእኛና በነገሥታቶቻችን፥ በአለቆቻችንም፥ በካህናቶቻችንም፥ በነቢያቶቻችንም፥ በአባቶቻችንም፥ በሕዝብህ ሁሉ ላይ የደረሰው መከራ ሁሉ በፊትህ ጥቂት መስሎ አይታይህ።'),
  ('2d2e4f99-4387-51f1-a4fa-20335af1ca9c', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 28, 33, 'በደረሰብንም ነገር ሁሉ አንተ ጻድቅ ነህ፤ አንተ እውነት አድርገሃልና፥ እኛም እጅግ በድለናልና።'),
  ('165d3a9d-fcf0-5c4f-ac3d-c0665ca8cb71', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 29, 34, 'ነገሥታቶቻችን፥ አለቆቻችንም፥ ካህናቶቻችንም፥ አባቶቻችንም ሕግህን አልጠበቁም፤ ትእዛዝህንና የመሰከርህባቸውን ምስክርህንም አልሰሙም።'),
  ('537808a8-8ec4-5112-a90d-5b5f122b573f', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 30, 35, 'በመንግሥትህም በሰጠሃቸው ታላቅ በጎነትህ፥ በፊታቸውም በሰጠሃቸው በሰፊውና በሰባው ምድር አልተገዙልህም፤ ከክፉም ሥራቸው አልተመለሱም።'),
  ('0dd78af5-73cf-5fed-ac3b-0ee708df6b68', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 31, 36, 'እነሆ፥ ዛሬ ባሪያዎች ነን፤ ፍሬዋንና በረከቷን ይበሉ ዘንድ ለአባቶቻችን በሰጠሃት ምድር እነሆ፥ በእርስዋ ባሪያዎች ነን፥'),
  ('3015f1fd-b62f-58ff-abf2-2884243bbd2c', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 32, 37, 'ስለ ኀጢአታችንም ለሾምህብን ነገሥታት በረከቷን ታበዛለች፤ ሰውነታችንንም ይገዛሉ፤ በእንስሶቻችንም የሚወድዱትን ያደርጋሉ፤ እኛም በጽኑ መከራ ላይ ነን።'),
  ('fe1e9ce8-6cd6-5b12-a8e6-ff6191ec5d70', 'bf058d35-483a-5cbb-ab71-e83785e765b5', '14a0cca7-7352-518c-a2f5-e3fcca202d55', 33, 38, 'ስለዚህም ሁሉ የታመነውን ቃል ኪዳን አድርገን እንጽፋለን፤ አለቆቻችንም፥ ሌዋውያኖቻችንም፥ ካህናቶቻችንም ያትሙበታል።”'),
  ('8a57ed72-02ff-5aad-a23c-7fc36ce27058', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 1, 1, 'ያተሙትም እነዚህ ናቸው፤ የሐካልያ ልጅ ሐቴርሰታ ነህምያ፥ ሴዴቅያስ፤'),
  ('2762ae7c-45e2-5580-ab30-59e0128addda', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 2, 2, 'ኦርያ፥ ዓዛርያ፥ ኤርምያስ፤'),
  ('dce88b3e-3a14-54cf-a6e6-ef1e50d2ccaa', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 3, 3, 'ፋሲኩር፥ አማርያ፥ ሚልክያ፤'),
  ('b02d08e0-ea04-5c58-a2df-6f463b188c5b', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 4, 4, 'ሐጡስ፥ ሰባንያ፥ መሉክ፤'),
  ('a644cac5-a337-58e4-a01a-90ba831e5637', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 5, 5, 'ካሪም፥ ሚራሞት፥ አብድያ፤'),
  ('70ebea14-349e-5189-a892-55aac6cc4448', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 6, 6, 'ዳንኤል፥ ገንቶን፥ ባሩክ፤'),
  ('a1b915d4-03f5-5c75-a259-bb48723c8769', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 7, 7, 'ሜሱላም፥ አብድያ፥ ሚያሚን፤'),
  ('20cf4c32-9618-54d9-a818-37a71aaec036', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 8, 8, 'መዓዝያ፥ ቤልጋይ፥ ሰማያ፤ እነዚህ ካህናት ነበሩ።'),
  ('ef16f680-9055-576f-a4d9-2ab757024c57', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 9, 9, 'ሌዋውያኑም የአዛንያ ልጅ ኢያሱ፥ ከኢንሐዳድ ልጆች ባንዩ፥ ቀዳምኤል፤'),
  ('b7bd17a5-6201-5280-a6c2-deff115e355f', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 10, 10, 'ወንድሞቹም ሰባንያ፥ ሆዲያ፥ ቆሊጣ፥ ፌልዕያ፥ ሐናን፤'),
  ('c74ed2c6-05ae-5d10-ac55-01d3f25a6f11', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 11, 11, 'ሚካ፥ ሬሆብ፥ ሐሳብያ፤'),
  ('6aea3653-80ad-5e33-ad80-550b48e6ef32', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 12, 12, 'ዘኩር፥ ሰራብያ፥ ሰባንያ፤'),
  ('8e7dd809-a8dd-5746-a399-1f4b18ad4a4d', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 13, 13, 'ሆድያ፥ ባኒ፥ ባኑን።'),
  ('d4cfcb2f-28e4-5056-a383-f0420e092076', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 14, 14, 'የሕዝቡ አለቆች ፋሮስ፥ ፈሐት ሞዓብ፥ ኤላም፥ ዛቱያ፥ ባኒ፤'),
  ('d4ffdbb6-cfdd-574f-ae44-d280533b3f3e', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 15, 15, 'ቡኒ፥ ዓዝጋድ፥ ቤባይ፤'),
  ('eda2db15-d0f8-5af3-a64d-dcc6da8708ad', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 16, 16, 'አዶንያስ፥ በጉዋይ፥ ዓዲን፤'),
  ('029720cc-de03-5de4-a0e8-e0d2e5f7d957', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 17, 17, 'አጤር፥ ሕዝቅያስ፥ ዓዙር፤'),
  ('0de7a979-6621-5990-a520-93d12951eb26', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 18, 18, 'አሆዲያ፥ ሐሱም፥ ቤሳይ፤'),
  ('8bcfbcf6-f265-59dd-af35-9c9f01dd09c3', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 19, 19, 'ሐሪፍ፥ ዓናቶት፥ ኖባይ፤'),
  ('7036074d-8c17-5c7b-a1bb-90526e22e2a5', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 20, 20, 'መግፈአስ፥ ሜሱላም፥ ኤዚር፤'),
  ('b1099d93-238d-52c2-afae-a29355829864', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 21, 21, 'ሜሴዜቤል፥ ሳዶቅ፥ ያዱአ፤'),
  ('884add8f-0820-5ace-ad69-58ccb14f2e0b', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 22, 22, 'ፈላጥያ፥ ሐናን፥ ዓናያ፤'),
  ('aec5c1b2-2580-5be8-a57e-d518c39c042e', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 23, 23, 'ሆሴዕ፥ ሐናንያ፥ አሱብ፥'),
  ('3dc7059a-6a57-575a-a5ba-912d15f93c21', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 24, 24, 'አሎኤስ፥ ፈሊሃ፥ ሶቤቅ፤'),
  ('08a44460-c269-5e05-a04a-b7ac40c88e53', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 25, 25, 'ሬሁም፥ ሐሰብና፥ መዕሤያ፤'),
  ('8904d8f8-2ffa-5814-ab53-fa093a827ccb', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 26, 26, 'አሂያ፥ ሐናን፥ ዓናን፥፤'),
  ('4a36eb6a-f8ee-5771-a610-97a9df800f88', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', 'bfca3bd8-c61f-5483-a9a1-81857712d655', 27, 27, 'መሎክ፥ ሔራም፥ ባዕና።'),
  ('fde90c72-6378-514a-acbf-e3e54ebd25f7', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 1, 28, 'የቀሩትም ሕዝብ፥ ካህናቱም፥ ሌዋውያኑም፥ በረኞቹም፥ መዘምራንም፥ ናታኒምም፥ ከምድርም አሕዛብ ራሳቸውን የለዩና ወደ እግዚአብሔር ሕግ የገቡ ሁሉ፥ ሚስቶቻቸውም፥ ወንዶችና ሴቶች ልጆቻቸውም፥ የሚያውቁትና የሚያስተውሉትም ሁሉ ወንድሞቻቸውንና ታላላቆቻቸውን አበረታቱ፤'),
  ('273203bb-4832-50d5-a95b-61a326a5ed54', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 2, 29, 'በእግዚአብሔርም ባሪያ በሙሴ እጅ በተሰጠው በእግዚአብሔር ሕግ ይሄዱ ዘንድ፥ የእግዚአብሔርን ትእዛዝ ሁሉ፥ ፍርዱንም፥ ሥርዐቱንም ይጠብቁና ያደርጉ ዘንድ ርግማንንና መሐላን አደረጉ።'),
  ('a2185d38-e6e0-5f8e-a65d-9021b8ccb70d', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 3, 30, 'ሴቶች ልጆቻችንንም ለምድር አሕዛብ አንሰጥም፤ ሴቶች ልጆቻቸውንም ለልጆቻችን አንወስድም፤'),
  ('6c729c40-da1b-52bb-a278-98b79d21ad9b', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 4, 31, 'የምድርንም አሕዛብ ሸቀጥና ልዩ ልዩ እህል ሊገበዩ በሰንበት ቀን ቢያመጡ በሰንበት ወይም በተቀደሰው ቀን ከእነርሱ አንገዛም፤ ሰባተኛውንም ዓመት እናከብራለን፤ ከሰውም ዕዳ ማስከፈልን እንተዋለን።'),
  ('54406116-ceb9-545c-addf-6ac8e59383f0', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 5, 32, 'ስለ አምላካችንም ቤት ሥራ ሁሉ በየዓመቱ የሰቅል ሢሶ እናመጣ ዘንድ ሥርዐት በራሳችን ላይ እናደርጋለን።'),
  ('363caed9-1c70-5884-a60c-c65d0ea52076', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 6, 33, 'ስለ አምላካችንም ቤት አገልግሎት፥ ስለ ኅብስተ ገጽም፥ ዘወትርም በሰንበትና በመባቻ ስለ ማቅረብ ስለ እህሉ ቍርባንና ስለሚቃጠለው መሥዋዕት፥ ስለ በዓላትም፥ ስለ ተቀደሱትም ነገሮች፥ ለእስራኤልም ስለሚያስተሰርየው ስለ ኀጢአት መሥዋዕት፥'),
  ('cca3ffee-b7df-53d9-a7e3-d1aee0a433f4', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 7, 34, 'እኛም ካህናቱና ሌዋውያኑ ሕዝቡም፥ እንደ አባቶቻችን ቤቶች በተወሰነ ጊዜ በየዓመቱ ወደ አምላካችን ቤት አምጥተን በሕጉ እንደ ተጻፈ በአምላካችን በእግዚአብሔር መሠዊያ ላይ ይቃጠል ዘንድ ስለ ዕንጨት ቍርባን ዕጣ ተጣጣልን፤'),
  ('eb291e0b-4db1-527e-a576-73df753fe3be', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 8, 35, 'በየዓመቱም የመሬታችንን እህል ቀዳምያት፥ የሁሉ ዓይነት ዛፍ የፍሬ ቀዳምያት ሁሉ ወደ እግዚአብሔር ቤት እናመጣ ዘንድ፥'),
  ('1c6a7ee6-431e-50b2-ac56-33cbdb8a2e22', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 9, 36, 'በሕጉም እንደ ተጻፈ የልጆቻችንንና የእንስሶቻችንን በኵራት፥ የበሬዎቻችንንና የበጎቻችንን በኵራት በአምላካችን ቤት ወደሚያገለግሉት ካህናት ወደ አምላካችን ቤት እናመጣ ዘንድ፥'),
  ('9c5d33aa-cc9e-5baa-a2c3-f26f02640158', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 10, 37, 'የእህላችንንም ቀዳምያት፥ የዛፉን ሁሉ ፍሬ፥ የወይኑንና የዘይቱንም ፍሬ ወደ ካህናቱ ወደ አምላካችን ቤት ጓዳዎች እናመጣ ዘንድ፥ ሌዋውያኑም ከከተሞቻችን እርሻ ሁሉ ዐሥራት ይቀበላሉና የመሬታችንን ዐሥራት ወደ ሌዋውያን እናመጣ ዘንድ ማልን።'),
  ('0c93dbc2-0e48-54fe-a156-9304c4b2d188', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 11, 38, 'ሌዋውያኑም ዐሥራቱን በተቀበሉ ጊዜ የአሮን ልጅ ካህኑ ከሌዋውያን ጋር ይሁን፤ ሌዋውያኑም የዐሥራቱን ዐሥራት ወደ አምላካችን ቤት ወደ ጓዳዎች ወደ ዕቃ ቤት ያምጡት።'),
  ('3d30c3a9-7b7c-559d-ab4b-57d9df5e37ce', '38f009b8-f4af-5a34-aebb-7e12a3ad13e9', '7b4d0982-e806-5788-acfd-ce03e2ed7cd9', 12, 39, 'የእስራኤል ልጆችና የሌዊ ልጆችም የእህሉንና የወይኑን፥ የዘይቱንም ቀዳምያት፥ የመቅደሱን ዕቃዎችና የሚያገለግሉት ካህናት፥ በረኞቹና መዘምራኑ ወዳሉባቸው ጓዳዎች ያግቡት፤ እንዲሁም የአምላካችንን ቤት ከቶ አንተውም።'),
  ('583df6eb-5012-5225-a2ba-cdf4b9e5246a', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 1, 1, 'የሕዝቡም አለቆች በኢየሩሳሌም ተቀመጡ፤ ከቀሩትም ሕዝብ ከዐሥሩ ክፍል አንዱ በቅድስቲቱ ከተማ በኢየሩሳሌም፥ ዘጠኙም በሌሎች ከተሞች ይቀመጡ ዘንድ ዕጣ ተጣጣሉ።'),
  ('fdf9a736-c000-5c08-af8d-c7dfd64b706f', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 2, 2, 'ሕዝቡም በፈቃዳቸው በኢየሩሳሌም ለመቀመጥ የወደዱትን ሰዎች ሁሉ ባረኩ።'),
  ('08718951-c695-559c-ae1b-355541a4d46f', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 3, 3, 'በኢየሩሳሌምም የተቀመጡት የሀገሩ አለቆች እነዚህ ናችው፤ እስራኤል ግን ካህናቱም፥ ሌዋውያኑም፥ ናታኒምም፥ የሰሎሞንም አገልጋዮች ልጆች እያንዳንዳቸው በየርስታቸውና በየከተማቸው በይሁዳ ከተሞች ተቀመጡ።'),
  ('9d575539-6fdb-5dc8-a48f-b7cc7a8671e6', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 4, 4, 'ከይሁዳና ከብንያምም ልጆች እነዚህ በኢየሩሳሌም ተቀመጡ። ከይሁዳ ልጆች፤ ከፋሬስ ልጆች የመላልኤል ልጅ፥ የሰፋጥያስ ልጅ፥ የሰማርያ ልጅ፥ የዘካርያስ ልጅ፥ የዖዝያ ልጅ አታያ፤'),
  ('2e6e0343-cda6-5147-ab0e-a3304380c727', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 5, 5, 'የሴሎ ልጅ፥ የዘካርያስ ልጅ፥ የዮያሪብ ልጅ፥ የዓዳያ ልጅ፥ የዖዝያ ልጅ፥ የኮልሖዜ ልጅ፥ የባሩክ ልጅ መዕሤያ።'),
  ('1f294289-2f86-55d4-ae31-c26d435208c5', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 6, 6, 'በኢየሩሳሌም የተቀመጡት የፋሬስ ልጆች ሁሉ አራት መቶ ስድሳ ስምንት ጽኑዓን ነበሩ።'),
  ('6b3025e8-5c81-50f4-ab7d-bb6761086b42', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 7, 7, 'የብንያምም ልጆች እነዚህ ናቸው፤ የይሳዕያ ልጅ፥ የአትያል ልጅ፥ የመዕሤያ ልጅ፥ የቆላያ ልጅ፥ የፈዳያ ልጅ፥ የዮሐድ ልጅ፥ የሜሱላም ልጅ ሴሎ።'),
  ('0663df4c-d512-531b-a6bf-669778aa0fc6', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 8, 8, 'ከእርሱም በኋላ ጌቤና ሴል ዘጠኝ መቶ ሃያ ስምንት ነበሩ።'),
  ('f0462dfd-9a82-56db-aa01-ee26cc6548ab', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 9, 9, 'አለቃቸውም የዝክሪ ልጅ ኢዮኤል ነበረ፤ የሰኑዋም ልጅ ይሁዳ በከተማው ላይ ሁለተኛ ነበረ።'),
  ('33838bd9-311e-56d7-ad68-a2222431251b', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 10, 10, 'ከካህናቱም የዮያሬብ ልጅ ይዳእያና ያኪን፤'),
  ('742e9adb-d4e5-5742-a97e-0326b92cb71d', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 11, 11, 'የእግዚአብሔርም ቤት አለቃ የአኪጦብ ልጅ፥ የማርዮት ልጅ፥ የሳዶቅ ልጅ፥ የሜሱላም ልጅ፥ የኬልቅያስ ልጅ ሣርያ፥'),
  ('438ed611-c30c-5b1f-a9f9-b96c8aee56fa', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 12, 12, 'የእግዚአብሔርንም የቤቱን ሥራ የሠሩ ወንድሞቻቸው ስምንት መቶ ሃያ ሁለት የመልክያ ልጅ፥ የፋስኩር ልጅ፥ የዘካርያስ ልጅ፥ የአማሴ ልጅ፥ የፈላልያ ልጅ፥ የይሮሖም ልጅ ዓዳያ፥'),
  ('fe3006fa-7ccd-58ef-a999-2846dc57d5e5', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 13, 13, 'ወንድሞቹም የአባቶች ቤቶች አለቆች ሁለት መቶ አርባ ሁለት፤ የኢሜር ልጅ፥ የሜሱላሙት ልጅ፥ የአሐዚ ልጅ፥ የኤዝርኤል ልጅ ሐማስያ፥'),
  ('7c48ddcd-6ac5-5d8f-a025-473b71aa705c', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 14, 14, 'ወንድሞቻቸውም መቶ ሃያ ስምንት ጽኑዓን ኀያላን፤ አለቃቸውም የሐጊዶሌም ልጅ ዘብዲሔል ነበረ።'),
  ('c75f8b4e-112c-5278-aa6c-535c2ffd49c0', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 15, 15, 'ከሌዋውያንም የቡኒ ልጅ፥ የአሳብያ ልጅ፥ የዓዝሪቃም ልጅ፥ የሐሱብ ልጅ ሰማያ፤'),
  ('18de67b9-e207-51a3-a5ba-7292eccb60ca', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 16, 16, 'ከእግዚአብሔርም ቤት በውጭ በነበረው ሥራ ላይ የነበሩ የሌዋውያን አለቆች ሴቤታይና ኢዮዛብድ፤'),
  ('a21f3dc2-acdd-536a-a721-eb9293d5349e', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 17, 17, 'በጸሎትም ጊዜ ምስጋናን የሚጀምሩ አለቃው የአሳፍ ልጅ፥ የዛብዲ ልጅ፥ የሚካ ልጅ ማታንያ፥ በወንድሞቹም መካከል ሁለተኛ የነበረ ቦቂቦቅያ፥ የኢዶትም ልጅ፥ የጌላል ልጅ፥ የሰሙዓ ልጅ አብድያ።'),
  ('59d78332-883d-58b7-aa35-a11eca475354', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 18, 18, 'በቅድስቲቱ ከተማ የነበሩ ሌዋውያን ሁሉ ሁለት መቶ ሰማንያ አራት ነበሩ።'),
  ('0dda81d6-201a-5eb2-af6d-8dafdc488320', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 19, 19, 'በሮቹንም የሚጠብቁ በረኞች፥ ዓቁብና ጤልሞን፥ ወንድሞቻቸውም መቶ ሰባ ሁለት ነበሩ።'),
  ('fa5fe548-e3c0-51ad-af6b-11cb398d1c10', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 20, 20, 'ከእስራኤልም የቀሩት ከካህናትና ከሌዋውያንም እያንዳንዳቸው በየርስታቸው በይሁዳ ከተሞች ሁሉ ውስጥ ነበሩ።'),
  ('dd977d54-a108-57d8-a3b5-36539e5cec71', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 21, 21, 'ናታኒምም በዖፌል ተቀምጠው ነበር፤ ሲሐና ጊስፋም በናታኒም ላይ ነበሩ።'),
  ('46ada850-ccdc-5ba2-aab1-f7432a5b0f4e', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 22, 22, 'በእግዚአብሔርም ቤት ሥራ ላይ ከነበሩ መዘምራን ከአሳፍ ልጆች ወገን የሚካ ልጅ፥ የመታንያ ልጅ፥ የሐሳብያ ልጅ፥ የባኒ ልጅ ኦዚ በኢየሩሳሌም የሌዋውያን አለቃ ነበረ።'),
  ('807c4928-8c0c-5623-ae1f-25fceefb1ff3', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 23, 23, 'በእነርሱም ላይ የንጉሥ ትእዛዝ ነበረ፤ የመዘምራኑም ሥርዐት ለየዕለቱ የተሠራ ነበረ።'),
  ('7d092c46-91e3-5790-a04f-c2b7c4bc1ba1', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 24, 24, 'ከይሁዳም ልጅ ከዛራ ወገን የባስያዘብኤል ልጅ ፈታያ ስለ ሕዝቡ ነገር ሁሉ በንጉሡ አጠገብ ነበረ።'),
  ('2ab62179-2e72-5c82-a87a-c7555e837963', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 25, 25, 'ስለ መንደሮቹና ስለ እርሻዎቻቸው ከይሁዳ ልጆች ዐያሌዎች በቂርያትአርባቅና በመንደሮችዋ፥ በዲቦንና በመንደሮችዋም፥ በቃጽብኤልና በመንደሮችዋም፥'),
  ('e6138270-36cd-57fe-ae69-20fcce7b0478', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 26, 26, 'በኢያሱ፥ በሞላዳ፥ በቤተፋሌጥ፥'),
  ('7283c7f4-2c6e-5d67-ad3e-e62676607a3c', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 27, 27, 'በሐጸርሱዓል፥ በቤርሳቤህና በመንደሮችዋ፥'),
  ('72618c6e-c566-5abd-a31e-d1857451a292', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 28, 28, 'በጼቅላቅ፥ በመኮናና በመንደሮችዋ፥'),
  ('3d226c41-c498-522e-a6dd-41d8fb13accc', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 29, 29, 'በዓይንሪሞን፥ በጼርህ፥ በየርሙት፥'),
  ('0b030612-9808-586d-aa68-ad94209cbaca', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 30, 30, 'በዛኖህ፥ በዓዶላም፥ በመንደሮቻቸውም፥ በለኪሶና በእርሻዎችዋ፥ በዓዜቃና በመንደሮችዋ ተቀመጡ። እንዲሁ ከቤርሳቤህ ጀምሮ እስከ ሄኖም ሸለቆ ድረስ ሰፈሩ።'),
  ('fa44313b-3538-57f2-a3ad-746782080aa0', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 31, 31, 'የብንያምም ልጆች ከጌባ ጀምሮ በማኬማስ፥ በአያል፥ በቤቴልና በመንደሮችዋ፥'),
  ('a8d762ee-3205-5def-af08-849821540d4c', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 32, 32, 'በዓናቶት፥ በኖብ፥ በሐናንያ፥'),
  ('0ee7042a-31db-550f-ac4a-3991f82f1ca8', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 33, 33, 'በሐጾር፥ በራማ፥ በጌትም፤'),
  ('924524c4-5dc9-5694-a3fa-77d8586443cc', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 34, 34, 'በሐዲድ፥ በሰቡኢም፥ በነብላት፥'),
  ('f542ab42-2a2d-5793-aabb-c45014891524', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 35, 35, 'በሎድ፥ በኣውኖ፥ በጌሐራሲም ተቀመጡ።'),
  ('ae5710d3-ef44-547f-a4ce-4b4e00152d54', 'c3f3e327-7135-511e-a756-17862f3361de', 'a91b6d8b-a400-59f9-a4c3-ba1c2f02a915', 36, 36, 'ከሌዋውያንም ተከፍለው በይሁዳና በብንያም ነበሩ።'),
  ('69a2bcd4-b1c7-54af-ae9c-10b5b48a8d39', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 1, 1, 'ከሰላትያል ልጅ ከዘሩባቤልና ከኢያሱ ጋር የወጡት ካህናትና ሌዋውያን እነዚህ ነበሩ፤ ሠራህያ፥ ኤርምያስ፥ ዔዝራ፤'),
  ('2a9d1dcc-413f-5ecc-a50c-0fc3ffe3fa0a', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 2, 2, 'አማርያ፥ መሎክ፥ ሐጡስ፥'),
  ('5961de77-0f1e-5e29-a65b-1ff7eac51f25', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 3, 3, 'ሴኬንያ፥ ሬሁም፥ ሜራሞት፤'),
  ('f13b6dbf-95b8-5e57-ad1e-18e103f857a0', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 4, 4, 'አዶ፥ ጌንቶን፥ አብያ፤'),
  ('880ac7b6-d120-5c5b-ac9f-27932809756e', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 5, 5, 'ሚያሚን፥ መዓድያ፥ ቤልጋ፤'),
