  ('17c03e4f-4fd5-58c6-a317-82878c8b8347', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 7, 7, 'ሳሎም፥ ዓሞቅ፥ ሔልቅያስ፥ ኢዳዕያ፤ እነዚህ በኢያሱ ዘመን የካህናቱና የወንድሞቻቸው አለቆች ነበሩ።'),
  ('74e7fc9d-4dd8-58a4-acc9-6d8f32b4eefd', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 8, 8, 'ሌዋውያኑም ኢያሱ፥ በንዊ፥ ቀድምኤል፥ ሰራብያ፥ ይሁዳ፥ ከወንድሞቹም ጋር በመዘምራን ላይ የተሾመ ማታንያ።'),
  ('4ca2a260-bd06-5bbb-aadd-1f1f24f5c0a2', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 9, 9, 'ወንድሞቻቸውም በቅቡቅያና ዑኒ በየሰሞናቸው በአንጻራቸው ነበሩ።'),
  ('4e70980c-bac0-5da9-a9c1-bdd7ece9bd2c', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 10, 10, 'ኢያሱም ዮአቂምን ወለደ፤ ዮአቂምም ኤሊያሴብን ወለደ፤ ኤሊያሴብም ዮሐዳን ወለደ፤'),
  ('b13b2f2b-45ad-5fb6-ad85-c8a0990cf538', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 11, 11, 'ዮሐዳም ዮናታንን ወለደ፤ ዮናታንም ይዱዕን ወለደ።'),
