  ('e841ff85-c4e0-5a3a-ad0e-304985d78c87', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 15, 15, 'ከሐሪም ዓድና፥ ከመራዮት ሔልቃይ፤'),
  ('741e6528-77a7-501e-ad6d-f02037b7ed2d', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 16, 16, 'ከአዶ ዘካርያስ፥ ከጌንቶን ሜሱላም፤'),
  ('cc856455-4659-5b72-a3a3-a67f29db8e8d', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 17, 17, 'ከአብያ ዝክሪ፥ ከሚያሚንና ከሞዓድያ፥ ፈልጣይ፤'),
  ('33ba9bd7-05c9-57e8-ae78-e692ff0be7d3', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 18, 18, 'ከቤልጋ ሳሙኣ፥ ከሰማዕያ ዮናታን፤'),
  ('1a2ee337-c0bc-548b-a64d-b878ecdea3fe', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 19, 19, 'ከዮያሬብ መትናይ፥ ከዮዳኤያ ኦዚ፤'),
  ('70bc3550-0b14-565f-a225-fcd1bb4c3dcc', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 20, 20, 'ከሳላይ ቃላይ፥ ከዓሞቅ ዔቤር፤'),
  ('f0f3c9c7-e3e2-59ce-a56e-ee06a1a07998', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 21, 21, 'ከኬልቅያስ ሐሳብያ፥ ከኢዳዕያ ናትናኤል።'),
  ('e2f6a5ad-8b4b-54c1-a9d5-dd5fb9241c61', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 22, 22, 'ከሌዋውያኑም በኤልያሴብና በዮሐዳ፥ በዮሐናንና በያዱዕ ዘመን የአባቶች ቤቶች አለቆች ተጻፉ፤ ካህናቱም በፋርሳዊው በዳርዮስ መንግሥት ዘመን ተጻፉ።'),
  ('dc91ead9-fece-502d-ac45-79f0a51b7bab', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 23, 23, 'የሌዊ ልጆች የአባቶች ቤቶች አለቆች እስከ ኤልያሴብ ልጅ እስከ ዮሐናን ዘመን ድረስ በታሪክ መጽሐፍ ተጻፉ።'),
  ('82719a48-c22e-5fc9-a022-1addec20bd9b', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 24, 24, 'የሌዋውያኑም አለቆች አሳብያ፥ ሰርብያ፥ ኢያሱ፥ የቀድምኤልም ልጆች፥ ወንድሞቻቸውም እንደ እግዚአብሔር ሰው እንደ ዳዊት ትእዛዝ በየሰሞናቸው በእነርሱ ፊት ያከብሩና ያመሰግኑ ነበር።'),
  ('30f31887-acda-525d-a301-60e11f67cb1e', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 25, 25, 'መታንያ፥ በቅቡቅያ፥ አብድያ፥ ሜሱላም፥ ጤልሞን፥ ዓቁብ በበሮች አጠገብ የሚገኙትን ዕቃ ቤቶች ለመጠበቅ በረኞች ነበሩ።'),
  ('c20d1ce4-d279-51b9-a6bb-e209846d0ed9', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '4cafb524-aaa0-5ab6-af5b-01531f7270d9', 26, 26, 'እነዚህም በኢዮሴዴቅ ልጅ በኢያሱ ልጅ በዮአቂም በአለቃውም በነህምያ፥ በጸሓፊውም በካህኑ በዕዝራ ዘመን ነበሩ።'),
  ('71ad4ff3-ae0f-56d3-a930-b7cad83faa36', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 1, 27, 'የኢየሩሳሌምም ቅጥር በተመረቀ ጊዜ ምረቃውን በደስታና በምስጋና፥ በመዝሙርም፥ በጸናጽልም፥ በበገናም፥ በመሰንቆም ለማድረግ ወደ ኢየሩሳሌም ያመጡአቸው ዘንድ ሌዋውያኑን በየስፍራቸው ሁሉ ፈለጉ።'),
  ('399e065e-f9e1-5c0b-a7be-5b9c026b6d70', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 2, 28, 'የመዘምራኑም ልጆች ከኢየሩሳሌም ዙርያና ከሌሎችም መንደሮች ተሰበሰቡ።'),
  ('6468930a-6c37-505f-a9ab-08e14eebbc9c', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 3, 29, 'ከቤት ጌልጋልና ከጌባ፥ ከአዝማዊትም እርሻ መዘምራኑ በኢየሩሳሌም ዙርያ ለራሳቸው መንደሮች ሠርተዋልና።'),
  ('70777220-b7ea-5492-af55-3385730c8757', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 4, 30, 'ካህናቱና ሌዋውያኑም ራሳቸውን አነጹ፤ ሕዝቡንም፥ በረኞችንም ቅጥሩንም አነጹ።'),
  ('780ab6ce-941f-5987-a0b5-161229959b32', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 5, 31, 'የይሁዳንም አለቆች ወደ ቅጥሩ አወጣኋቸው፤ አመስጋኞቹንም በሁለት ታላላቅ ተርታ አቆምኋቸው፤ የአንዱም ተርታ ሰዎች ወደ ቀኝ በቅጥሩ ላይ ወደ ጉድፍ መጣያው በር ሄዱ።'),
  ('cf2e1234-1432-53bc-a8a9-7ae7d695f0f8', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 6, 32, 'ከእነርሱም በኋላ ሆሴዕ የይሁዳም አለቆች እኩሌታ፤'),
  ('8fe3819c-6470-5bcd-a720-8b8d870d8a97', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 7, 33, 'ዓዛርያ፥ ዕዝራ፥ ሜሱላም፥'),
  ('7d0eb2cf-3b14-56d6-abcd-5ec17c515b7d', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 8, 34, 'ይሁዳ፥ ብንያም፥ ሰማዕያ፥ ኤርምያስ፤'),
  ('f94ce6a5-b445-5ea4-a5fd-fa0c3f9c8d49', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 9, 35, 'መለከትም ይዘው ከካህናቱ ልጆች አያሌዎች፥ የአሳፍም ልጅ የዘኩር ልጅ የሚካያ ልጅ የመታንያ ልጅ የሰማዕያ ልጅ የዮናታን ልጅ ዘካርያስ፤'),
  ('3a64e571-d37e-588d-a8b8-4400981e09b6', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 10, 36, 'ወንድሞቹም ሰማዕያ፥ አዘርኤል፥ ማዕላይ፥ ጌላላይ፥ መዓይ፥ ናትናኤል፥ ይሁዳ፥ አናኒ የእግዚአብሔርን ሰው የዳዊትን የዜማውን ዕቃ ይዘው ሄዱ፤ ጸሓፊውም ዕዝራ በፊታቸው ነበረ።'),
  ('41f901b3-7cae-5856-a270-5ae1195c1af4', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 11, 37, 'በምንጭም በር አቅንተው ሄዱ፤ በዳዊትም ከተማ ደረጃ፥ በቅጥሩም መውጫ፥ ከዳዊትም ቤት በላይ እስከ ውኃው በር ድረስ በምሥራቅ በኩል ሄዱ።'),
  ('422590db-3749-5478-a22c-a25891c94fbb', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 12, 38, 'ሁለተኛውም የአመስጋኞቹ ክፍል ወደ ግራ ሄደ፤ እኔና የሕዝቡም እኩሌታ በስተኋላቸው ነበርን፤ በቅጥሩም ላይ፥ በእቶኑ ግንብ በላይ እስከ ሰፊው ቅጥር ድረስ፥'),
  ('ab41e192-3bde-5f1f-a9aa-49ae1d254d96', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 13, 39, 'ከኤፍሬምም በር በላይ፥ በአሮጌው በርና በዓሣ በር፥ በአናንኤልም ግንብ፥ በሃሜአ ግንብ እስከ በጎች በር ድረስ ሄዱ፤ በዘበኞችም በር አጠገብ ቆሙ።'),
  ('256a34b5-8117-59ba-a8b2-0c3fdb3864f8', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 14, 40, 'እንዲሁ ሁለቱ የአመስጋኞች ክፍሎች በእግዚአብሔር ቤት ቆሙ፤ ከእነርሱም ጋር እኔና የአለቆች እኩሌታ ነበርን፤'),
  ('c7345656-31b9-5a2c-a916-7d3e1fcec533', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 15, 41, 'ካህናቱም ኤልያቄም፥ መዕሤያ፥ ሚንያሚን፥ ሚካያ፥ ኤልዮዔናይ፥ ዘካርያስ፥ ሐናንያ መለከት ይዘው፥'),
  ('023640a9-d60c-56af-aa4a-eed2065f786d', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 16, 42, 'መዕሤያ፥ ሰማዕያ፥ ኤልየዜር፥ ኦዚ፥ ዮሐናን፥ ሚልክያ፥ ኤላም፥ ኤዝር፥ መዘምራኑም በታላቅ ድምፅ ዘመሩ፤ አለቃቸውም ይዝረአያ ነበረ።'),
  ('680b4925-b266-552c-a4e7-70758310bbd1', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 17, 43, 'እግዚአብሔርም በታላቅ ደስታ ደስ አሰኝቶአቸዋልና በዚያ ቀን ትልቅ መሥዋዕት አቀረቡ፤ ደስም አላቸው፤ ሴቶቹና ልጆቹም ደግሞ ደስ አላቸው፤ ደስታቸውም በኢየሩሳሌም ከሩቅ ተሰማ።'),
  ('66c280df-dfd0-5a5b-ab2d-26f9c0314590', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 18, 44, 'የይሁዳም ሕዝብ በአገልጋዮቹ ካህናትና ሌዋውያን ደስ ስላላቸው፥ የካህናቱንና የሌዋውያኑን ዕድል ፈንታ እንደ ሕጉ ከከተሞች እርሻዎች ያከማቹ ዘንድ ለቀዳምያት፥ ለዐሥራትም በየዕቃ ቤቶቹ ላይ በዚያ ቀን ሰዎችን ሾሙ።'),
  ('3543a824-43bf-58a7-acc2-42dc8ce92363', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 19, 45, 'እነርሱም መዘምራኑና በረኞቹም የአምላካቸውን ሥርዐት የመንጻታቸውን ሥርዐት እንደ ዳዊትና እንደ ልጁ እንደ ሰሎሞን ትእዛዝ ጠበቁ።'),
  ('cce13ef8-b491-5e9a-ade8-e1f2a3d72f3a', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 20, 46, 'በዳዊትም ዘመን አሳፍ የመዘምራን አለቃ ነበር፤ እነርሱም እግዚአብሔርን በዜማ ያመሰግኑ ነበር።'),
  ('16343a70-ac49-5ac3-ae4e-e7af23c7eebc', '7e63d2c1-fd72-5e0c-aa45-af72e7c36edc', '57017324-83e9-5bfd-a756-0b2d4d0db850', 21, 47, 'እስራኤልም ሁሉ በዘሩባቤልና በነህምያ ዘመን ለመዘምራኑና ለበረኞቹ ፈንታቸውን በየዕለቱ ይሰጡ ነበር፤ የተቀደሰውንም ነገር ለሌዋውያን ሰጡ፤ ሌዋውያኑም ከተቀደሰው ነገር ለአሮን ልጆች ሰጡ።'),
  ('c2482c62-5758-5280-a9cd-60eccd3b8054', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 1, 1, 'በዚያም ቀን የሙሴን መጽሐፍ በሕዝቡ ጆሮ አነበቡ፤ አሞናውያንና ሞዓባውያንም ወደ እግዚአብሔር ጉባኤ ለዘለዓለም እንዳይገቡ የሚል በዚያ አገኙ።'),
  ('e801bc4c-19cd-5814-a471-5745dbd16c74', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 2, 2, 'የእስራኤልን ልጆች በእንጀራና በውኃ አልተቀበሉአቸውምና፥ ይረግማቸውም ዘንድ በለዓምን ገዝተውባቸዋልና፤ ነገር ግን አምላካችን ርግማኑን ወደ በረከት መለሰው።'),
  ('9f033af3-4d43-55ce-a8de-9d3b12866f08', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 3, 3, 'ሕጉንም በሰሙ ጊዜ ከእስራኤል ጋር የተደባለቀውን ሕዝብ ሁሉ ለዩ።'),
  ('41afb7ab-c0cd-5899-ac4a-7c59b8999818', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 4, 4, 'ከዚህም አስቀድሞ በአምላካችን ቤት ጓዳዎች ላይ ተሾሞ የነበረው ካህኑ ኤልያሴብ ከጦብያ ጋር ተወዳጅቶ፥'),
  ('cec42fdb-32e2-5408-a68a-8aad07706dd6', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 5, 5, 'ለሌዋውያን፥ ለመዘምራንና ለበረኞቹ እንደ ሕጉ የተሰጣቸውን የእህሉን ቍርባንና ዕጣኑን፥ ዕቃዎቹንም፥ የእህሉንና የወይኑን፥ የዘይቱንም ዐሥራት፥ ለካህናቱም የሆነውን ቀዳምያቱን አስቀድሞ ያስቀመጡበትን ታላቅ ዕቃ ቤት አዘጋጅቶለት ነበር።'),
  ('952ccaa4-2a0e-503b-a84a-b8358c4b39f5', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 6, 6, 'እኔ ግን በባቢሎን ንጉሥ በአርተሰስታ በሠላሳ ሁለተኛው ዓመት ወደ ንጉሡ ሄጄ ነበርና በዚህ ጊዜ በኢየሩሳሌም አልነበርሁም። ከጥቂት ዘመንም በኋላ የንጉሡን ፈቃድ ለመንሁ፤'),
  ('0b3be08e-b055-5f93-aba9-7cb5ff1d8f33', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 7, 7, 'ወደ ኢየሩሳሌምም መጣሁ፤ ኤልያሴብም በእግዚአብሔር ቤት አደባባይ ለጦቢያ ዕቃ ቤቱን በማዘጋጀት ያደረገውን ክፉ ነገር አስተዋልሁ።'),
  ('8edeb999-577a-54b2-a501-3fc18715cd68', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 8, 8, 'እጅግም አስከፋኝ፤ የጦብያንም የቤቱን ዕቃ ሁሉ ከዕቃ ቤት ወደ ውጭ ጣልሁ።'),
  ('1608d159-1ff8-50f3-a808-709d23118669', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 9, 9, 'ዕቃ ቤቶቹንም እንዲያነጹ አዘዝሁ፤ የእግዚአብሔርንም ቤት ዕቃዎች፥ የእህሉንም ቍርባን፥ ዕጣኑንም መልሼ በዚያ አገባሁ።'),
  ('92b2c30d-9bc5-5e0b-a29c-95e5502e785f', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 10, 10, 'ለሌዋውያንም ፈንታቸው እንዳልተሰጠ፥ የሚያገለግሉትም ሌዋውያንና መዘምራን እያንዳንዱ ወደ እርሻው እንደ ሄደ ተመለከትሁ።'),
  ('833b847e-4455-5669-a751-87530ccb84f8', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 11, 11, 'እኔም፥ “የእግዚአብሔር ቤት ስለ ምን ተተወ?” ብዬ ከአለቆቹ ጋር ተከራከርሁ። ሰበሰብኋቸውም፤ በየስፍራቸውም አቆምኋቸው።'),
  ('7acb470a-ccd6-5c52-a9ac-aef31ae3bbd9', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 12, 12, 'ይሁዳም ሁሉ የእህሉንና የወይኑን የዘይቱንም ዐሥራት ወደ ዕቃ ቤቶች አመጡ።'),
  ('96a8a8f1-b8d5-52eb-a570-a75108e4b2e0', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 13, 13, 'በዕቃ ቤቶችም ላይ ካህኑን ሰሌምያን፥ ጸሓፊውንም ሳዶቅን፥ ከሌዋውያኑም ፈዳያን ሾምሁ፤ ከእነርሱም ጋር የመታንያ ልጅ የዘኩር ልጅ ሐናን ነበረ፤ እነርሱም የታመኑ ሆነው ተገኙ፤ ሥራቸውም ለወንድሞቻቸው ማከፋፈል ነበረ።'),
  ('03480bc7-5dee-53dc-aa0b-f075284b8b09', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 14, 14, 'አምላኬ ሆይ፥ ስለዚህ አስበኝ፤ ለእግዚአብሔርም ቤት ያደረግሁትን ወረታዬን አታጥፋ።'),
  ('fee78f33-443f-55c3-ac43-d317efd75a4f', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 15, 15, 'በዚያም ወራት በይሁዳ በሰንበት ቀን የወይን መጭመቂያን የሚረግጡትን፥ ነዶም የሚከምሩትን፥ የወይኑን ጠጅና የወይኑን ዘለላ፤ በለሱንም፥ ልዩ ልዩም ዓይነት ሸክም በአህዮች ላይ የሚጭኑትን፥ በሰንበትም ቀን ወደ ኢየሩሳሌም የሚያስገቡትን አየሁ፤ ገበያም ባደረጉበት ቀን አስመሰከርሁባቸው።'),
  ('56222df5-10ac-5a97-af28-7bdcf3dd36ec', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 16, 16, 'ደግሞም በእርስዋ የተቀመጡ ነበሩ፤ እነርሱም ዓሣዎችን፥ ልዩ ልዩም ዓይነት ሸቀጥ አምጥተው በሰንበት ቀን በኢየሩሳሌም ለይሁዳ ልጆች ይሸጡ ነበር።'),
  ('9d85ede3-7c23-5f48-a531-f35230db7d57', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 17, 17, 'ከይሁዳም አለቆችና ታላላቆች ጋር ተከራከርሁና እንዲህ አልኋቸው፥ “ይህ የምታደርጉት ክፉ ነገር ምንድን ነው? የሰንበትንስ ቀን ታረክሳላችሁን?'),
  ('02a23708-ebb3-5e61-a661-c43ec3502e5d', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 18, 18, 'አባቶቻችሁ እንደዚህ አድርገው አልነበረምን? አምላካችንስ ይህን ክፉ ነገር ሁሉ በእኛና በዚች ከተማ ላይ አምጥቶ አልነበረምን? እናንተስ ሰንበትን በማርከሳችሁ በእስራኤል ላይ መዓትን ትጨምራላችሁ?”'),
  ('46b668a7-e871-511a-a25f-d181cf06c84f', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 19, 19, 'ከዚህ በኋላ ሰንበት ከመግባቱ በፊት በኢየሩሳሌም በሮች ድንግዝግዝታ በሆነ ጊዜ በሮችዋ እንዲዘጉ፥ ሰንበትም እስኪያልፍ ድረስ እንዳይከፈቱ አዘዝሁ። በሰንበትም ቀን ሸክም እንዳይገባ ከብላቴኖች በዐያሌዎቹ በሮችዋን አስጠበቅሁ።'),
  ('c5c5aa29-0780-5bd6-a5e5-4289abbba578', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 20, 20, 'ሁሉም አንድ ወይም ሁለት ጊዜ ከኢየሩሳሌም ውጭ አድረው ገበያ አድርገው ነበር።'),
  ('dc7f1b83-1b1a-52f8-a755-44114517d1e5', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 21, 21, 'እኔም አስመሰከርሁባቸውና፥ “ከቅጥሩ ውጭ ለምን ታድራላችሁ? እንደ ገና ብታደርጉት እጆችን አነሣባችኋለሁ” አልኋቸው። ከዚያም ጊዜ ጀምሮ በሰንበት ቀን እንደ ገና አልመጡም።'),
  ('3ee64279-7482-5d68-ac10-f2492fe02271', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 22, 22, 'ሌዋውያኑንም ራሳቸውን እንዲያነጹ፥ መጥተውም በሮቹን እንዲጠብቁ፥ የሰንበትንም ቀን እንዲቀድሱ ነገርኋቸው። “አምላኬ ሆይ፥ ስለዚህ ደግሞ አስበኝ፥ እንደ ምሕረትህም ብዛት ራራልኝ” አልሁ።'),
  ('a579e01f-6897-57ce-aeb4-b7e0b58cc650', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 23, 23, 'ደግሞም በዚያ ወራት የአዛጦንንና የአሞንን፥ የሞዓብንም ሴቶች ያገቡትን አይሁድ አየሁ።'),
  ('e3d87a98-d73a-5179-a30c-f6499620240a', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 24, 24, 'ከልጆቻቸውም እኩሌቶቹ በአዛጦን ቋንቋ ይናገሩ ነበር፤ በሌሎች ሕዝብ ቋንቋ የሚናገሩም ነበሩ፤ በአይሁድም ቋንቋ መናገር አያውቁም ነበር።'),
  ('9a8c0652-7350-514d-add7-0ef0dd799ffa', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 25, 25, 'እነርሱንም ተቈጣኋቸው፤ ረገምኋቸውም፤ ከእነርሱም ዐያሌዎቹን መታሁ፤ ጠጕራቸውንም ነጨሁ፤ እንዲህም ብዬ በእግዚአብሔር አማልኋቸው፥ “ሴቶች ልጆቻችሁን ለወንዶች ልጆቻቸው አትስጡ፤ ሴቶች ልጆቻቸውንም ለወንዶች ልጆቻችሁ አትውሰዱ።'),
  ('5fd9e319-9f84-5de7-a740-50c5ef45dd7b', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 26, 26, 'የእስራኤል ንጉሥ ሰሎሞን በዚህ ነገር ኀጢአት አድርጎ የለምን? በብዙ አሕዛብም መካከል እንደ እርሱ ያለ ንጉሥ አልነበረም፤ በአምላኩም ዘንድ የተወደደ ነበረ፤ እግዚአብሔርም በእስራኤል ሁሉ ላይ አንግሦት ነበር፤ እርሱንም እንኳ እንግዶች ሴቶች አሳቱት።'),
  ('be0f3b68-4971-5fc0-a762-857a780f0161', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 27, 27, 'እንዲሁ እንግዲህ ይህን ሁሉ ታላቅ ክፋት ስትሠሩ፥ እንግዶችንም ሴቶች በማግባት አምላካችንን ስትበድሉ አንስማባችሁ።”'),
  ('f53e8774-4cf8-5916-a77a-20497c15f080', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 28, 28, 'ከዋነኛውም ካህን ከኤልያሴብ ልጅ ከዮዳሔ ልጆች አንዱ ለሐሮናዊው ለሰንባላጥ አማች ነበረ፤ ከእኔም ዘንድ አባረርሁት።'),
  ('bc88036d-f453-504f-a4aa-de1db0e5b5f7', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 29, 29, '“አምላኬ ሆይ፥ ክህነትን የክህነትንና የሌዋውያንንም ቃል ኪዳን ስላፈረሱ አስባቸው።”'),
  ('09f53350-89fb-5b7f-a107-e7c7a5b21f2f', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 30, 30, 'ከእንግዳ ነገርም ሁሉ አነጻኋቸው፤ ለካህናቱና ለሌዋውያኑም ለእያንዳንዳቸው በየሰሞናቸው፥'),
  ('8b5b7dea-50b3-503a-a575-ea6a6dffdbd1', 'ed10cc3e-b891-58d0-ad0c-8264f5c25400', '0063c3fd-8884-5ab2-a062-93e4d2a1793b', 31, 31, 'በየጊዜውም ዕንጨት ለሚሸከሙ ሰዎች ቍርባን፥ ለበኵራቱም ሥርዐት አደረግሁ። “አምላካችን ሆይ፥ በመልካም አስበኝ።”'),
  ('4540f66f-7c8a-5935-ad40-1e353ee5c3a7', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 1, 1, 'ከተማችን ኢየሩሳሌም በጠፋች በሠላሳ ዓመት ዕዝራ የተባልሁ እኔ ሱቱኤል በባቢሎን ነበርሁ፤ በመኝታዬም ደንግጬ ነበርሁ፤ ፊቴም ተገልጦ ነበር። በልቡናዬም ዐሳቤ ይወጣና ይወርድ ነበር።'),
  ('9455f080-b468-581f-afae-4db16dbbb79c', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 2, 2, 'የጽዮንን ጥፋትዋን፥ በባቢሎንም የሚኖሩ ሰዎችን ደስታ አይቻለሁና።'),
  ('d24dc1e3-d1ca-5b46-a1a5-4d9d9782aba9', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 3, 3, 'ሰውነቴም ፈጽማ ታወከች፤ የሚያስፈራ ነገርንም ከልዑል ጋር እናገር ጀመርሁ።'),
  ('11a9393b-4def-51d4-a423-07f356e76122', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 4, 4, 'ስናገርም እንዲህ አልሁ፥ “አቤቱ፥ ጌታ ሆይ፥ አስቀድሞ ምድርን በፈጠርሃት ጊዜ አንተ ብቻህን ይህን ያልህ አይደለምን? አዳምን በመዋቲ ሥጋ ታስገኘው ዘንድ መሬትን ያዘዝሃት አይደለምን?'),
  ('8ad0f345-b330-5ddc-aadd-879291f26c4f', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 5, 5, 'እርሱም የእጆችህ ፍጥረት ነው፥ በእርሱም ላይ የሕይወትን እስትንፋስ እፍ አልህበት፤ በፊትህም ሕያው ሆነ።'),
  ('c862ad33-2d0a-5a12-a294-ceb4d401c6a2', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 6, 6, 'ምድርም ሳትጸና ቀኝህ ወደ ተከለቻት ወደ ገነት አገባኸው።'),
  ('81660a9d-ce99-5918-a5bd-0aad22f15015', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 7, 7, 'እርሱንም የጽድቅ ትእዛዝን አዘዝኸው፤ ትእዛዝህንም አፈረሰ፤ ከዚህም በኋላ በእርሱና በልጆቹ ላይ ሞትን አመጣህ፤ አሕዛብና ሕዝብ፥ ነገድና ቍጥር የሌላቸው መንደረተኞችም ከእርሱ ተወለዱ።'),
  ('db328a14-5d9f-5841-a7d3-025250875153', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 8, 8, 'አሕዛብም ሁሉ በየሥራቸው ኖሩ። በፊትህም በደሉ፤ አንተንም ካዱ፤ አንተ ግን አልከለከልሃቸውም።'),
  ('1aa572de-0eb4-5fd5-adc7-1591756d58ce', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 9, 9, 'ዳግመኛም በጊዜው ጊዜ በምድር ላይና በዚህ ዓለም በሚኖሩ ሰዎች ላይ የጥፋት ውኃን አመጣህ፤ አጠፋሃቸውም።'),
  ('01e332ec-129d-594a-ae9b-c0e0bf239729', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 10, 10, 'ቅጣታቸውም የተካከለ ሆነ፤ በአዳም ላይ ሞትን እንዳመጣህ እንደዚሁ በእነዚህም ላይ የጥፋት ውኃን አመጣህ።'),
  ('c17d7bb2-6741-5d6c-a39d-cf6684624df4', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 11, 11, 'ከእነርሱም ስሙ ኖኅ የሚባል አንድ ሰውን ከቤተ ሰቡ ጋር አተረፍህ፤ ከእርሱም ጻድቃንና ኃጥኣን ተወለዱ።'),
  ('2f80fca5-efc2-53aa-a50c-75008faf614d', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 12, 12, '“ከዚህም በኋላ ይበዙ ዘንድ፥ በምድር የሚኖሩትም ይመሏት ዘንድ በጀመሩ ጊዜ፥ ልጆቻቸውም በበዙና ከእነርሱም ብዙ የሚሆኑ አሕዛብና ሕዝብ በተወለዱ ጊዜ፥ ከቀደመው በደል ይልቅ እንደገና እጅግ ይበድሉ ጀመሩ።'),
  ('27cd3f90-04ca-50d7-ae97-9893aeb8396d', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 13, 13, 'ከዚህም በኋላ በፊትህ በበደሉ ጊዜ ከእነርሱ አንዱን ስሙ አብርሃም የሚባለውን መረጥህ።'),
  ('a48357ab-cba4-58b6-afe6-fadce1f5db0b', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 14, 14, 'እርሱንም ወደድኸው፤ የዘመኑንም መጨረሻ ለብቻው በብቻህ በሌሊት አሳየኸው።'),
  ('f0f54c53-10fc-56d1-ac9a-e79911ef76c0', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 15, 15, 'የዘለዓለም ቃል ኪዳንንም አጸናህለት፤ ልጆቹንም እስከ ዘለዓለም ፈጽመህ እንዳታጠፋቸው ተስፋ ሰጠኸው። ይስሐቅንም ሰጠኸው፤ ለይስሐቅም ያዕቆብንና ኤሳውን ሰጠኸው። ያዕቆብንም ለራስህ ለየህ፤ ኤሳውን ግን ጠላህ፤ ያዕቆብም ትልቅ ሕዝብ ሆነ፤'),
  ('86b551e5-2a48-5e0f-ab98-b60185d2c2fb', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 16, 16, 'ዘሮቹንም ከግብፅ ባወጣሃቸው ጊዜ ወደ ደብረ ሲና ወሰድሃቸው፤'),
  ('b2e7c89f-a637-5a96-af99-46b804eaf495', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 17, 17, 'ሰማያትን ዝቅ አደረግህላቸው፤ ምድርንም አነዋወጥህላቸው፤ ዓለምንም አወክህላቸው፤ ጥልቁን አነዋወጥህላቸው፤ ባሕሩንም ከፈልህላቸው።'),
  ('5904d85b-c219-5450-a0a6-d07dbd77b5e4', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 18, 18, 'ለያዕቆብ ልጆች ሕግን፥ ለእስራኤልም ወገኖች ትእዛዝን ትሰጣቸው ዘንድ የእሳትና የንውጽውጽታ፥ የበረድና የነፋስ የሚሆኑ አራቱ የጌትነትህ ተአምራት ተደረጉ።'),
  ('abe86160-72d6-5d2d-a023-33b304ca3662', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 19, 19, 'ነገር ግን በእነርሱ የሕግህ ፍሬ ይደረግ ዘንድ ከእነርሱ ክፉ ዐሳብን አላራቅህም። ቀዳማዊ አዳም ክፉ ልብን ገንዘብ አድርጎ ነበርና ድል ተነሣ።'),
  ('01b62992-21e1-57de-affe-e6f5ef9db1de', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 20, 20, 'እርሱ ብቻ አይደለም፤ ከእርሱ የተወለዱ ልጆችም ሁሉ እንጂ።'),
  ('5dd0ac75-afa0-56c5-a820-6a9347c6d591', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 21, 21, 'ከዚህም በኋላ ያች ደዌ ከሕግህ ጋር በሰዉ ሁሉ ልቡና ከክፉ ሥራ ጋር ኖረች፤ በጎነትም ጠፋች፤ ክፋት ግን ኖረች።'),
  ('e15e4448-294b-5cfc-a8c6-4b4c029085ca', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 22, 22, 'ዘመን ዐለፈ፤ ዓመትም ተፈጸመ፤ ስሙ ዳዊት የሚባል አገልጋይህንም አስነሣህ።'),
  ('99c46ff0-ba1b-5aee-a53f-8bf041ec284a', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 23, 23, 'ለስምህ ከተማህን ይሠራ ዘንድ፥ መባህንም በውስጥዋ ያቀርብ ዘንድ ነገርኸው።'),
  ('901678c4-cc3b-5c66-a97f-66643904cf7e', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 24, 24, 'ብዙ ዓመትም ሆነ፤ ምንም የሚሠሩት በጎ ሥራ ሳይኖር በዚህ ዓለም የሚኖሩ ሰዎች በደሉ።'),
  ('23fa7485-7736-5da0-a9b0-b2856f2c0a2d', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 25, 25, 'አዳም እንደ አደረገ፥ ልጆቹም ሁሉ እንዳደረጉ እነርሱም ክፉ ዐሳብን ገንዘብ አድርገዋልና።'),
  ('b43870d4-c59a-5203-a6e1-addce73b7e02', '08dbe364-4075-57d4-a882-b57a1a44e205', '6aa6ea60-0e75-5e74-a66b-53db0d7390f4', 26, 26, 'ከተማህንም በጠላቶችህ እጅ አሳልፈህ ሰጠህ።”'),
  ('a78e8721-e045-5026-a4dd-42c239a47bf1', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 1, 27, 'ያንጊዜ እኔ በልቡናዬ የጽዮን ከተማን እጅ ያደርጓት ዘንድ በባቢሎን የሚኖሩ ሰዎች ጽድቅን በመሥራት በውኑ ይበልጡናልን? አልሁ።'),
  ('abb518d3-24de-510c-aec1-d380cd2f840d', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 2, 28, 'ከዚህም በኋላ ወደዚህ በደረስሁ ጊዜ ቍጥር የሌለው ኀጢአትን አየሁ፤ እነሆ፥ ለሠላሳ ዓመት ሰውነቴ ብዙ ከሓድያንን አየች፤ በዚህም ልቡናዬ አደነቀ።'),
  ('4b88e605-a3de-59ff-a26a-400af4b733e3', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 3, 29, 'ኃጥኣንን እንዴት እንደምትታገሣቸው፥ ለዝንጉዎችም እንደምትራራላቸው፥ ወገኖችህንም ጥለህ ጠላቶችህን እንዴት እንደምትጠብቅ አየሁ።'),
  ('dde8ca67-8836-54a8-a717-2454f4adbc12', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 4, 30, 'የማንንም አልተመለከትህም፤ የዚችስ መንገድ ፍጻሜዋ እንዴት ነው? ጽድቅን በመሥራት ባቢሎን ከጽዮን የምትበልጥበት አለን?'),
  ('2ea397b4-bf01-526f-a982-ac315b72a191', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 5, 31, 'አዎ፥ ከእስራኤል ሌላ ወገን ያወቀህ አለን? ወይስ በሕግህ እንደ ያዕቆብ የታመነ ሌላ ወገን አለን?'),
  ('8cdb5e85-a70c-5b1b-a931-c13373a24bd3', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 6, 32, 'ዋጋው ያልተገለጠ፥ ድካሙም ያላፈራ አለን? ወደ አሕዛብም በሄድሁ ጊዜ ሕግህንና ትእዛዝህን ሳያስቡ ደስ ብሏቸው አገኘኋቸው።'),
  ('9fa52d85-dc68-5b09-a627-6413aeb49363', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 7, 33, 'አሁንም በእርሱ ዘንድ የሚዛን ውልብልቢትን የምትመስል ያህል አንሶ ይገኝ እንደ ሆነ የእኛንና በባቢሎን የሚኖሩ ሰዎችን ኀጢአት በሚዛን መዝን።'),
  ('a384946b-9e68-5a72-ab54-e2d48819a5c0', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 8, 34, 'በዚህ ዓለም የሚኖሩ ሰዎች በፊትህ ያልበደሉ መቼ ነው? ወይስ ሕግህን እንደዚህ የጠበቀ ወገን ማነው?'),
  ('d6d799a9-ee8e-577f-a34e-4de56970ec1a', '08dbe364-4075-57d4-a882-b57a1a44e205', '96d3e0f2-6fce-565f-ace7-7a0f6ddb11d7', 9, 35, 'ፍጹም የሆነ ሕዝብስ አይገኝም።'),
  ('182af946-7957-592b-ad70-f1e96269456d', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 1, 1, 'ስሙ ዑርኤል የተባለው ወደ እኔ የተላከው መልአክ መለሰልኝ።'),
  ('d60555ec-e301-5343-aacf-ab7bfffb4674', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 2, 2, '“የልዑልን የጌትነቱን ምክር ታገኝ ዘንድ ልቡናህ ማድነቅን አደነቀን?” አለኝ።'),
  ('96858b69-07df-5ac9-a4d8-a040baf6ff37', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 3, 3, '“አዎ ጌታዬ፥” አልሁት፤ እርሱም እንዲህ አለኝ፥ “ሦስቱን መንገዶች አሳይህ ዘንድ፥ ሦስቱንም ምሳሌዎች በፊትህ አኖር ዘንድ ተላክሁ፥'),
  ('cf144025-b01e-5f84-a0d5-97d81ff05381', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 4, 4, 'ከእነዚህም አንዲቱን የተረጐምህልኝ እንደ ሆነ እኔም ታውቅ ዘንድ የምትወዳትን ይህችን መንገድ እነግርሃለሁ፤ ይህ ክፉ ልቡናም ስለምን እንደ ሆነ አስተምርሃለሁ።”'),
  ('79089b85-5ada-504a-afe2-83fccb77d625', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 5, 5, 'እኔም አልሁት፥ “አቤቱ ተናገር” እርሱም አለኝ፥ “እሳቱን በሚዛን መዝን፤ ነፋሱንም በመስፈሪያ ስፈር፤ ያለፈችውንም ቀን ጥራት።”'),
  ('440df1a2-616a-5383-ad18-c5fd316a2176', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 6, 6, 'እኔም መልሼ እንዲህ አልሁት፥ “ስለዚህ ነገር እኔን እንደ ጠየቅኸኝ ይህን ነገር ማድረግ የሚችል የተፈጠረ ሰው ማን ነው?”'),
  ('f4e3bd36-074f-5b49-a86d-bda8c67aa505', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 7, 7, 'እርሱም አለኝ፥ “በባሕር ውስጥ ምን ያህል ቤቶች አሉ? ወይም በጥልቁ ውስጥ ምን ያህል ምንጮች አሉ? ወይም በሰማያት ላይ ምን ያህል መንገድ አለ? ወይም የሲኦል መንገድ በየት ነው? ወይም የገነት መንገድ በየት ነው? ብዬ ጠይቄህስ ቢሆን፥'),
  ('960ff0d6-81f8-5053-ac33-76744afd8e81', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 8, 8, 'ወደ ጥልቁ አልወረድሁም፤ ወደ ሲኦልም ፈጽሜ አልወረድሁም፤ ወደ ሰማይም አልወጣሁም ባልኸኝ ነበር።'),
  ('80204bf3-8ad4-5c63-aaf2-0522180c87a1', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 9, 9, 'አሁን ግን ስለ ነፋስና ስለ እሳት፥ ስላለፈችውም ቀን እንጂ ይህን አልጠየቅሁህም፤ እነሆ፥ ልታውቀው አትችልም፤ ስለ እነዚህም የመለስህልኝ የለም።'),
  ('79d2d3f3-4485-5d67-ae6f-4fd03ae3cb11', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 10, 10, 'በአንተ ዘንድ ያለውን ማወቅ ያልቻልህ፥'),
  ('75d45c0f-1635-50aa-a641-85998af442a9', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 11, 11, 'የልዑልን የመንገዱን ሥርዐት እንዴት ማወቅ ትችላለህ? የልዑል መንገዱ ፍጻሜ በሌለው ተወስኗልና፥ የምትፈርስ፥ የምትበሰብስ አንተ የማይፈርስ፥ የማይበሰብስ የልዑልን መንገድ ማወቅ አትችልም።”'),
  ('13f4e76c-3ed7-5c30-a22c-a9bd749897af', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '901a8c54-6ccc-5534-ab42-2efcb5f961fe', 12, 12, 'ይህንም በሰማሁ ጊዜ በግንባሬ ወደቅሁ፤ “ተፈጥረን በኀጢአት ከምንኖርና መከራን ከምንቀበል ባልተፈጠርን በተሻለን ነበር፤ መከራ እንድንቀበልም አናውቅም” አልሁት።'),
  ('8c8a4c01-7bfa-54e3-a6f5-6202a922663e', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 1, 13, 'መልሶም እንዲህ አለኝ፥ “ዛፍና የዱር እንጨቶች ሄደው ምክርን ተማከሩ።'),
  ('47e9604e-482a-56b0-ab33-a76a28181f6f', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 2, 14, 'ከፊታችን እናርቃት ዘንድ ኑ ሄደን ባሕርን እንውጋት፤ ለዛፍነታችንም ሌላ ሀገር እናቅና” አሉ።'),
  ('54d6aa47-2754-5842-aac6-0db2b14b257c', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 3, 15, 'እንደዚሁም የባሕር ማዕበላት ምክርን መከሩ፤ “ለማዕበልነታችን በዚያ ሌላ ሀገር እንድናቀና በምድረ በዳ ያለ ዛፍን እንወጋው ዘንድ ኑ እንዝመት” አሉ።'),
  ('ba3891b3-f4e3-57b7-abb2-bdad4c417e98', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 4, 16, 'የዛፎች ምክር ከንቱ ሆነ፤ እሳት ወጥታ በልታቸዋለችና።'),
  ('b1e8dc12-b3ff-5593-a68d-bfe13283ff63', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 5, 17, 'እንዲሁም የባሕር ማዕበላት ምክር ከንቱ ሆነ፤ አሸዋው ገድቦ ከልሎአቸዋልና።'),
  ('628f802b-5594-5549-a9e4-9381b08a5619', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 6, 18, '“ፍርድ የምታውቅ ከሆነ ከእነዚህ ማንን እውነተኛ፥ ማንንስ ሐሰተኛ ታደርጋለህ?” አለኝ።'),
  ('1dd5fe6d-402d-5de7-a0e7-b73c17db8846', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 7, 19, 'መልሼም እንዲህ አልሁ፥ “ሁለቱ ከንቱን ዐሰቡ፤ የብስ ለዛፍ፥ ባሕርም ማዕበልን ትሸከም ዘንድ ተሰጥታለችና።”'),
  ('664d613d-f163-506d-a037-d54c6297af39', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 8, 20, 'እርሱም መልሶ እንዲህ አለኝ፦“ መልካም ፈረድህ፤ እንዲሁ ለራስህ ለምን አትፈርድም?'),
  ('34f1be8a-2bb6-5ade-a663-1eed027fcfe6', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '7d1f53c6-9619-5412-ab85-8b8843927acd', 9, 21, 'የብስ ለዛፍ፥ ባሕርም ለማዕበልዋ እንደ ተሰጠች እንዲሁም በምድር የሚኖሩ ሰዎች በምድር ያለውን ማወቅ ይችላሉ እንጂ በሰማያትና ከሰማያት በላይ ያለውን አይደለም።”'),
  ('563928cb-db94-52f5-af16-8b98568794c1', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 1, 22, 'መልሼም እንዲህ አልሁት፥ “አቤቱ እጠይቅሃለሁ፤ እንግዲያው እናስብ ዘንድ ልብ ለምን ተሰጠን?'),
  ('9ee3767d-7971-5959-a427-59cb48bda7c5', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 2, 23, 'እኔ ግን የልዑልን መንገድ እጠይቅ ዘንድ አልወደድሁም፤ ሁልጊዜ በእኛ ላይ ስለሚያልፈው እንጂ፤ እስራኤል በውርደት ለአሕዛብ፥ የወደድኸውም ሕዝብ ለኀጢአተኞች ሕዝብ ተሰጥቶአልና። የአባቶቻችንም ኦሪት ጠፍታለችና፤ በውስጧም የተጻፈው ቃል ኪዳን የለምና።'),
  ('c081ef8b-ca6d-5ade-a32f-acff4b7a303e', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 3, 24, 'ከዓለም እንደ አንበጣ እናልፋለን፤ ሕይወታችንም እንደ ጢስ ነው፤ ምሕረትንም ለማግኘት የተገባን አይደለንም።'),
  ('04589e0d-23ee-5809-a338-b00e0e42410d', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 4, 25, 'ነገር ግን በእኛ ስለ ተጠራ ስለ ቅዱስ ስሙ ምን እናደርጋለን? ስለዚህ ነገር ጠየቅሁህ።”'),
  ('b6764418-ce15-5cae-aa1f-f85a42b59050', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 5, 26, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “በሕይወት ካለህ ታየዋለህ፤ በሕይወት ብትኖርም በጊዜው ታውቀዋለህ፤ ዓለም ያልፍ ዘንድ ይቸኩላልና።'),
  ('052830f1-136e-5670-a669-f9fa2c56e36b', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 6, 27, 'ዓለም የጻድቃንን ተስፋ ማስቀረት አይችልምና፥ ይህ ዓለም ጭንቅን የተሞላ ነውና፥ ደዌንም የተሞላ ነውና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('6613985c-c540-5f42-a4e0-cdb4fb0a2f6e', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 7, 28, 'ስለእርሷ የጠየቅኸኝ ክፋት ተዘርታለችና፥ መከርዋም አልደረሰምና።'),
  ('865127e5-59b6-5286-a73e-53e8fe390ab8', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 8, 29, 'በውስጡም የተዘራው ካልታጨደና ካልተነሣ ክፋት የተዘራችበት ቦታው አይወገድም።'),
  ('bb19f5a7-a235-5294-aa85-b7fa7066a259', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 9, 30, 'በመጀመሪያ ክፉ የዘር ቅንጣት በአዳም ልቡና ተዘርቶ ነበርና፥ የኀጢአት ፍሬም ተወልዷልና እስከ ዛሬም ድረስ ደርሷልና፥ መከሩም እስኪደርስ ድረስ ይወለዳል፤'),
  ('fec24b68-c640-56e1-adbe-c7f393330c14', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 10, 31, 'አንተ ራስህ እስኪ አስበው! የክፉ ዘር ቅንጣት ቢዘራ ይህን ያህል የኀጢአት ፍሬ ተወለደች።'),
  ('e1ab4e37-3e12-5fc4-a855-32d6b915c963', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 11, 32, 'የመልካም ዘር ቅንጣት ግን ብትዘራ ቍጥር የሌለውን መልካም ፍሬን እንዴት ባፈራች ነበር!!”'),
  ('ef7a19a4-4e1e-58df-a978-0f6d13d69063', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 12, 33, 'መልሼም እንዲህ አልሁት፥ “ደገኛው እስከ መቼ ይሆናል? የዚህ ዓለም ዘመኑ ክፉም፥ ጥቂትም ነውና።”'),
  ('345e8a15-8714-5a84-ace0-b6c24cec5f19', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 13, 34, 'መልሶም እንዲህ አለኝ፥ “ከልዑል ይልቅ አንተ እጅግ የምትቸኩል አይደለህም፤ አንተስ ስለ ራስህ ትቸኩላለህ፤ ልዑል ግን ስለ ብዙዎች ይቸኩላል።'),
  ('2d615ceb-b004-56a1-a25b-aa78f7beb466', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 14, 35, 'ስለዚህ የጻድቃን ነፍሳት በማደሪያቸው ሁነው ጠየቁ፤ በዚህ እስከ መቼ ድረስ እንኖራለን? የዋጋችንስ መከር መቼ ይደርሳል?” አሉ።'),
  ('45c18383-cb17-5bf1-a523-0f096615a87d', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 15, 36, 'መልአኩ ኢይሩማኤልም እንዲህ ብሎ መለሰላቸው፥ “እንደ እናንተ ያሉት ጻድቃን ቍጥራቸው በተፈጸመ ጊዜ ነው።'),
  ('a5aa6b73-1e5a-5184-ad47-edc6cc45557c', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 16, 37, 'ይህ ዓለም በሚዛን ተመዝኗልና፥ ባሕሩንም በመስፈሪያ ሰፍሮታልና፤ የተሰጠውም መስፈርት እስኪፈጸም ድረስ ዝም ይላል፤ አይነቃምም።”'),
  ('ceac511c-043c-58cb-a9c7-148dc2cbae3d', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 17, 38, 'እኔም መልሼ እንዲህ አልሁት፥ “አቤቱ ጌታዬ እነሆ፥ እኛ ሁላችን ኀጢአትን የተመላን ነን፤'),
  ('00cfd137-a19d-5f94-ae39-ca875a92cded', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 18, 39, 'ምናልባት የጻድቃን የዋጋቸው መከር በእኛ ምክንያት ይከለከላልን? ወይስ በዚህ ዓለም ስለሚኖሩት ሰዎች ኀጢአት ነው?”'),
  ('312aa6cb-2609-5758-ab4d-8715468660b7', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 19, 40, 'እርሱም መለሰልኝ እንዲህም አለኝ፥ “ዘጠኝ ወር ከተፈጸመ በኋላ በማኅፀንዋ ያለውን ልጅዋን ማስቀረት ይቻላት እንደ ሆነ ሄደህ የፀነሰች ሴትን ጠይቃት።”'),
  ('a05911e8-4f82-5259-aaf9-f71ccedecb7d', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 20, 41, 'እኔም መልሼ አልሁት፥ “አቤቱ አትችልም፥” እርሱም አለኝ፥ “ሲኦልና የጻድቃን ነፍሳት ማደሪያዎችም እንዲሁ ናቸው።'),
  ('1aeac8a1-d4eb-51fc-ab5b-01f442667cf6', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 21, 42, 'ማኅፀን በምጥ ጊዜ ለመውለድ እንደምትቸኩል ምድርም ዓለም ከተፈጠረ ጀምሮ የተቀበሩባት ሰዎችን ትሰጥ ዘንድ ትቸኩላለች።'),
  ('1516d8fb-6cc3-5a06-a465-2dc0f5cd878e', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', '2f6436a6-d89e-52f2-a79d-4d905347433e', 22, 43, 'ያንጊዜም ታውቅ ዘንድ የምትወድደውን ነገር እነግርሃለሁ፥”'),
  ('939f12e0-2e15-5ac3-a032-df09cc610420', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 1, 44, 'እኔም መለስሁለት እንዲህም አልሁት፥ “በፊትህ ባለሟልነትን ካገኘሁ፥ ልጠይቅም እንዲቻለኝ ካደረግኸኝ ይኽን ንገረኝ።'),
  ('cba2445b-ce44-5b2d-a826-9103ee6f3c07', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 2, 45, 'ይመጣ ዘንድ ያለው ዘመን ባለፈው ዘመን ልክ ነውን? ወይስ ያለፈው ዘመን ይበዛል?'),
  ('09d43e2f-7f82-5446-a5ab-1c5c5b00e8bd', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 3, 46, 'ያለፈውን አውቀዋለሁና፥ የሚመጣውን ግን አላውቀውምና።”'),
  ('c43100f5-7a1a-509b-ae58-7ce1e04a369e', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 4, 47, 'እርሱም አለኝ፥ “በቀኝ በኩል ባንድ ወገን ሁነህ ቁም፤ የምሳሌውንም ትርጓሜ አሳይሀለሁ።”'),
  ('7ee6184b-0598-5bf6-a8ce-5faf4e274f61', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 5, 48, 'እኔም ቆምሁ፤ እነሆም ምድጃ በፊቴ እየነደደ ሲሄድ አየሁ፤ ከዚህም በኋላ እሳቱ በሄደ ጊዜ እነሆ ጢሱ ቀረ።'),
  ('f28b0c5a-bc5b-5ab9-a56e-2f7ff5188afb', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 6, 49, 'ከእርሱም በኋላ ውኃን የተመላች ደመና በፊቴ ሄደች፤ ታላቅና ብዙ የሆነ ዝናምንም ታዘንማለች፤ ታላቁ ዝናምም ካለፈ በኋላ ካፊያው ቀረ።'),
  ('41a7aca4-6e40-5644-a70b-544b4edc7c44', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 7, 50, 'እርሱም አለኝ፥ “እንግዲህ እስኪ አንተ ዐስበው፤ ከካፊያው ዝናሙ፥ ከጢሱ እሳቱ እንደሚበዛ፥ እንደዚሁም ያለፈው መስፈርት ይበዛል፤ ነገር ግን ካፊያውም ጢሱም ይቀራል።'),
  ('efbdfe57-bced-5d52-ad74-6c5e069ab680', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 8, 51, '“እስከ እነዚያ ዘመኖች ድረስ እኖራለሁን? እንጃ! በእነዚያስ ወራቶች ምን ይደረጋል?” ብዬ ማለድሁት።'),
  ('c9853ef6-5a58-5a56-aff6-356a37fbd8b2', '45048a4b-566f-5ba8-aa9d-fdb1e62fde9e', 'a3098adf-a24a-504f-a952-6d9b7f5b04e1', 9, 52, 'እርሱም መለሰልኝ እንዲህም አለኝ፥ “ስለ ጠየቅኸኝ ምልክትስ ከብዙ በጥቂቱ መንገር ይቻለኛል፤ ስለ ሕይወትህ ግን እነግርህ ዘንድ አልተላክሁም፤ እኔም አላውቀውም።'),
  ('67979eca-348b-594e-ab18-4a9c256957cd', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 1, 1, '“ምልክቱም እነሆ፥ ወራት ይመጣል፤ በምድር የሚኖሩትንም ሰዎች ታላቅ ድንጋፄ ይይዛቸዋል፤ የጽድቅ መንገድም ትሰወራለች፤ ሃይማኖትም ከሀገር ትጠፋለች።'),
  ('2761fc63-911b-5f28-a891-305b5f6a1f5d', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 2, 2, 'በደልም አንተ ከአየኸውና ከሰማኸው ይልቅ ይበዛል።'),
  ('4a508476-b029-57e8-a8eb-83f72a0ab3f7', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 3, 3, 'ዛሬ የጠፋና የፈረሰ ሆኖ የምታየውም ሀገር ይጠፋል፤ ምድርም ምድረ በዳ ትሆናለች።'),
  ('de7fea39-c15d-55ea-ad17-cab7115e73c5', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 4, 4, 'ልዑልም ሕይወትህን ከሰጠህ ከሦስት ወራት በኋላ ምድርን ስትታወክ ታያታለህ፤ ፀሐይም ድንገት በሌሊት ያበራል፤ ጨረቃም ድንገት በቀን ያበራል።'),
  ('72c9bada-5495-5015-a741-5e5ba0ee1aa2', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 5, 5, 'ከእንጨቶችም ደም ይፈስሳል፤ ድንጋይም ትጮኻለች፤ ሕዝቡም ይታወካሉ፤ ከዋክብትም ይረግፋሉ።'),
  ('96f496c1-ac7d-5a7d-a45d-f4433aa691c0', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 6, 6, '“ብዙዎች ያልጠረጠሩት ይነግሣል።'),
  ('6bfd0a03-3228-5b6d-a291-448cada6a143', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 7, 7, 'ሁሉም ቃሉን ይሰማል።'),
  ('c92fad2b-2442-5e22-a5f9-84b2ddb43b52', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 8, 8, 'በብዙ ሀገሮች ሽብር ይሆናል፤ ጥቅል እሳትም ይላካል፤ የምድረ በዳ አውሬዎችም ከቦታቸው ይፈልሳሉ። ከሴቶችም ባለ ምልክት ይወለዳል።'),
  ('c52d0489-a58a-5828-aac2-d4f64a47d9b7', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 9, 9, 'የሚጣፍጠውም ውኃ መራራ ይሆናል፤ ወዳጆችም እንደ ጠላት በድንገት እርስ በርሳቸው ይጋደላሉ፤ ያንጊዜም ጥበብ ትሰወራለች፤ ምክርም ወደ ማደሪያዋ ትመለሳለች።'),
  ('d5656e99-7255-5da7-a95d-43f2c6f0e671', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 10, 10, 'ብዙ ሰዎች ይፈልጓታል፤ ነገር ግን አያገኙአትም፤ በምድርም ላይ ኀጢአት፥ ዐመፅም፥ ስንፍናም ትበዛለች።'),
  ('a6c75196-a40d-5f91-accc-718217536521', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 11, 11, 'አንዲቱ ሀገር አቅራቢያዋን ሀገር ‘በውኑ በአንቺ ዘንድ የተደረገ ጽድቅ አለን? ወይስ ጽድቅን የሚያደርግ ሰው አለን?’ ብላ ትጠይቃታለች። ያችም ‘የለም’ ትላታለች።'),
  ('77756838-0019-5db5-ad08-2e6ed82f1551', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 12, 12, 'በእነዚያም ወራቶች ሰው ሞትን ይመኛል፤ ነገር ግን አያገኝም፤ ሚስትም ያገባል፤ ደስም አይለውም፤ ይደክማል፤ ሥራውንም ይሠራል፤ መንገዱ ግን አይከናወንለትም።'),
  ('deccbce9-b7c7-52f4-ad1a-faab2f3362d6', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 13, 13, 'ይኽንም ምልክት እነግርህ ዘንድ ተላክሁ፤ ዛሬ እንደ ጾምህም ዳግመኛ ሰባት ቀን ብትጸልይና ብታለቅስ ከዚህ የሚበልጥ ትሰማለህ።”'),
  ('8657464a-8097-5319-a0f3-c119883e4277', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 14, 14, 'ዳግመኛም ከእንቅልፌ ነቃሁ፤ ሰውነቴም እጅግ ስቅጥጥ አለችብኝ፤ ሰውነቴም እስክትዝል ድረስ ደከመች።'),
  ('bd775980-f3af-5e7c-ab33-fdf56f9893c8', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 15, 15, 'ወደ እኔ የመጣውና የተናገረኝ መልአኩም እጄን ያዘኝ፤ በእግሬም አቁሞ አጸናኝ።'),
  ('9e3489c8-9b82-5fde-aec8-54a97c2d77d8', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 16, 16, 'ከዚህም በኋላ በሁለተኛዪቱ ሌሊት የሕዝቡ ያለቆቻቸው አለቃ ፍልስጥያል ወደ እኔ መጣ፤ እንዲህም አለኝ፥ “አንተ ዕዝራ! ወዴት ነበርህ? ፊትህስ ስለ ምን አዝኗል?'),
  ('c6bf1cd1-2976-5c25-a4c5-94516547273f', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 17, 17, 'በምርኮ ሀገር ያሉ እስራኤል ሁሉ ለአንተ አደራ እንደ ተሰጡህ አታውቅምን?'),
  ('2a74f81c-ee15-505c-ada8-93eaad28f14f', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 18, 18, 'እንግዲህስ እስራኤልን እንዳትጥላቸው፥ መንጋዎችንም በክፉዎች ተኵላዎች አፍ እንደ ጣለ እረኛ እንዳትሆን ተነሥተህ እህልን ቅመስ።”'),
  ('a370526c-2cd8-5696-a20f-c0564aa5f622', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '4361cd54-b621-5a32-a04e-6fd6699d66b3', 19, 19, 'እንዲህም አልሁት፥ “ከእኔ ዘንድ ሂድ፤ ዳግመኛም እስከ ሰባት ቀን ድረስ ወደ እኔ አትምጣ፤ ከዚህም በኋላ ወደ እኔ ና፤ እኔም ነገርን እነግርሃለሁ፥” ከእኔም ዘንድ ሄደ።'),
  ('b13457fd-dae3-5017-ac66-120c0bdb5926', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 1, 20, 'እኔም መልአኩ ዑርኤል እንዳዘዘኝ አዝኜ እያለቀስሁ ሰባት ቀን ጾምሁ።'),
  ('d03b7d73-7020-5a4d-a4f5-68a76e09ad07', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 2, 21, 'ከሰባት ቀን በኋላም የልቡናዬ አሳብ እጅግ አደከመኝ።'),
  ('4485ff01-24cb-576e-aeb5-3c59f65b4a0a', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 3, 22, 'የጥበብም መንፈስ ሰውነቴን አነሣሣቻት፤ ዳግመኛም በልዑል ፊት እናገር ጀመርሁ።'),
  ('f5b2a4e3-66a1-53ca-a3c8-15dfa9361324', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 4, 23, 'እንዲህም አልሁ፥ “አቤቱ ጌታዬ፥ ከምድር ዛፎችና እንጨቶች ሁሉ አንድ የወይን ሐረግን ለአንተ መረጥህ።'),
  ('5cf3990c-1526-55a5-a64c-13d68b751cce', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 5, 24, 'ከዓለሙ ጥልቆች ሁሉ አንድ ወንዝን ለአንተ መላህ።'),
  ('988ec1e1-bed6-5d5b-a3ed-0d6d4184cb68', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 6, 25, 'ከሀገሮችም ሁሉ አንድ ሀገርን መረጥህ፤ ከተሠሩት ከተሞችም ሁሉ ጽዮንን ለአንተ ቀደስህ።'),
  ('7b131f4e-c164-539f-a635-97d8f8b36db8', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 7, 26, 'ከተፈጠሩ ወፎችም ሁሉ አንድ ርግብን ለአንተ ለየህ፤ ከተፈጠሩት እንስሳትም ሁሉ አንድ በግን መረጥህ።'),
  ('1f39e979-7b38-5c38-aec0-2148a09f7a63', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 8, 27, 'ከምድር አሕዛብ ሁሉ አንድ ሕዝብን ለራስህ መረጥህ፤ ለዚህ ለመረጥኸው ሕዝብህም በሁሉ ዘንድ የተፈተነ ሕግህን ሰጠኸው።'),
  ('c21d7cfe-e580-55b0-a102-3b7a930fae7e', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 9, 28, '“አሁንም አቤቱ፥ ይህን አንዱን ለብዙዎች አሳልፈህ ለምን ሰጠኸው? ከሌሎችም ሥሮች ለይተህ አንዱን ሥር ለምን አጐሳቈልኸው? አንድ ሕዝብንስ በብዙዎች መካከል ለምን በተንኸው?'),
  ('3efa993f-5ac7-555c-a6a5-2533c1470885', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 10, 29, 'የተስፋህ ባላጋራዎችዋ በሕግህ የታመኑትን ረገጧቸው።'),
  ('5f17dfe2-777b-563a-a14e-1e90a183d514', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 11, 30, 'ወገኖችህንስ ከጠላሃቸው አንተ በእጅህ ብትቀጣቸው ይሻላል።”'),
  ('e79ce647-41d5-51a7-a649-a3db09147391', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 12, 31, 'ይኽንም ቃል ከተናገርሁ በኋላ ባለፈችው በዚያች ሌሊት አስቀድሞ ወደ እኔ የመጣው መልአክ ወደ እኔ ተላከ።'),
  ('bf6be7b1-597e-5581-aaf2-662fe6478b8a', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 13, 32, 'እንዲህም አለኝ፥ “ስማኝ ልንገርህ፤ አድምጠኝ ብዙም እነግርሃለሁ።”'),
  ('a108af6c-fd7b-5bc6-ab11-c5b8bf63fb7f', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 14, 33, 'እኔም አልሁት፥ “አቤቱ ተናገር።” እርሱም አለኝ፥ “ይህ ለእስራኤል እጅግ ድንቅ ነውን? ወይስ ከፈጣሪው ይልቅ እስራኤልን አንተ እጅግ ትወድደዋለህን?”'),
  ('b5c42abe-884e-50ea-ad29-b8bdfaa6e584', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 15, 34, 'እኔም አልሁት፥ “አቤቱ፥ አይደለም፤ ነገር ግን ስለ አሳሰበኝ ተናገርሁ፤ አቤቱ፥ ሁልጊዜም የልዑልን መንገድ አገኝ ዘንድ፥ የፍርዱንም ፍለጋ አውቅ ዘንድ ስመራመር ኵላሊቴን አስጨነቀኝ።”'),
  ('fc4f393f-caaa-5fa9-a679-f60a121e5578', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 16, 35, 'እርሱም አለኝ፥ “አትችልም።” እኔም አልሁት፥ “አቤቱ፥ ስለ ምንድን ነው? ስለ ምንስ ተወለድሁ? የያዕቆብን መከራ፥ የእስራኤልንም ወገኖች ድካማቸውን እንዳላይ የእናቴ ማኅፀን ስለምን መቃብር አልሆነኝም?”'),
  ('29227aac-ea69-51d2-a92f-810b0537cafa', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 17, 36, 'እንዲህም አለኝ፥ “ገና ያልመጡ ቀኖችን ቍጠር፥ የተበተኑትንም አበባዎች ሰብስብልኝ፤ የደረቀውንም ሣር አለምልምልኝ።'),
  ('2ca77fe3-ec14-52e5-a70a-7572770d906c', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 18, 37, 'የተዘጉትንም ቤቶች ክፈትልኝ፤ በውስጣቸውም የተዘጉ ነፋሳትን አምጣልኝ፤ ፈጽሞ ያላየኋቸውንም ፊታቸውን አሳየኝ፤ ቃላቸውንም አሰማኝ፤ የዚያን ጊዜም በሚገባ ያገኛቸውን መከራ እነግርሃለሁ።”'),
  ('66974872-de99-5d9c-acde-69dc0aa4103f', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 19, 38, 'እኔም መልሼ አልሁት፥ “አቤቱ ጌታዬ፥ አነዋወሩ ከሰው የተለየ ካልሆነ በቀር ይህን ማወቅ የሚችል ማንነው?'),
  ('ffceef6e-4c30-5091-a475-0eb7b8ee3831', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 20, 39, 'እኔ ዐላዋቂና የተዋረድሁ ነኝ፤ ይህንም የምትጠይቀኝን ነገር እንዴት ልነግርህ እችላለሁ?”'),
  ('eca7d252-66d4-5b3c-ac0a-769f497678dd', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 21, 40, 'እርሱም እንዲህ አለኝ፥ “እኔ ከምነግርህ ከእኒህ አንዱን መናገር እንደማትችል እንደዚሁ ፍርዴንና ስለ ወገኖች የምታገሠውን የፍቅሬን መጨረሻ ማግኘት አትችልም።”'),
  ('c94596a3-8177-52b1-ad70-fe9b4048f6bb', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 22, 41, 'እንዲህም አልሁት፥ “አቤቱ፥ እነሆ፥ አንተ ስለ እነርሱ ታገሥህ፤ ከእኛ አስቀድሞ የነበሩ እንግዲህ ምን ያደርጋሉ? እኛና ከእኛ በኋላ የሚነሡትስ?”'),
  ('3b121020-a384-5749-ab87-cf2463bc78d7', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 23, 42, 'እርሱም አለኝ፥ “ወደ ኋላ ያሉት እንዳይዘገዩ፥ የቀደሙትም እንዳይፈጥኑ ፍርዴን እንደ ቀለበት አደረግኋት።”'),
  ('91924278-0818-5836-a07d-39d291523e7b', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 24, 43, 'እኔም አልሁት፥ “ፍርድህን ፈጥነህ ታሳይ ዘንድ የቀደሙትንና ወደ ኋላ ያሉትን አሁንም ያሉትን፥ ባንድ ጊዜ አንድ አድርገህ መፍጠር አትችልም ነበርን?” ።'),
  ('1b2325d2-b1d1-5cfe-ac46-9d8c8f6e4cd8', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 25, 44, 'እንዲህም አለኝ፥ “ሥራ ከሠሪው ፈጽሞ የሚቸኩል አይደለም፤ ዓለምም በውስጧ የተፈጠሩትን ባልቻለቻቸውም ነበር።”'),
  ('91512a69-220c-5af8-a604-7ff4d5c58c6e', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 26, 45, 'እንዲህም አልሁት፥ “አቤቱ የፈጠርሃቸውን በአንድ ጊዜ በአንድነት እንደምታስነሣቸው ለእኔ ለባሪያህ እንዴት ነገርኸኝ? የፈጠርሃቸውንም በአንድ ጊዜ ፈጥነህ የምታስነሣቸው ከሆነ ዓለም ይጨነቃል፤ ይህም ባይሆን ዛሬ ካሉት ጋራ አንድ ጊዜ ሊሸከማቸው በቻለ ነበር።”'),
  ('f3a788ca-053a-519f-a8b9-1da2cd5aaf00', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 27, 46, 'እርሱም እንዲህ አለኝ፥ “እስኪ የሴት ማኅፀንን እሺ አሰኛት፤ ዐሥር ልጆችንም ስትወልጂ ለምን በየዓመቱ ትወልጃለሽ? በላት። እንግዲህ ዐሥሩን በአንድ ጊዜ ትሰጥ እንደ ሆነ ጠይቃት።'),
  ('fd8a49f1-7da6-5261-a7f6-b192f63753f7', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 28, 47, 'በየዓመቱ ካልሆነ በቀር በአንድ ጊዜ የማትችል አይደለምን?'),
  ('20d03a88-1532-5c01-a5f0-c5782b900049', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 29, 48, 'ሕፃን ሴት መውለድ እንደማትችል፥ ያረጀችም እንደማትችል፥ እንዲሁ እኔም ለፈጠርሁት ዓለም በየጊዜው ሥርዐት ሠራሁለት።”'),
  ('6cbc5abd-86da-5e57-aff4-696552f3b370', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 30, 49, 'እኔም ጠየቅሁት፤ እንዲህም አልሁት፥ “በፊትህ እናገር ዘንድ መንገድ ሰጥተኸኛልና እነሆ፥ በእውነት አንተ አልኸኝ፤ ወጣት የነበረች እናታችሁ ፈጽማ አረጀች፤ ኀይላችንስ እንደ ቀደሙን ሰዎች ኀይል ለምን አልሆነልንም?”'),
  ('4657e935-7cca-50f7-a588-3b546b7700a0', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 31, 50, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “ልጅ የወለደች ሴትን ጠይቃት፤ ትነግርሃለችም።'),
  ('3dcdbd49-9a1c-5362-a97d-f8b4e574d28e', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 32, 51, 'በጥንካሬ ያንሳሉ እንጂ ዛሬ የወለድሻቸው ቀድሞ እንደ ወለድሻቸው ለምን አልሆኑም? በላት።'),
  ('d7f04344-8ea4-5fc1-aed5-018af01b5adc', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 33, 52, 'እርሷም እንዲህ ትልሃለች፥ “በወጣትነት የተወለደ ልጅ ልዩ ኀያል ነው፤ በእርጅና የተወለደውም ልዩ ደካማ ነው።'),
  ('baeda930-fae5-5788-ab67-9bb3ae8a194f', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 34, 53, 'ነገር ግን ከቀደሙት ሰዎች እናንተ በኀይል እንደምታንሱ አንተ ራስህ ታውቀዋለህ።'),
  ('7b2454a3-f92c-5762-aa47-84d9096a4b0a', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 35, 54, 'ከእናንተም በኋላ የሚወለዱ ከእናንተ ያንሣሉ፤ የተፈጠረውና ያለውም የሕፃንነቱ ኀይል ዘመን ካለፈ እንዲሁ ነው።”'),
  ('2616457e-ef02-5f10-aa2d-5d29ea381c68', '9426985c-8f3d-56ac-a1ec-6470e4a40da9', '3869baa4-dea2-5816-a3ca-e6c308a168b4', 36, 55, 'እኔም አልሁት፥ “አቤቱ ጌታዬ እሺ በለኝ፤ በዐይኖችህ ፊት ባለሟልነትን ካገኘሁ ለባሪያህ ንገረው፤ ዓለምህን በማን ትጐበኛለህ?”'),
  ('4fa4a353-8bd1-52e2-af39-e92ef5f94fff', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 1, 1, 'እርሱም አለኝ፥ “መጀመሪያ በሰው ልጅ ነው፤ በኋላ ግን እኔ ራሴ ነኝ፤ ሰማይና ምድር፥ ሀገሮችም ሳይፈጠሩ፥ የዓለም መንገድም ሳይጸና፥ ነፋሳትም ሳይነፍሱ፤'),
  ('885a64ac-fcfb-536c-a9a6-da932370b048', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 2, 2, 'የነጐድጓድ ድምፅም ሳይሰማ፥ የመብረቅ ብልጭታም ሳይበራ፥ የገነት ምድር ሳይፈጠር፥'),
  ('2898e72a-e81e-56e4-a09b-721934d0ba16', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 3, 3, 'የአበቦችም ውበት ሳይታይ፥ የመሬት መነዋወጥ ኀይልም ሳይጸና፥ የመላእክትም ሠራዊት ሳይቈጠሩ።'),
  ('e78f0dd8-e851-57d1-a9b6-94a6a4dde3d1', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 4, 4, 'የሰማይም ምጥቀቱ ሳይታይ፥ የሰማያትም መስፈርት ሳይሰፈር፥'),
  ('137e42a7-1e1a-50df-ae63-5b8f3a69cf97', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 5, 5, 'የሚመጣው ዓለም ፍለጋ ሳይታወቅ፥ የኃጥኣን ጥላ ሳይወገድ፦ የጌታ ማኅተም ሕግን በሚጠብቁና ሃይማኖትን በሚያምኑ ላይ ሳይታተም፥'),
  ('62b638d8-63b6-5f32-a7eb-69de2424e912', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 6, 6, 'ያንጊዜ እኔ ራሴ ይህን ዓለም እጐበኝ ዘንድ አሰብሁ፤ ሌላም አይደለም።”'),
  ('4b2de33c-3407-5c66-afb0-50ccb0e7912a', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 7, 7, 'መልሼም እንዲህ አልሁት፥ “የመጀመሪያው ዓለም ምልክቱ፥ ጊዜውስ ምንድን ነው? ፍጻሜውስ መቼ ነው? የሁለተኛውስ ዓለም መጀመሪያው መቼ ነው?”'),
  ('1cd6c9ce-50fd-5f5c-afbe-e84b41507b49', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 8, 8, 'እንዲህም አለኝ፥ “ከአብርሃም እስከ ይስሐቅ ነው፤ ያዕቆብና ዔሳው ከእርሱ ተወልደዋል፥ በተወለዱም ጊዜ ያዕቆብ የኤሳውን ተረከዝ ይዞ ተወለደ።'),
  ('75a1a7d8-5fdf-59df-ac26-d2719814d926', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 9, 9, 'ኤሳው የዚህ ዘመን ፍጻሜ ምሳሌ ነው፤ ያዕቆብም የአዲሱ ዘመን መጀመሪያ ነው።'),
  ('b0c19394-b4b6-5a39-a701-8722bb08e6d6', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 10, 10, 'የሰው መጨረሻ አካሉ ተረከዙ ነውና፤ የሰውም መጀመሪያ አካሉ እጁ ነው። ነገር ግን ዕዝራ አትመራመር።”'),
  ('89d70810-378b-5944-a673-fe0d95e8c57a', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 11, 11, 'እኔም መለስሁለት እንዲህም አልሁት፥ “አቤቱ ጌታዬ፥ በዐይኖችህ ፊት ባለሟልነትንስ ካገኘሁ፥'),
  ('50bfd1f9-ec10-5de8-a203-278376680adc', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 12, 12, 'ባለፈው ሌሊት አስቀድሞ በከፊል የነገርኸኝን የዚህን ምልክት መጨረሻ ለባሪያህ ንገረው።”'),
  ('715749c8-29c3-574e-a383-e0a03ce8e4ec', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 13, 13, 'እርሱም መለሰልኝ እንዲህም አለኝ፥ “ተነሥተህ በእግርህ ቁም፤ ጩኸት የተመላበትንም ቃል እነግርሃለሁ።'),
  ('1028e47e-0d9f-5902-a071-76cfd9311279', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 14, 14, 'አንተ በውስጡ የቆምህበት ቦታ ቢነዋወጥ በነገርሁህ ጊዜ አትደንግጥ፤ ስለ ነገር መጨረሻ ነውና።'),
  ('cbf7918d-7cf6-5790-afc3-db1e0b48b5bd', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 15, 15, 'ያንጊዜ የምድር መሠረቶች ነገርን ያስረዳሉ።'),
  ('5cfcbfbb-8db7-5617-acb6-1379a38abe44', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 16, 16, 'ነገሩ ስለ እነርሱ ነውና፥ ይንቀጠቀጣሉ፤ ይነዋወጣሉም፤ በመጨረሻቸው ያልፉ ዘንድ አላቸውና፥”'),
  ('dc8020e8-fe3d-51cf-a1ae-bd2140ecc69f', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 17, 17, 'ከዚህም በኋላ ይህን በሰማሁ ጊዜ ተነሥቼ በእግሮች ቆምሁ፤ እነሆ፥ የሚናገረውንም ቃል ሰማሁ፤ ድምፁም እንደ ብዙ ውኃ ድምፅ ነበር።'),
  ('2a2d199a-d72e-578e-ac77-af960bc17fea', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 18, 18, 'በምድር የሚኖሩትን ሁሉ ይጐበኛቸው ዘንድ ልዑል በደረሰ ጊዜ እነሆ፥ ዘመን ይመጣል ይል ነበር።'),
  ('57b6d46e-39ab-5ffc-a5cf-f302ce75e222', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 19, 19, 'ጽዮን በታነጸች ጊዜ ያመፁብኝን ዐመፃቸውን ያንጊዜ እመራመራቸው ዘንድ አለኝ።'),
  ('81a8efc1-13e4-54c7-acf7-23bad56d520e', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 20, 20, 'ይመጣ ዘንድ ያለው ዓለም በታተመ ጊዜ የማደርገው ምልክት ይህ ነው፤ በሰማይ መጻሕፍት ይገለጣሉ፤ ሁሉም ያየኛል።'),
  ('2a0912e8-20ef-5450-a616-13faf92610d7', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 21, 21, 'ዓመት የሆናቸው ሕፃናት ፈጽመው ይናገራሉ፤ የፀነሱ ሴቶችም የሦስት ወርና የአራት ወር ሕፃናትን ይወልዳሉ፤ ሕያዋንም ሆነው ይነሣሉ።'),
  ('9705d65a-e16a-5bd7-a21e-a25ccd987149', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 22, 22, 'የማትታይ ምድርም ዘርዕ ተዘርቶባት ትታያለች፥ ውስጣቸው ሙሉ የነበሩ ቤቶችም ባዷቸውን ይገኛሉ።'),
  ('c2a0485a-aef4-58f9-a6ec-8d03616db772', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 23, 23, 'ነጋሪት ይሰማል፤ የሰማውም ሁሉ ይደነግጣል።'),
  ('c8667657-921f-5909-adff-d0f4c07bb1ca', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 24, 24, 'በእነዚያም ወራት ወዳጆች ከወዳጆቻቸው ጋር እርስ በርሳቸው እንደ ጠላት ይዋጋሉ። ምድርም በውስጧ የሚኖሩባትን ታስደነግጣቸዋለች፤ የውኃው ምንጮችም ይገታሉ፤ እስከ ሦስት ሰዓትም ድረስ አይፈስሱም።'),
  ('63c80410-5bae-57b9-ad76-c078ed6f4cc2', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 25, 25, '“ከዚህ ከነገርሁህ ሁሉ የቀረ ሰው ሁሉ የሚድን እርሱ ነው፤ ትድግናዬን የዘመኔንም ፍጻሜ የሚያይ እርሱ ነው።'),
  ('3a648f78-f8f8-58f6-a942-263e358e8ab2', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 26, 26, 'ያንጊዜም ያረጉና ከተወለዱ ጅምሮ ሞትን ያልቀመሱ እነዚያን ሰዎች ያዩአቸዋል፤ በዓለም የሚኖሩ ሰዎችም ልቡና ይለወጣል፤ ሌላ ልቡናም ይሰጣቸዋል።'),
  ('e77db3ab-9625-5ad9-ad8b-bf14c9bab418', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 27, 27, 'ክፋት ትደመሰሳለችና፥ ተንኰልም ትጠፋለችና።'),
  ('174d21a8-b20d-5e97-ae4e-f8dd9b6a737d', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 28, 28, 'ሃይማኖት ትለመልማለች፤ ሞት ድል ይነሣል፤ ያለ ፍሬ ለብዙ ዘመን የነበረች ጽድቅ ትገለጣለች።”'),
  ('618039dd-665c-52b4-ae30-bcb50c38c074', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 29, 29, 'በተናገረኝም ጊዜ እኔ የቆምሁበት ስፍራ ጥቂት ጥቂት እያለ ይነዋወጥ ነበር።'),
  ('6cfdb7cd-7bff-5205-ab46-ea12484d9b08', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 30, 30, 'እርሱም አለኝ፥ “ባለፈችው ሌሊት እንደ ነገርሁህ ይህን ምልክት እነግርህ ዘንድ መጣሁ።'),
  ('287a02b7-06b0-535e-ad3f-e283316d17f7', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 31, 31, 'ዳግመኛ ሰባት ቀን ብትጾምና ብትጸልይ ከዚህ የሚበልጥ ዳግመኛ እነግርሃለሁ።'),
  ('d34a3b67-8cbb-5693-a09e-9f661592f722', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 32, 32, 'ቃልህ በልዑል ዘንድ መሰማትን ተሰምትዋልና። ከሕፃንነትህም ጀምሮ ያለው የጽድቅህ ኀይል ተገልጧልና።'),
  ('c4109d91-1f5e-5070-af5b-2d52180d51d5', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 33, 33, 'ስለዚህም ይህን ነገር እነግርህ ዘንድ ልዑል ላከኝ።'),
  ('cce3d7c8-14d7-5ad8-af78-e7aa233aa5e9', '747e4eac-a938-5dc7-af6c-208930adf26e', 'e45f6d1d-3fa5-5800-a427-4d33fc026951', 34, 34, 'እንዲህም አለኝ፦ እመን፤ አትፍራ፤ በኋላ ዘመን እንዳትጠራጠር ስለ ቀደመውም ክፉ አሳብህ አትቸኩል።”'),
  ('b3f0ba16-9415-5196-a7cc-a0e72d76b893', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 1, 35, 'ከዚህም በኋላ የነገረኝን ሦስቱን ሱባዔያት እጨርስ ዘንድ ዳግመኛ ሰባት ቀን እያለቀስሁ ጾምሁ።'),
  ('04ac0d2b-9f0b-5aac-a96b-fc2cac211751', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 2, 36, 'በዚያች ሌሊት ልቤ ታወከችብኝ፤ በልዑልም ፊት እናገር ጀመርሁ።'),
  ('b4eaf3e5-f926-5848-aa8b-e4901c1b68fb', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 3, 37, 'ሰውነቴ ፈጽማ ትናደዳለችና፥ ልቡናዬም ትናወጣለችና።'),
  ('0ebab420-e1db-58c4-a321-639f6af027b6', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 4, 38, 'እንዲህም አልሁ፥ “አቤቱ ጌታዬ፥ በመጀመሪያው መፍጠርህ በመጀመሪያዪቱ ቀን ሰማይና ምድር ይፈጠር አልህ፤ እንዲሁም ተፈጠረ፤ ቃልህም ፍጥረትን ይፈጥር ነበር።'),
  ('501b3dd5-eaef-5db4-a729-d5a72f56dc29', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 5, 39, 'መንፈስም ይሰፍፍ ነበር። ጨለማም ሞልቶ ነበር፥ ፀጥ ብሎም ነበር። ድምፅም አልነበረም፤ የሰው ልጅ ድምፅ ገና አልነበረምና።'),
  ('62183ca6-c9a2-5cd4-a9b9-7555f09b6602', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 6, 40, 'ያንጊዜም ብርሃን ከአዳራሽህ እንዲገኝ ፍጥረትህም እንዲገለጥ አዘዝህ።'),
  ('349b6eb9-9254-5635-a71c-ef32939f01c8', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 7, 41, '“ዳግመኛም በሁለተኛው ቀን በሰማያት ያለ ነፋስን ፈጠርህ፤ እኩሌታውም ወደ ላይ ይወጣ ዘንድ፥ እኩሌታውም በታች ይኖር ዘንድ በውኃው መካከል እንዲለይ አዘዝኸው።'),
  ('7987fdd8-0871-5d63-a761-628a0512031c', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 8, 42, 'ዳግመኛም በሦስተኛው ቀን ውኃውን ከምድር በሰባተኛው እጅ ላይ እንዲሰበሰብ አዘዝኸው። የምድር ስድስቱ እጅም በውስጣቸው ያርሱ ዘንድ፥ ዘርም ይዘሩ ዘንድ፥ በፊትህም ይኖሩ ዘንድ ደረቅ ሆኖ ይቅር አልህ።'),
  ('1045b799-a707-5330-a117-faf6511bef06', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 9, 43, 'ቃልህም በወጣ ጊዜ ፍጥረት ይፈጠር ነበር።'),
  ('2ab53fa5-22e7-5b3d-a2bf-b2f840186fee', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 10, 44, 'ያንጊዜም ቍጥር የሌለው ብዙ ፍሬ በቀለ፤ የሁሉም ጣዕሙ፥ ያበባውም መልክ ልዩ ልዩ ነበር፤ የእንጨቱም ዓይነት ልዩ ልዩ ነበር፤ መዓዛውም ልዩ ልዩ ነበር።'),
  ('fd860355-e6ea-5d71-a499-a8080e667e63', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 11, 45, '“ባራተኛይቱም ቀን ያበሩ ዘንድ የጨረቃና የፀሐይ ብርሃን፥ የከዋክብትም ሥርዐት ይፈጠር ዘንድ አዘዝህ።'),
  ('396dbe25-f4f8-5a1b-aedd-d926dd75597a', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 12, 46, 'ይፈጠር ዘንድ ላለው ሰውም ያገለግሉ ዘንድ አዘዝሃቸው።'),
  ('c08d2d1a-076e-58e3-afc1-fb6c9fbf2a85', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 13, 47, '“ባምስተኛውም ቀን የናጌብ ውኃ ያለበትን ያን ሰባተኛውን እጅ ሕይወት ያላቸውን ወፎችንና ዓሣዎችን ያስገኝ ዘንድ አዘዝኸው።'),
  ('8135f543-ff6a-51c1-af3f-7c8ed88c455a', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 14, 48, 'ስለዚህ ትውልድ ሁሉ ጌትነትህን ይናገሩ ዘንድ የማይናገርና ደመ ነፍስ የሌለው ያ ውኃ ሕይወት ያለውን አስገኘ።'),
  ('33803039-c14a-5335-a2c0-0a878333006a', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 15, 49, 'ያንጊዜም የፈጠርሃቸውን ሁለቱን እንስሳት ጠበቅህ፤ ያንዱን ስሙን ብሔሞት አልኸው፤ የሁለተኛውንም ስሙን ሌዋታን አልኸው።'),
  ('fe4b6e14-ec27-5e60-a9be-6cf6ba4b333b', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 16, 50, 'በየራሳቸውም ለየሃቸው፤ የናጌብ ውኃ ያለበት ያ ሰባተኛው እጅ ሊወስናቸው አይችልምና፥'),
  ('63cbf38f-b3e1-529e-a988-6f15826b4de3', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 17, 51, 'አራቱ ተራሮች ባሉበት በዚያ እርሱ በውስጡ ይኖር ዘንድ ለብሔሞት ከስድስቱ እጅ አንዱን እጅ የብስን ሰጠኸው።'),
  ('50615fd8-ff5c-55cb-a036-9ff0bad8fe2d', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 18, 52, '“ለሌዋታንም የባሕሩን ሰባተኛ እጅ ሰጠኸው፤ ለምትወዳቸው ምግብ ይሆኑ ዘንድም ጠበቅሃቸው።'),
  ('9a0774c6-3759-54ba-a1f2-52a577ae7947', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 19, 53, 'በስድስተኛዪቱም ቀን በፊትህ እንስሳን፥ የሰማይ ወፎችንና የዱር አውሬዎችን ታስገኝ ዘንድ ምድርን አዘዝሃት።'),
  ('25c39b6f-ac1d-5eb0-a315-b9eb4bb83e53', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 20, 54, 'በዚህም ሁሉ ላይ አዳምን ገዥ አድርገህ ሾምኸው፤ አስቀድመህ በፈጠርኸው ፍጥረት ላይም ገዥ ሆነ። በእርሱም ምክንያት የመረጥኸን እኛ ወገኖችህ ከእርሱ ተገኘን።'),
  ('a73b3183-97b4-5546-a376-83645e2c2c52', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 21, 55, '“አቤቱ፥ ይህን ሁሉ በፊትህ ተናገርሁ፤ ይህን ዓለም ሰለ እናንተ ፈጠርሁት ብለሃልና።'),
  ('08502686-d85c-5603-ad6e-bc86c7b652c5', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 22, 56, 'ከአዳም የተወለዱ ሌሎች አሕዛብ ግን እንደ ኢምንት ናቸው፤ እንደ ምራቅም ይመስላሉ፤ እንደ አፍሻት ጠብታም ናቸው፤ ደስታቸውም እንደ ኢምንት ነው።'),
  ('bea88ab7-6d5e-551c-abf3-c8cbc82c4ecc', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 23, 57, 'አሁንም እነሆ እንደ ኢምንት ናቸው ያልሃቸው እነዚያ አሕዛብ እነሆ በእኛ ላይ ሠለጠኑ፤ ረገጡንም።'),
  ('8f9ba9cc-a37c-54a0-ab00-297499bf16bc', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 24, 58, 'የምወደው የበኸር አንድያ ልጄ ያልኸን እኛ ወገኖችህ ግን በአሕዛብ እጅ ገባን።'),
  ('23d7ca5e-a197-52e1-ae72-a6538d61e456', '747e4eac-a938-5dc7-af6c-208930adf26e', '87685ca5-6371-52b0-a270-1d7d16992ea6', 25, 59, 'ነገር ግን ዓለምን ስለ እኛ ከፈጠርኸው ዓለማችንን ለምን አንወርስም? ይህስ እስከ መቼ ድረስ ነው?”'),
  ('2e50f092-604b-5cb3-a1a0-4d8af8835e2a', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 1, 1, 'ከዚህም በኋላ ይህን ነገር ተናግሬ በጨረስሁ ጊዜ ባለፈችው በዚያች ሌሊት አስቀድሞ ወደ እኔ የመጣው ያ መልአክ ወደ እኔ ተላከ።'),
  ('b08ce894-2d9f-5c7b-aa19-3761ca51c38e', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 2, 2, 'እንዲህም አለኝ፥ “ዕዝራ ሆይ፥ ተነሥ፤ እነግርህ ዘንድ ወደ አንተ የመጣሁ የእኔን ቃል ስማ።”'),
  ('a3b4660a-8120-5f0c-a267-b83ee82c4f8e', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 3, 3, 'እኔም አልሁት፥ “ጌታዬ ተናገር፤” እርሱም አለኝ፥ “በአንድ ሰፊ ቦታ ባሕር አለች፤ እርስዋም ሰፊና ጥልቅ ናት።'),
  ('27e702da-c4b5-5dba-a154-a3d352625bb8', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 4, 4, 'ጠባብ የመግቢያ መንገድም አላት፤ የመስኖ ውኃ ቦይ ያህልም ትሆናለች።'),
  ('6d3b7146-d995-5e2e-a7af-cb57e31bcd95', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 5, 5, 'ያያትና ያገኛት ዘንድ ወደዚያች ባሕር ሊገባ የወደደ ቢኖር ያን ጠባቡን መግቢያዋን ካላለፈ ወደ አደባባይዋ መግባት እንዴት ይችላል?'),
  ('8bcbc750-cc98-5624-acbb-18afb4e49f18', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 6, 6, 'ወይም በሜዳ የተሠራች፥ ከበረከቱም ሁሉ የተመላች አንዲት ከተማ አለች።'),
  ('46e8d4b6-8995-559f-a1f6-4d1ea486fb4f', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 7, 7, 'የመግቢያዋም መንገድ ጠባብ ነው፤ በገደል ውስጥም ናት፤ በቀኝዋ እሳት፥ በግራዋም ጥልቅ ውኃ አለ።'),
  ('70a7ff3d-9749-57fc-a3e8-9a279864e7a0', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 8, 8, 'አንዲት መንገድ በውኃና በእሳት መካከል አለች፤ መንገድዋም ከአንድ ሰው እግር ጫማ በቀር አትችልም።'),
  ('014a629f-1168-5c8b-a8e3-516781f206be', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 9, 9, 'ይህች ከተማ የተሰጠችው የሚወርሳት ሰው ቢኖር ያን ጠባቡን መንገድ ካላለፈ ርስቱን እንዴት ያገኛል?”'),
  ('d0132cc8-1c74-5abb-aebf-e4a0d6b7a6c7', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 10, 10, 'እኔም፥ “አቤቱ፥ እንደዚሁ ነው” አልሁት። እርሱም እንዲህ አለኝ፥ “የእስራኤል ምድራቸው፥ ዕድል ፈንታቸውም እንዲሁ ነው።'),
  ('f1a052d4-d570-5ffd-aa14-a3c35fa55e32', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 11, 11, 'ዓለምን ስለ እነርሱ ፈጥሬዋለሁና።'),
  ('79a2ae8b-1ad9-544a-a3d5-b753adce4004', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 12, 12, 'አዳምም ትእዛዜን ባፈረሰ ጊዜ የዚህ ዓለም ጎዳናው ሰንከልካላና ጠባብ፥ ጐድጓዳና የከፋ፥ መከራው የበዛ፥ ጻዕርና ጋርን የተመላ ሆነ።'),
  ('f0536894-8013-57b8-a7b5-565ddbdc4996', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 13, 13, 'የዚያኛው ዓለም ግን ጎዳናው ታላቅ ነው፤ ሰፊም ነው፤ ብሩህም ነው፤ ሞት የሌለበት የሕይወት ፍሬንም ያፈራል።'),
  ('44bb98f2-70e1-5d1e-a289-ff09c8bf7dc6', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 14, 14, 'ሕያዋን የምትሆኑ እናንተም ያን ሰንከልካላና ያን ኀጢአት ካላለፋችሁት ለእናንተ የተዘጋጀውን ማግኘት አትችሉም።'),
  ('7a76a3ff-cb34-5fe3-ab07-8ac7ff0d03e2', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 15, 15, 'አሁንስ አፈር የምትሆን አንተ ለምን ትታወካለህ? ሟች የምትሆን አንተስ ለምን ትናወጣለህ?'),
  ('718e7c7f-d2e0-5b68-acdf-8bd8585d0e5e', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'a87c0539-890f-5549-a038-54ab280764a5', 16, 16, 'ያለውን ነው እንጂ የሚመጣውን በልብህ ለምን አታስብም?”'),
  ('5ec17726-c155-5588-a0f4-871a64ecc972', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 1, 17, 'እኔም መልሼ አልሁት፥ “አቤቱ ጌታዬ፥ ጻድቃን ይህን ዓለም እንደሚወርሱት፥ ኃጥኣን ግን እንደሚጠፉ አንተ በሕግህ እነሆ፥ ተናገርህ።'),
  ('419365d6-7a4b-5a9f-a5ac-bfe8c311ea70', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 2, 18, 'ጻድቃን ሰፊውን ተስፋ እያደረጉ ጠባቡን ይታገሡታልና፤ ጠባቡን የሚታመኑ ኃጥኣን ግን ሰፊውን አያገኙትም።”'),
  ('209dac23-3780-5dec-af9d-6e38af529c34', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 3, 19, 'እርሱም እንዲህ አለኝ፥ “አንተ በፍርድ ከአንዱ ከእግዚአብሔር የምትሻል አይደለህም፤ ከልዑልም አንተ የምትራቀቅ አይደለህም።'),
  ('c43b36c2-cde8-5e9f-a8d9-001d0d29ec0a', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 4, 20, 'የሠራውን የእግዚአብሔርን ሕጉን ያቃለሉ እነዚያ ይጥፉ፤'),
  ('060f8537-1479-50f2-a43a-75755ad8dea0', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 5, 21, 'እግዚአብሔር ሕጉን ሠርተው በሕይወት እንዲኖሩ አዟቸዋልና። ሕጉን ቢጠብቁ ግን ባልተፈረደባቸውም ነበር።'),
  ('cd6dad5a-643e-5329-afe3-50e7061927b7', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 6, 22, 'ኃጥኣን ግን ካዱት፤ ተዉትም፤ ለራሳቸውም ክፉ አሳብን አሰቡ።'),
  ('03a77e31-a986-578b-a31d-e1ce7b2c5fe6', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 7, 23, 'ሽንገላንና ዐመፅን ለራሳቸው ገንዘብ አደረጉ፤ ከዚህም ሁሉ ጋር እግዚአብሔር የለም አሉ፤ መንገዱንም ተዉ።'),
  ('c334dab1-1e90-5ae0-aa87-1e10e3722cef', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 8, 24, 'ሕጉንም ካዱ፤ ቃል ኪዳኑንም ቸል አሉ፤ በሥርዐቱም አልታመኑም፤ ሥራውንም ናቁ፤ አምልኮቱንም አላሰቡም።'),
  ('dab40219-855b-5b43-a812-ae343d1cf8c8', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '19833183-13c9-58df-afac-ecdcac812765', 9, 25, 'ስለዚህ የተራቈተው ለተራቈቱት ነው፤ የተሞላውም ለተሞሉት ነው።'),
  ('7be982cb-2840-5514-ac0e-ffe2a6a4ac1c', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 1, 26, '“እኔ የነገርሁህ ምልክት የሚገለጥበት ወራት እነሆ፥ ይመጣልና፥ ዛሬ የምትታይ ከተማ ታልፋለች፤ ዛሬ የተሰወረች ምድርም ትገለጻለች።'),
  ('d99e0cb1-c525-5096-a749-5a00a3ccb01e', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 2, 27, 'እኔ ከነገርሁህ ከክፉ ሥራ የዳነ ሁሉ ክብሬን የሚያይ እርሱ ነው።'),
  ('4683d4bc-687b-56f2-a509-ba61c8148b31', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 3, 28, 'የእኔ መሲሕ አብረውት ካሉት ጋር ይገለጣልና፥ የሚነሡትንም ደስ ያሰኛቸዋል።'),
  ('3d33aff6-c170-5eba-aad3-deb001388d70', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 4, 29, 'ከዚህ በኋላ ልጄ መሲሑ ይፈጽማል፤ አእምሮ ያለውም ሰው ሁሉ ይፈጽማል፤'),
  ('2a87a94b-74fd-55f6-a445-2a5af4c5437c', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 5, 30, 'ዓለምም እንደ ቀድሞው ሰባት ቀን ዝም ያለውን ያህል ወደ ቀድሞ አነዋወሩ ይመለሳል፤ የሚቀርም የለም።'),
  ('3131fcee-1b1d-5f48-a875-e473b019d042', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 6, 31, 'ከሰባት ቀን በኋላም የነቃበት ጊዜ የሌለ ሰው ይነሣል፤ የመዋቲ ሰው ዓለምም ያልፋል።'),
  ('772f7754-d82a-545e-a6c7-1afd4791fdc9', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 7, 32, 'ምድርም የተቀበሩባትን ሰዎች ትመልሳለች፤ መሬትም በውስጡ ያረፉትን ሰዎች ይመልሳል፤ ከዚህም በኋላ አብያተ ነፍስ በውስጣቸው የተቀመጡ ነፍሳትን ይመልሳሉ።'),
  ('9e989f9e-b466-5c38-a902-6809acba8a67', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 8, 33, 'ያንጊዜም ልዑል በፈጠረው በዙፋኑ ላይ ይገለጣል፤ ቸርነቱም ትመጣለች፤ ይቅርታውም ትመለሳለች፤ ትዕግሥቱም ትሰበሰባለች።'),
  ('f52eedcc-b928-5f92-a5f2-578a9acc49cc', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 9, 34, 'ቍርጥ ፍርድ ብቻ ይቀራል፤ ጽድቅ ትጸናለች፤ ሃይማኖትም ትገለጣለች።'),
  ('1dc84fbc-ed97-5244-adb6-46a78be0716e', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 10, 35, 'ሰውን ሥራው ይከተለዋል፤ ዋጋውም ይገለጣል፤ ቅንነቱም ትነቃለች፤ ኀጢአቱም አታንቀላፋም።'),
  ('97d9cb0d-76b5-539b-ab49-1fb6f3004e04', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 11, 36, 'የቍርጥ ፍርድ ጕድጓድ በዕረፍት ቦታ አንጻር ይከፈታል። በደስታ ገነትም አንጻር እሳተ ገሃነም ይገለጣል።'),
  ('82cca84f-d7bb-57a3-a4f9-00372bda5580', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 12, 37, '“ያንጊዜም ልዑል ከሙታን የተነሡ አሕዛብን፦ ‘እነሆ እዩ፤ የካዳችሁትም ማን እንደ ሆነ ዕወቁ፤ ያልተገዛችሁ ለማን ነው? የናቃችሁትስ የማንን ትእዛዝ ነው?” ይላቸዋል።'),
  ('19ab3e61-0913-50cc-a104-210e18ccd8a3', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 13, 38, 'እነሆ፥ ወደ ፊታችሁ እዩ፤ በወዲህ ደስታና ዕረፍት አለ፤ በወዲያም ፍርድና እሳት አለ።’'),
  ('6bba5f00-21d1-59fe-afd5-33cc1b48a1c3', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 14, 39, '“ልዑል በፍርድ ቀን አሕዛብን እንዲህ ይላቸዋል፦ ‘የፍርድ ቀንስ እንዲህ ናት፤ ፀሐይ፥ ጨረቃም፥ ከዋክብትም የሉአትም።'),
  ('fb3feb9e-5925-572c-a5ff-3c27cf08256a', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 15, 40, 'ደመናም፥ መብረቅም፥ ነጐድጓድም፥ ነፋስም፥ ውኃም፥ ሰማይም፥ ጨለማም፥ ሌሊትም፥ መዓልትም የሉአትም፤'),
  ('8e5b4721-9260-5ef0-a4c6-2dffa2ef94a1', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 16, 41, 'ክረምት፥ በጋም፥ መከርም፥ ብርድም፥ ሐሩርም፥ ጥቅል ነፋስ፥ በረድ፥ ውርጭ፥ ጉም፥ ዝናም፥ ጠል የለባትም።'),
  ('403d6e89-793e-5a63-ae09-b2bb42a1cca6', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 17, 42, 'ማታና ጧት፥ ብርሃንና ብልጭልጭታ፥ ፋናና መብራት፥ ሁሉ ለእርሱ የተጠበቀለትን ያይበት ዘንድ ከእግዚአብሔር ከጌትነቱ ብርሃን ብቻ በቀር ይህ ሁሉ የለም።'),
  ('bf1f5bde-07b0-5c9c-a813-a49bc254ab5a', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 18, 43, 'የዚያች ሰዓት ርዝመቷ እንደ ሰባት ዓመት ይሆናል።'),
  ('9a07497b-1dab-587a-ab5a-6f21e02bbf01', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '64b38cf5-857a-55c1-a193-3485c5cce782', 19, 44, 'ፍርዱም፥ ቅጣቱም ይህ ነው’ ይህንም ለአንተ ብቻ ነገርሁ።”'),
  ('431c8792-4d1a-5b44-af9f-28b2f2aa860a', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 1, 45, 'እኔም እንዲህ አልሁት፥ “አሁንም አቤቱ፥ ትእዛዝህን ጠብቀው የኖሩ ብፁዓን ናቸው።'),
  ('e06e6209-fefa-5ce4-aede-fafe1e1c6c66', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 2, 46, 'ነገር ግን ስለ ጠየቅሁህ ነገር ከሕያዋን መካከል የማይበድል ማንነው? ከተወለደስ ወገን ሕግህን ያልተወ ማንነው?'),
  ('f4522ec2-b1ef-5d82-a4e5-e3d14b6d4e91', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 3, 47, 'አሁንም በሚመጣው ዓለም ደስ ታሰኛቸው ዘንድ ያለህ ጻድቃን ጥቂት እንደ ሆኑ፥ የሚፈረድባቸውም ብዙዎች እንደ ሆኑ አያለሁ።'),
  ('2c21b2f6-e314-59aa-ae1c-f74a8e692592', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 4, 48, 'ከዚህም ያሳተን፥ ወደ ጥፋትም የመራን፥ ወደ ሞት ጎዳናና ወደ ጥፋት መንገድም የወሰደን፥ ከዛሬ ጀምሮ ከእኛ ሕይወትን ያራቃት፥ ክፉ ልቡና በእኛ ጸንትዋልና። ይህም በተወለዱ ሁሉ ላይ ነው እንጂ በጥቂቶች ብቻ አይደለም።”'),
  ('db793711-349e-5ec9-a8c2-1633bdf02b6b', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 5, 49, 'መልአኩም መለሰልኝ እንዲህም አለኝ፥ “ስማኝ ልንገርህ፤ ዳግመኛም አስተምርሃለሁ።'),
  ('52fc7e5f-0d71-544b-ae2d-7cb5d1d498cc', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 6, 50, 'ስለዚህ ነገር ልዑል ሁለት ዓለምን እንጂ አንድ ዓለምን ብቻ አልፈጠረም።'),
  ('74567a74-7bf5-5f58-a798-661c12772123', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 7, 51, 'አንተ ግን የጻድቃን ቍጥራቸው ጥቂት ነው፤ ብዙዎችም አይደሉም፤ የኃጥኣን ግን ቍጥራቸው ብዙ ነው ብለሃልና፥'),
  ('8ad30440-0002-5861-a746-8c7686e16333', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 8, 52, 'እርሳሱን ከሸክላ ጋር ሥራ።”'),
  ('84421361-ad48-5e48-a681-619835fb5179', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 9, 53, 'እኔም አልሁት፥ “አቤቱ፥ ይህ እንዴት ይቻለኛል።”'),
  ('53f16601-b6ac-5169-a356-34d4de423826', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 10, 54, 'እንዲህም አለኝ፥ “ይህን ብቻ አይደለም፥ ነገር ግን ምድርን ጠይቃት፤ ትነግርሃለችም፤ ተናገራት፤ ትመልስልሃለችም።'),
  ('6ba1dd2d-3af5-5c67-a79c-e7d632657937', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 11, 55, 'እነሆ፥ ወርቁን፥ ብሩንም፥ ናሱንም፥ ብረቱንና እርሳሱን፥ ሸክላውንም አንቺ ታስገኚዋለሽ በላት።'),
  ('c266f674-a149-5a1a-ad0e-a6febfc3dc7a', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 12, 56, 'ብር ከወርቅ፥ ናስም ከብር፥ ብረትም ከናስ፥ እርሳስም ከብረት፥ ሸክላም ከእርሳስ ይበዛል።'),
  ('fddb08bb-8176-5dc9-a6c8-0733b38f7894', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 13, 57, 'እንግዲህ አንተ ራስህ ዕወቅ፥ የትኛው ይከብራል? የትኛውስ ይወደዳል? የሚበዛው ነውን? ወይስ የሚያንሰው ነው?”'),
  ('42e0d82f-96be-5e8f-aabb-d23c5b72c924', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 14, 58, 'እኔም መለስሁለት እንዲህም አልሁት፥ “ጌታዬ ሆይ የሚያንሰው ይወደዳል፤ የሚበዛውም ይረክሳል።”'),
  ('8fe533be-f59b-5d9c-a958-1e64cb622e8b', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 15, 59, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “ያሰብኸውን አንተ ራስህ መዝነው፤ ከብዙው ካለው ይልቅ፥ ከጥቂቱ ያለው እጅግ ደስ ይለዋልና ከእኔ ዘንድ የሚገኝ የጻድቃን ደስታቸው እንደዚሁ ነው።'),
  ('c1187238-6399-524d-aaa3-3739047ea0f6', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 16, 60, 'ስለሚድኑ ስለ ጥቂቶች ደስ ይለኛል፤ ክብሬን ያገኛሉና። ስሜም በእነርሱ ተመስግኖአልና።'),
  ('6bc0702f-6a70-5b70-a554-656b785bab93', 'be69d268-6c2b-54fa-a4ff-2a905683a563', '60876c8f-9aa6-53b0-adf6-b18eed226f91', 17, 61, 'ስለሚጠፉ ስለ ብዙዎች ልቡናዬን አላሳዝነውም። እነርሱ ዛሬ በእሳት ተመስለዋልና፥ እንደ እሳት ነበልባልም ሆነዋልና፥ እንደ ጢስም ነድደውና ተንነው ጠፍተዋልና።”'),
  ('3bc99036-ffbd-5ee2-a455-2aae1ec3e1a4', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 1, 62, 'እኔም መለስሁለት፤ እንዲህም አልሁት፥ “ምድር ሆይ እንዳንቺ ያለ ልዩ ፍጥረት ከመሬትሽ ለምን ተገኘ?'),
  ('199f2fa5-e0dd-558e-a180-4d35b03da934', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 2, 63, 'ነገር ግን ክፉ ልቡና ከሚፈጠርልን ይልቅ ባይፈጠርልን በተሻለን ነበር።'),
  ('cb514067-17fc-5694-aa13-a3b7ad90da42', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 3, 64, 'ክፉ ልብም ከእኛ ጋር ያድጋል፤ ስለ እርሱም ይፈረድብናል፤ ሳናውቀው እንጐዳለንና።'),
  ('3791900f-87ed-5fea-a0a4-68867adf1ef6', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 4, 65, 'የሰው ልጆች ያልቅሱ፤ የምድረ በዳ አውሬዎች ግን ደስ ይበላቸው፤ ከአዳም የተወለዱ ሁሉም ያልቅሱ፤ የእንስሳ መንጋዎችም ደስ ይበላቸው።'),
  ('8a6c5ed3-d699-5681-a487-e37fcb80bdda', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 5, 66, 'የሚጠብቃቸው ቍርጥ ፍርድ ስለሌለ፥ ፍርድንም ገሃነምንም ስለማያውቁት፥ ከሞቱም በኋላ መነሣትን ተስፋ ስለማያደርጉ እነርሱ ከእኛ እጅግ ይሻላሉና።'),
  ('0ebc9ad4-9b43-5915-ada9-4ef7b3bd2452', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 6, 67, 'የምንነሣው ትንሣኤ ምን ይጠቅመናል?'),
  ('e4fbdc9e-45f4-5d3f-adbd-f76a3925fb0d', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 7, 68, 'የተወለድን ሁሉ በኀጢአት ተሰጠምን፤ ዐመፅንም ተሞላን፤ በደላችንም ጸና።'),
  ('67dd34f4-db2a-5880-a92b-fc0ebf01b25c', 'be69d268-6c2b-54fa-a4ff-2a905683a563', 'ce4ecc81-b71b-588d-ae65-e01a114cf1c6', 8, 69, 'ከሞትን በኋላ ወደ ፍርድ ባንሄድ በተሻለን ነበር አልሁት።”'),
  ('5161b2f5-dfec-53f8-aeec-23e407657de5', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '59c49fc7-6b49-5c86-a403-b4b5af766374', 1, 1, 'መልአኩም መለሰልኝ፤ እንዲህም አለኝ፥ “ልዑል ይህን ዓለም፥ አዳምንና ከእርሱ የተወለዱትንም ሁሉ በፈጠራቸው ጊዜ ቍርጥ ፍርድንና ቅጣቱን አስቀድሞ አዘጋጀ።'),
  ('a231639d-d0fa-5f53-a702-8cb0ff8decd8', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '59c49fc7-6b49-5c86-a403-b4b5af766374', 2, 2, 'አሁንም ከቃልህ የተነሣ አስተውል፤ እንዲህ ብለሃልና፦ ‘ክፉ ልብ ከእኛ ጋር ያድጋል፤'),
  ('4e4d0005-5973-581d-aab5-beebf0a76014', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '59c49fc7-6b49-5c86-a403-b4b5af766374', 3, 3, 'በምድር የሚኖሩም ስለ እርሱ ይፈረድባቸዋል፥ አእምሮ ሳላቸው ይበድላሉና፥ ሕጉንም በልቡናቸው ተቀብለው ትእዛዙን አልጠበቁምና፥ ሕጉንም ተምረው የተቀበሉትን ሕጉንና ትእዛዙን ትተዋልና።'),
  ('7a0e6af4-e9f2-5950-a0cf-d245ad8a2e29', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '59c49fc7-6b49-5c86-a403-b4b5af766374', 4, 4, 'እንግዲህ በቍርጥ ፍርድ ቀን ምን ይሉ ዘንድ አላቸው? በኋለኛው ዘመንስ ምን ይናገራሉ?'),
  ('ec7bc2c2-6195-524f-ac47-c80a48bf1917', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '59c49fc7-6b49-5c86-a403-b4b5af766374', 5, 5, 'ልዑል በዚህ ዓለም የሚኖሩ ሰዎችን ምን ያህል ታገሣቸው? ነገር ግን ስለ ወሰነው ጊዜ ነው እንጂ ስለ እነርሱ አይደለም።”'),
  ('32ec2966-0042-50bd-aefe-51a890c0d550', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 1, 6, 'እኔም መለስሁለት እንዲህም አልሁት፥ “በፊትህ ባለሟልነትን ካገኘሁ ይህንም ለባሪያህ ንገረው፤ በሞትን ጊዜ፥ ከእኛ ከእያንዳንዳችንም ነፍሳችን በምትወጣበት ጊዜ ቍርጥ ፍርዱን የሚያደርግበት ጊዜው እስኪደርስ ድረስ ይጠብቁናል? ወይስ ከዛሬ ጀምሮ ይፈረድብናል?”'),
  ('70ab4331-4049-51fd-a8b6-faf9bde272e8', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 2, 7, 'እርሱም መለሰልኝ እንዲህም አለኝ፥ “ይህንም እነግርሃለሁ፤ አንተ ግን ከከሓድያን ጋር አትጨመርም፤ ከሚፈረድባቸውም ጋር አትቈጠርም።'),
  ('f4a7fa83-6939-5bf5-ab7f-70cd537295ab', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 3, 8, 'በልዑል ዘንድ የተዘጋጀ መዝገብ ለአንተ አለህና፥ ነገር ግን እስከ ኋለኛው ቀን ድረስ አልገልጥልህም።'),
  ('1bde8655-0318-50ce-a3eb-b7464d6ce82e', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 4, 9, 'የሞትስ ነገር እንዲህ ነው፤ ከልዑል ዘንድ የትእዛዝ ቃል ከመጣ በኋላ፥ እገሌ ይሙት ባለ ጊዜ ነፍሱ ከሥጋው ትለያለች፤ ዳግመኛም ወደ ሰጣት ትመለሳለች፤ ለልዑል ጌትነትም አስቀድማ ትሰግዳለች።'),
  ('cfff93c6-145c-530d-ae04-18ba7781f971', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 5, 10, 'የልዑልን መንገዶች ካልጠበቁ፥ የልዑልን ሕግ ካቃለሉ፥ እርሱንም መፍራትን ካላሰቡ ከከሓድያን ወገን ከሆኑ ግን፥'),
  ('864f7c60-1194-5b65-ac5b-6707747ab67c', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 6, 11, 'እነዚያ የኃጥኣን ነፍሳት ይዞራሉ እንጂ ወደ ጻድቃን ማደሪያ አይገቡም፤ ከዚህ በኋላ መከራ ይቀበላሉ፤ ይጨነቃሉ፤ ያዝናሉም፤ ሰባቱንም ሥርዐታት ያሳዩአቸዋል።'),
  ('b80c86f5-fe0e-54e8-aa7a-be6a457f1fbf', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 7, 12, 'መጀመሪያዪቱ ሥርዐት ይህች ናት፤ የልዑልን ሕግ ክደዋልና።'),
  ('995825e2-86b0-543a-afc9-e3d78e4e7c37', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 8, 13, 'ሁለተኛዪቱም ሥርዐት እንዲህ ናት፤ ከእንግዲህ ወዲህ ዳግመኛ በሕይወት ይኖሩ ዘንድ መመለስ አይቻላቸውምና።'),
  ('1824021b-4a0f-59aa-aa40-8fc8c9c3e9cd', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 9, 14, 'ሦስተኛዪቱም ሥርዐት እንዲህ ናት፥ በልዑል ሥርዐት ላመኑ የተዘጋጀላቸውን ዋጋ ያያሉና።'),
  ('10238c82-6a17-5a6e-a194-c099f097288e', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 10, 15, 'አራተኛዪቱም ሥርዐት እንዲህ ናት፤ በኋላ ዘመን የሚጠብቃቸውን ፍርድ ያያሉና።'),
  ('5cbb7fd4-e3a6-52b6-a133-d222904359a8', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 11, 16, 'አምስተኛዪቱም ሥርዐት እንዲህ ናት፤ መላእክት የጻድቃንን ነፍስ በማደሪያቸው ውስጥ በብዙ ዕረፍት ሲጠብቋቸው ያያሉና።'),
  ('c8ed0d22-049f-55c4-aaf6-9bf759e0d66b', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 12, 17, '“ስድስተኛዪቱም ሥርዐት እንዲህ ናት፤ ከዛሬ ጀምሮ የሚያገኛቸውን መከራ እያዞሩ ያሳዩአቸዋልና።'),
  ('b53a0f51-f605-5fe3-a14e-cd8cf7999452', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 13, 18, 'ከነገርሁህ ሥርዐታት ሁሉ የምትበልጥ ሰባተኛዪቱ ሥርዐት እንዲህ ናት፤ በፊቱ ይፈረድባቸው ዘንድ ያላቸው ዛሬ በሕይወታቸው ሳሉ እርሱን የበደሉ በፊታቸው የልዑልን ጌትነት ባዩ ጊዜ በኀሣር ይቀልጣሉና፥ በኀፍረትም ይጐሳቈላሉና፥ በፍርሀትም ይጠወልጋሉና።'),
  ('ee3399d7-2d15-544f-ac60-af514a7b5f1b', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 14, 19, '“የልዑልን ሕግ የጠበቁ ግን ከመዋቲ ሥጋቸው በሚለዩበት ጊዜ ሥርዐታቸው እንዲህ ናት።'),
  ('5d783181-b50f-5c36-a3c6-d2df44f97aad', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 15, 20, 'በኖረበት ዘመን ሁሉ ያስተማራቸው የልዑልን ሕግ ይፈጽሙ ዘንድ መከራቸውን ታግሠው ሁልጊዜ በድካም ለእግዚአብሔር ተገዝተውለታልና።'),
  ('d1199acd-1246-5710-a71a-eb48e5e939e0', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 16, 21, 'ስለዚህ ነገራቸው እንዲህ ነው።'),
  ('a757d4df-4e93-5a77-a3a3-c1640a099bbe', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 17, 22, 'መጀመሪያ የተቀባያቸውን የእግዚአብሔርን ጌትነት በብዙ ደስታ ያያሉ፤ ወደ ሰባቱም ሥርዐታት ይወስዷቸዋል።'),
  ('72cf25c6-c0aa-56f9-a665-a1a7fab9e796', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 18, 23, 'መጀመሪያዪቱ ሥርዐት እንዲህ ናት፤ በዛሬው ሕይወታቸው በሞት እንዳያስታቸው በእነርሱ ያለ ክፉ አሳብን ድል ይነሡ ዘንድ በብዙ ድካም ተጋድለዋልና።'),
  ('04f39c73-da85-57f1-abd1-011606e6f4cb', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 19, 24, 'ሁለተኛዪቱም ሥርዐት እንዲህ ናት፤ የኃጥኣንን ነፍሳት በሚዞሩበት ያዩአቸዋልና፤ የሚጠብቃቸውንም ፍርድ ያያሉና።'),
  ('a4b3bd59-3235-586c-ad6a-9db88fc68d71', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 20, 25, 'ሦስተኛዪቱም ሥርዐት እንዲህ ናት፥ በሕይወት ሳሉ በሃይማኖት የተቀበሉትን ሕጉን እንደ ጠበቁ የፈጠራቸው ምስክር ይሆንላቸዋልና።'),
  ('c7632f97-4de0-5876-a19d-a3872ee1071e', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 21, 26, 'አራተኛዪቱም ሥርዐት እንዲህ ናት፥ መላእክት እየጠበቋቸው ብዙ ደስታ ባለባቸው ማደሪያዎቻቸው ከዛሬ ጀምሮ የሚያርፉትን ዕረፍትና የሚቈያቸውን ክብር ያያሉና።'),
  ('942ea59d-0d7e-5c13-aa1b-8451af5fb5ca', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 22, 27, 'አምስተኛዪቱም ሥርዐት እንዲህ ናት፤ ዛሬ ያለውን ሞት እንዴት ድል እንደነሡትና ኋላ ያገኙት ዘንድ ያላቸውን እንደ ወረሱ አይተው ደስ ይላቸዋልና፤ ዳግመኛም ድካምን ከተመላ ከዚህ ከጠባቡ የተነሣ እንደታገሡ፥ ያን ሰፊውን ሕይወት እንደሚያገኙ ያያሉ። ሞት በሌለበትም ለዘለዓለም ደስ ይላቸዋል።'),
  ('c1337733-1ec7-5f95-ae33-0a012c53542f', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 23, 28, 'ስድስተኛዪቱም ሥርዐት እንዲህ ናት፤ ፊታቸው እንደ ፀሐይ እንደሚያበራ፥ ብርሃናቸውም እንደ ከዋክብት እንደሚያንጸባርቅ ያሳዩአቸው ዘንድ አላቸውና፥ ከእንግዲህ ወዲህም አይሞቱምና።'),
  ('f00a9f1c-f401-5d4b-a046-4a3f6ed02eb1', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 24, 29, 'ከሁሉ የምትበልጥ ሰባተኛዪቱም ሥርዐት እንዲህ ናት፤ በእርሱ ዘንድ ይከብሩና ዋጋ ያገኙ ዘንድ ያላቸው በሕይወት ሳሉ የተገዙለትን ፊቱን ያዩ ዘንድ የሚቸኩሉ ስለ ሆነ ሳያፍሩ በብዙ ደስታ ተማምነው በግልጥ ይመካሉና።'),
  ('daa68a33-9c9d-5a2f-aee8-073891c3ac0a', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 25, 30, '“ከዛሬ ጀምሮ ያገኙ ዘንድ ያላቸው የጻድቃን ነፍሳት ሥርዐታቸው ይህ ነው፤ ከሓድያንም መከራ ይቀበሉ ዘንድ የነገርሁህ ሥርዐታቸው፥ መንገዳቸውና ፍርዳቸው ይህ ነው።”'),
  ('3480205d-4e21-57f7-a323-14cbc1802850', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 26, 31, 'እኔም መለስሁለት እንዲህም አልሁት፥ “ከሥጋዋ ከተለየች በኋላ ይህን የነገርኸኝን ታይ ዘንድ ለነፍስ ቀን ይሰጣታልን?”'),
  ('be456640-f735-5fab-a7be-8328f3b9ffe6', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 27, 32, '“በእነዚያም በሰባቱ ቀኖች ይህን የነገርሁህን ሥራቸውን ሁሉ ያዩ ዘንድ ለሰባት ቀን ነጻ ናቸው፤ ከዚያም በኋላ ወደ ቦታቸው ይመለሳሉ” አለኝ።'),
  ('c507a654-cedf-566f-a29d-a385bb0ba62c', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 28, 33, 'እኔም መለስሁለት እንዲህም አልሁት፥ “አቤቱ ጌታዬ፥ በፊትህ ባለሟልነትን ካገኘሁ ይህንም ለባሪያህ ዳግመኛ ንገረው፤ በፍርድ ቀን ጻድቃን በልዑል ዘንድ ለኃጥኣን መለመን ይችላሉን?'),
  ('5fddceaf-a65e-54ce-ab72-d7010a34ad37', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 29, 34, 'አባቶችም ለልጆቻቸው፥ ልጆችም ለአባቶቻቸው፥ ወንድሞችም ለወንድሞቻቸው፥ ዘመዶችም ለዘመዶቻቸው፥ ወዳጆችም ለወዳጆቻቸው መለመን ይችላሉን?”'),
  ('e57a98f6-533b-551d-a20a-f18219bc8ce4', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 30, 35, 'እርሱም መለሰልኝ እንዲህም አለኝ፥ “በፊቴ ባለሟልነትን አግኝተሃልና ይህንም እነግርሃለሁ፦ የፍርድ ቀንስ ለአንድ ጊዜ ናት፤ በሁሉም ትእዛዝ ላይ የእውነት ማኅተምን ያሳያቸዋል።'),
  ('71736388-a448-58b4-aa5f-d9123ed40715', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 31, 36, 'ዛሬ አባት ልጁን ስለ እርሱ፥ ልጅም አባቱን፥ ጌታም አገልጋዩን፥ ወዳጅም ወዳጁን ስለ እርሱ ታሞ ይተኛ ዘንድ፥ በልቶና ጠጥቶም ደስ ይለው ዘንድ፥ ይፈወስም ዘንድ እንደማይልከው፥'),
  ('a56174fe-027d-5c8c-ae06-84e8c9a54c87', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 32, 37, 'እንደዚሁ አንዱ ለሌላው መለመን ፈጽሞ የሚችል ማንም የለም፤ የራሱንም ሸክም በባልንጀራው ላይ የሚመልስ ማንም የለም። ሁሉም ዋጋውን ያገኛልና፥ ሥራውም የየራሱ ነውና።”'),
  ('f4cb4105-e062-552c-a540-48dc5688bee2', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 33, 38, 'እኔም መለስሁለት እንዲህም አልሁት፥ “ቀድሞ አብርሃም ስለ ሰዶምና ገሞራ፥ ሙሴም በምድረ በዳ በበደሉ ጊዜ ስለ አባቶቻችን እንደ ለመነ ዛሬ እንዴት አገኘን?'),
  ('e111ba33-bd9f-56e5-a3fa-24f231c45c74', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 34, 39, 'ኢያሱ በአካን ዘመን ስለ እስራኤል፥ ሳሙኤልም በሳኦል ዘመን፥'),
  ('2d6d59fa-00eb-596e-a5c4-741da31e98c2', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 35, 40, 'ዳዊትም ስለ ቸነፈር፥ ሰሎሞንም ስለ ቤተ መቅደስ፥ ኤልያስም ስለ ዝናምና ስለ ሙታን ይድኑ ዘንድ፥'),
  ('154e8aa6-4499-5110-ac64-93c8b9830334', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 36, 41, 'ሕዝቅያስም በሰናክሬም ዘመን ለሕዝቡ፥ ብዙ ሰዎችም ስለ ብዙዎች ለመኑ።'),
  ('5504c707-7a22-534d-ac01-20f825185be8', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 37, 42, 'እንግዲህ ዛሬ መዋቲው በሕይወት ሳለ፥ ኀጢአትም በዝታ ሳለች ጻድቃን ስለ ኃጥኣን ከለመኑ ያንጊዜስ እንደዚሁ እንደ ምን አይሆንም?”')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('cfe0b87f-15a3-50fc-a7bd-a9a629fb0b08', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 38, 43, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “የዚህ የዛሬው ዓለም ፍጻሜው ገና አልሆነምና፤ የእግዚአብሔርም ክብር በውስጡ ለዘለዓለም ተገልጦ የሚኖር አይደለምና-። ስለዚህም ጽኑዓን ለድኩማን ለመኑ።'),
  ('e0c838c9-6397-5745-ad49-e3097a026ee6', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 39, 44, 'የፍርድ ቀንስ የዚህ ዓለም መጨረሻ ናት፤ መዋቲው ያልፍ ዘንድ፥ የማያልፈውም ይተካ ዘንድ፥ ለሚመጣው ዓለም መጀመሪያ ናት።'),
  ('1802a90f-84ae-5265-afed-98fadde9d8e3', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 40, 45, 'ከዚህ በኋላ ድካም ይሻራል፤ ጠብም ይጠፋል፤ ጽድቅም ታብባለች፤ ቅንነት ትጸናለች።'),
  ('0a021057-a20b-5cf0-a238-504d3361f2a7', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 41, 46, 'ያንጊዜ በፍርድ ድል የተነሣ ሰውን ይቅር ማለት የሚቻለው የለም፤ ድል የነሣውንም መከራ ሊያጸናበት የሚችል የለም።”'),
  ('d9ef9862-7a67-5828-a49c-f57c6c01cad1', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 42, 47, 'እኔም መለስሁለት፤ እንዲህም አልሁት፥ “ቃሌ እንደ ቀደመው ነው፤ አሁንም እንዲህ እላለሁ፦ ምድር አዳምን ባታስገኘው በተሻለ ነበር፤ ከአስገኘችውም እንዳይበድል ባስተማረችው ነበር።'),
  ('b28dbb1d-8d46-56b7-a541-eed6b98ac506', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 43, 48, 'ሁላችን የምንኖረው ሕይወት ምን ይጠቅመናል? በኀዘን እንኖራለንና፤ ከሞትንም በኋላ ዳግመኛ ፍርድ ይቈየናልና።'),
  ('f684a978-c7f9-5d48-a52f-e4b411fa766f', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 44, 49, 'አዳም ሆይ! ምን አደረግንህ? አንተ ባትበድል ይህች መከራ በእኛ ላይ ባልመጣችብን ነበር።'),
  ('deaf5b28-586e-5da9-a152-24c17ba2481f', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 45, 50, 'ተስፋ ያስደረግኸን፥ ሞት የሌለበት የሚመጣው ዓለም ምን ይጠቅመናል? እኛ ግን ሞትን የሚያመጣ ሥራን ሠራን።'),
  ('a79f755f-1e4b-5719-a9f9-0239fad24919', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 46, 51, 'የነገሩንን በጎውን ተስፋ አልሠራንም፤ እኛ ግን ክፉ ሥራን ሠራን። ዐመፅንም ተከተልን።'),
  ('ebde09bb-c981-568d-ae8e-1f26c93d7085', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 47, 52, 'ኀዘንና ደዌ የሌለባቸውን፥ ለእኛ የተዘጋጁትን ቤቶች አልተከተልንም። እኛ ግን ኀጢአትን ሠራን።'),
  ('3b39b444-84c8-5fd5-a3dd-90448833eb5f', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 48, 53, 'ያጸናቸው ዘንድ መከራ የተቀበሉ ጻድቃን የልዑልን ጌትነት ያዩ ዘንድ አላቸውና፤ እኛ ግን በበደላችን ኖርን።'),
  ('751a1234-3bd3-5bfb-aecf-dfa04dd07463', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 49, 54, 'ፍሬው የማይጠወልግ ገነት ይገለጣልና፥ በውስጡም የሚገኘው ፍሬ ደስታና ሕይወት ነውና።'),
  ('a0d94e2e-c9cd-5d19-a294-697b7c76e91e', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 50, 55, 'እኛ ግን አንገባም፤ የማንመሰገንበትን ሥራ እንሠራለንና።'),
  ('0aff4580-c2f2-58d2-ab65-f88a7cb8d154', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 51, 56, 'ትዕግሥትን ያጸኗት ፊታቸው ይበራልና፥ የእኛ ፊት ግን ከጨለማ ይልቅ ይጠቍራል።'),
  ('a8e863d4-3bd3-50f1-a934-3a8eb4026939', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 52, 57, 'እነሆ፥ ከሞትን በኋላ በእኛ ላይ ምን እንዳለ ሳናውቅ እንኖራለን።”'),
  ('a8f6d661-46bd-5c1d-aef4-ed94604c582d', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 53, 58, 'መልአኩም መለሰልኝ እንዲህም አለኝ፥ “በዚህ ዓለም ለሚጋደል፥ በምድር ለተወለደ ሰው የታሰበለት ይህ ነው።'),
  ('404732c0-40cd-5e29-af60-173c833b7429', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 54, 59, 'ድል ያደረገ እኔ ያልሁትን ያገኛል፤ ድል የተነሣ ግን አንተ ያልኸውን ያገኛል።'),
  ('f4d7cdb2-a100-58bd-aa3f-00f94958e59b', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 55, 60, 'ትድኑ ዘንድ ሕይወትን ምረጧት ብሎ ሙሴ ለሕዝቡ የነገራቸው መንገድ ይህች ናት። ነገር ግን እርሱን አልተቀበሉትም፤ ከእርሱም በኋላ ነቢያትን የተናገርኋቸው እኔንም አልተቀበሉም።'),
  ('9ce0a48a-8269-5970-a6e7-923fa06fee28', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 56, 61, 'በሚያምኑ ሰዎች ደስታ እንዳለ በሚጠፉት ሰዎች ኀዘን የለም።”'),
  ('8156ddf1-26ac-5bf4-a52c-de2198c9602b', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 57, 62, 'እኔም መለስሁለት እንዲህም አልሁት፥ “አቤቱ፥ ምንጊዜም እንደ ኢምንት የሆኑትን ይቅር ባላቸው ጊዜ ልዑል ዛሬ ይቅር ባይ እንዲባል ፈጽሜ አውቃለሁ።'),
  ('a05af353-a3db-55fc-a541-aef66cc72f13', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 58, 63, 'ይቅር ባይ ነው፤ ወደ ሕጉ የተመለሱትን ይቅር ይላቸዋልና።'),
  ('899b44c8-2e05-5b4f-acd8-22e5b401ce52', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 59, 64, 'ታጋሽም ነው፤ የበደሉትን ሰዎች እንደ ልጆች ይታገሣቸዋልና።'),
  ('8f5c381b-36ab-5f73-a641-0472272579e7', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 60, 65, 'ለጋስም ነው፤ እንደ ሥራቸው እንደሚገባቸው መጠን ለነገርሁህ ሰዎች ይሰጣቸዋልና።'),
  ('0d8a51e2-b0a3-5a72-ac2e-b32807701ade', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 61, 66, 'ምሕረቱም የበዛ ነው፤ ላሉት፥ ለሚታዘዙትም፥ ይመሰገኑ ዘንድ ላላቸውም ቸርነቱን ፈጽሞ ያበዛልና።'),
  ('8e3dd93d-25e4-5d57-a2f2-25ff75bec36e', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 62, 67, 'ቸርነቱን ፈጽሞ ካላበዛ ይህ ዓለም ባልኖረ ነበርና፥ በእርሱም ያሉ ባልኖሩ ነበርና።'),
  ('bffd78b5-687e-5245-a369-48f2610b99ed', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 63, 68, 'ለጋስም ነው፤ ኃጥኣን ከኀጢአታቸው ይመለሱ ዘንድ ከቸርነቱ ካልሰጣቸው ሰው ሁሉ ባልዳነ ነበርና።'),
  ('a1fcd011-dcd1-58f1-a1b9-9a086517129c', 'bc8877f7-ddc1-55de-aad3-a7ff6f332ef5', '8dfc0235-6247-5901-a379-d7ea805b7dcb', 64, 69, 'ፈራጅም ነው፤ እርሱ የፈጠረውን ፍጥረት ካልጠበቀ የከሓድያን ብዛታቸው ይጠፋልና፤ ከቍጥራቸውም ብዛት አይቀርምና። ያም ባይሆን በጣም ጥቂት ነው።”'),
  ('5eac73c7-b2fd-5b88-a934-2e05469e2f33', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 1, 1, 'መልአኩም መለሰልኝ እንዲህም አለኝ፥ “ይህንስ ዓለም ልዑል ስለ ብዙዎች ፈጠረው፤ የሚመጣውን ግን ስለ ጥቂቶች ፈጠረው።'),
  ('47d6f001-0f20-5f98-a640-559802e2c8b0', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 2, 2, '“ዕዝራ! እነሆ በፊትህ ምሳሌውን እተረጕምልሃለሁ፤ ምድርን ጠይቃት፤ ትነግርሃለችም፤ ከእርሱ ሸክላ የሚገኝበትን መሬት ታስገኛለችና፥ መሬትም ወርቅ ከእርሱ የሚገኝበትን ታስገኛለችና፥ ከወርቅ ይልቅ ሸክላ እጅግ ይበዛል።'),
  ('feeb7bc8-4920-5806-aaad-3e03d9a21a69', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 3, 3, 'የዚህ ዓለም ሥራም እንዲሁ ነው፤ በውስጡ የተፈጠሩ ብዙ ናቸው፤ የሚድኑ ግን ጥቂቶች ናቸውና።”'),
  ('a066e49b-a84b-5d34-a601-6830df4187d1', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 4, 4, 'እኔም መለስሁለት እንዲህም አልሁት፥ “ልብ ከጥበብ የተነሣ ደስ ይበላት፤ ጆሮም ነገርን ትጠጣ።'),
  ('79eeedc1-cf46-5986-a3a0-dcf9e5949f8a', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 5, 5, 'ጆሮ ለመስማት ተሠርትዋልና፥ ልብም ለማወቅ ተፈጥሯልና፥ ሰው ከጥቂት ሕይወት በቀር ሳይሰጠው ባልወደደው ይሄዳል።'),
  ('bdf6250c-9895-5652-a4a0-48f049a1e488', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 6, 6, 'አቤቱ ለባሪያህ ከፈቀድህለት፥ ዓለም ሰውን በሚችለው ገንዘብ ሙታን ሁሉ መኖርን ይችሉ ዘንድ እንዲያፈራልን እናርስና እንዘራ ዘንድ ልብንና ሕሊናን ብትሰጠን በተሻለን ነበር።'),
  ('093f387c-a8d3-57eb-a48a-bba2e819f446', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 7, 7, 'የእጆችህ ፍጥረት እኛ አንተ እንደተናገርህ ሁላችን የተካከልን ነንና።'),
  ('4eb239c1-35b4-53fa-a7a6-1fb57edb6e02', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 8, 8, 'ዛሬ በማኅፀን ትፈጥረዋለህና፥ ሥጋንና ሕዋሳትንም ትቀርጽለታለህና፥ ማስተዋልንም ትሰጠዋለህና፥ በእሳትና በውኃ ትጠብቀዋለህና፥ ያን የፈጠርኸውንም በማኅፀን ዘጠኝ ወር ትሸከመዋለህና፥ ባንተም ቃል ይጠበቃልና።'),
  ('5b4ac55e-81c5-5a80-ab4e-256cc857e11f', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 9, 9, 'ዳግመኛም እናቱ በወለደችው ጊዜ፥ ከተወለደና ከተፈጠረ በኋላ፥ የሚጠባበትን ወራት እስኪጨርስ ድረስ ይህ ባሪያህ ሕፃኑ ያድግ ዘንድ፥'),
  ('126e1687-064a-5903-a2e2-0c3a1f02978b', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 10, 10, 'ከሰውነትዋ በላይ ካሉ ከጡቶችዋም የጡት ፍሬ ወተት ይፈስለት ዘንድ ታዝለታለህ፥'),
  ('9388f7cb-08c5-59d5-a5cf-95f94096ea13', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 11, 11, 'ይህ ባሪያህ እስከ ጊዜው ድረስ ያድግ ዘንድ በቸርነትህ ታሳድገዋለህ።'),
  ('3d683bdf-7241-57f9-a4c3-69e04a3467a8', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 12, 12, 'በቸርነትህም ትመግበዋለህ፤ ሕግህንም ታስተምረዋለህ፤ በጥበብህም ትገሥጸዋለህ።'),
  ('f0e9831e-07b5-5e7b-a20d-e91dadd2330d', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 13, 13, 'ከዚህ በኋላ የፈጠርኸውንና ሕያው ያደረግኸውን ያን ባሪያህን ትገድለዋለህ።'),
  ('125c0f3c-9ab8-5b16-a1af-045b12e5891f', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 14, 14, 'ፈጥረህ ይህን ያህል ዘመን ያኖርኸውን ያን ባሪያህን የምታጠፋው ከሆነ እንግዲያ ለምን ፈጠርኸው?'),
  ('57fddd26-3a07-5a8a-a32a-7aa21a074d4e', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 15, 15, 'አሁንም ነገርህ እውነት ነው፤ ስለ ሁሉም አንተ ታውቃለህ፤ ነገር ግን እናገር ዘንድ እኔን ያተጋኝ አይደለም።'),
  ('458b8d6e-4072-5c81-a2a7-a0f4e81a85df', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 16, 16, 'ይህን የማዝን ስለ ወገኖችህና ስለ ርስትህ ነው እንጂ።'),
  ('8bc9c7d6-cdc0-5e4b-a318-b6b2cbbafac2', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 17, 17, 'ይህንም በፊትህ እማልድ ዘንድ የጀመርሁት ስለ እኔም፥ ስለ እነዚያም ነው። የሚመጣውን ዓለም ሕጉን እየሰማን የምንኖር የእኛን መሰነካከል አያለሁና።'),
  ('acf09124-7c58-52c4-a0b9-fccc8bf8c01b', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', '71dad071-1074-51d9-a031-cc7dd0f0e5eb', 18, 18, 'ስለዚህም ቃሌን ስማ፤ በፊትህ የምናገረውንም ልመናዬን አድምጥልኝ።”'),
  ('7eda3cbb-7216-5fe7-a923-12282e962277', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 1, 19, 'ሳይወስዱት የዕዝራ የጸሎቱ ቃል መጀመሪያ ይህ ነው።'),
  ('70c1e3c5-943f-5128-a79c-28c755eb0705', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 2, 20, '“ለዘለዓለሙ የምትኖር አቤቱ፥ በልዑል አርያም ሁነህ የምታይ፥ በሰማይ ያለህ፥'),
  ('a3f084fd-ac9e-5d63-adb6-76e5b6e187dd', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 3, 21, 'ሥልጣንህ የማይሸነፍ፥ መንግሥትህ የማያልፍ፥ ሠራዊተ መላእክት በፍርሀት የሚቆሙልህ፥'),
  ('aa207059-7117-51f1-a3e3-79ab5d2e55b6', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 4, 22, 'ነፋስና እሳት በትእዛዝህ የተፈጠሩ፥ ቃልህ ጽኑ የሆነ፥ የተናገርኸውም ጸንቶ የሚኖር፥'),
  ('ff2d6452-386c-5e45-a40a-8f3f3651c23a', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 5, 23, 'ሥርዐትህ ጽኑ የሆነ፥ ትእዛዝህም የሚያስፈራ፥ ትእዛዝህም ጥልቆችን የሚያደርቅ፥ ቍጣህም ተራራዎችን የሚያቀልጥ፤ ሕግህም እውነት የሆነ፥'),
  ('a2f38efe-a0a6-5688-a7db-20fd10e733e9', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 6, 24, 'አቤቱ፥ የባሪያህን ቃል ስማ፤ የባሪያህን ልመና አድምጥ፤ ነገሬንም አድምጥ።'),
  ('beaccda2-b217-59ad-a0ec-3efac587e2d5', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 7, 25, 'እኔ በሕይወት ሳለሁ እነግርሃለሁ፤ ልቡናዬም እንዳሰበ መጠን እነግርሃለሁ፤ እመልስልሃለሁም።'),
  ('7c840448-76ae-5842-aae6-507796ab81a1', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 8, 26, 'የወገኖችህን በደል አትመልከት፤ ለአንተ የተገዙልህን ጽድቃቸውን ተመልከት እንጂ።'),
  ('cd267f92-7817-544d-adaa-69c81bfa5586', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 9, 27, 'የኃጥኣንን ሥራቸውን አትመልከት፤ በመከራቸው ሥርዐትን የጠበቁትን ተመልከት እንጂ።'),
  ('4fdcdd6d-965f-597d-a4e3-f247d1b8f00d', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 10, 28, 'በፊትህ ክፉ ሥራን ስለሠሩ አትቈጣ፤ በፍጹም ልባቸው በሕግህ የታመኑትን አስብ እንጂ።'),
  ('1a5607a5-d45f-5ad0-a186-21b0e0961743', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 11, 29, 'በሥራቸው እንደ እንስሳ የሆኑ ሰዎችን ጥፋት አትውደድ። ሥርዐትህን በብሩህ ልቡና ያጸኗትን አስባቸው፤ ተመልከታቸውም እንጂ።'),
  ('330a750f-5bbd-5a1b-a13b-a274598cab88', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 12, 30, 'ከአራዊት የከፉ ሰዎችን አትቈጣቸው። በጌትነትህ መታመን ያዘወተሩትን ውደዳቸው እንጂ።'),
  ('bf15b0f8-4420-5368-aa18-a85a4eb37fd8', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 13, 31, 'ነገር ግን እኛና ከእኛ አስቀድሞ የነበሩ ሞትን የሚያመጣ ሥራን ሠራን።'),
  ('f908a696-e737-55b5-ace3-47702bcb3080', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 14, 32, 'አንተ ግን ስለ እኛ፥ ስለ በደሉ ሰዎችም ይቅር ባይ ሁን፤ በጎ ሥራ የሌለን እኛን ይቅር ብትለን ያንጊዜ ይቅር ባይ ትባላላህና።'),
  ('84bdf6da-e99f-5385-a3c4-0c1055fa41eb', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 15, 33, 'በአንተ የተዘጋጀ በጎ ሥራ ያላቸው ጻድቃንን ግን በሥራቸው ይቅር ትላቸዋለህ።'),
  ('a18b8499-db00-5b19-a2ec-110af95c0159', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 16, 34, 'ትቈጣው ዘንድ ሰው ምንድን ነው? ስለ እርሱስ ታዝን ዘንድ የመዋቲ ወገን ምንድን ነው?'),
  ('a949d687-7ea9-5b73-a0ed-c2ff98b43382', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 17, 35, 'አሁንም ከተወለደው ወገን የማይበድል እንደሌለ እውነት እናገራለሁ።'),
  ('fcaafe8f-c99c-5da6-a6fc-a03a04663511', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 18, 36, 'ነገር ግን ጌታ ሆይ፥ ስለዚህ በጎ ሥራ የሌላቸውን ይቅር ብትላቸው ቸርነትህ ፈጽሞ ይታወቃል።”'),
  ('23e19a6e-ab0f-5ee6-a401-08f4c04946d5', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 19, 37, 'እርሱም መለሰልኝ እንዲህም አለኝ፥ “በእኔ ዘንድ እውነትን ተናገርህ፤ አንተ እንደ ተናገርኸው እንዲሁ ነው።'),
  ('ddf28166-e3df-551f-ad82-11374c0be9a2', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 20, 38, 'ለሚበድሉ ሰዎች ሞትን፥ ፍርድንም፥ ጥፋትንም በእውነት አልወድላቸውም።'),
  ('105d8b66-e0dd-5bc8-a24f-38638f647c8d', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 21, 39, 'ነገር ግን ስለ ጻድቃን ደስ ይለኛል፤ የሚድኑ ዋጋቸውን ያገኛሉና።'),
  ('04b52fd0-7618-54c7-ab4b-0d1df4f4165c', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 22, 40, 'እንደ ተናገርኸውም እንዲሁ ይሆናል።'),
  ('8af84e33-1583-52a6-a99d-1c2dd5d08e8c', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 23, 41, 'ገበሬ ብዙ ዘር እንደሚዘራ፥ ብዙ ተክልንም እንደሚተክል፥ ጊዜውም ቢሆን ዘሩ ሁሉ የሚበቅል እንደ አይደለ፥ ተክሉም ሁሉ ሥር የሚሰድድ እንደ አይደለ፥ በዚህ ዓለም ያሉ ሰዎችም እንዲሁ ናቸው፤ ሁሉም የሚድኑ አይደሉም።”'),
  ('48acbcf3-7daa-5809-af29-e6ba36b0c7e0', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 24, 42, 'እኔም መለስሁለት፤ እንዲህም አልሁት፥ “በፊትህ ባለሟልነትንስ ካገኘሁ ልናገር።'),
  ('08fbe3ff-1bc6-53ed-ad7d-528fdf4531a8', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 25, 43, 'የገበሬ ዘርስ ባይበቅል ምናልባት ዝናም ባያገኝ ይሆናል፤ ስለዚህም ይጠፋል።'),
  ('cf333546-ebbd-551a-a438-088c951d9651', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 26, 44, 'ነገር ግን በእጅህ የፈጠርኸው፥ በአምሳልህም የመሰልኸው ሰው አምሳልህ ነውና፥ ስለ እርሱም ሁሉን ፈጥረሃልና፥ እንግዲህ እንደ ገበሬ ዘር ለምን ታደርገዋለህ?'),
  ('f84b006a-cab2-54fe-a4e4-c31570eb8682', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 27, 45, 'አቤቱ አገባብህም አይደለም፤ ለወገኖችህ ራራ፤ ርስትህንም ይቅር በል እንጂ፤ ፍጥረትህን ይቅር ትለዋለህና።”'),
  ('31573df3-9038-538f-a25e-9752ec9e0830', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 28, 46, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “በዚህ ዓለም ያለው በዚህ ዓለም ላሉት ምሳሌያቸው ነው፤ የወዲያው ዓለም ግን በወዲያው ዓለም ለሚኖሩ ምሳሌያቸው ነው።'),
  ('63a13f68-bf89-5372-a2b4-eef6941e701c', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 29, 47, 'ነገር ግን ዕውቀት ያነሰህ አንተ ከእኔ ይልቅ ፍጥረቴን ፈጽመህ ትወድድ ዘንድ፥ ይልቁንም አንተ ኃጥእ ሳትሆን በብዙ ወገን ኃጥእን ትመስላለህ።'),
  ('ebaf4fc1-0bff-5825-affe-14c3bcb10a3e', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 30, 48, 'ነገር ግን ስለዚህ በልዑል ዘንድ ትመሰገናለህ፤'),
  ('2de63fcc-a62e-5fc7-adef-2315bfb7b350', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 31, 49, 'ራስህን አዋርደሃልና፥ ፈጽመህም ትመሰገን ዘንድ እንደሚገባህ ራስህን እንደ ጻድቃን አላደረግህምና።'),
  ('61d7b733-38aa-59cf-a892-ac6d0ff564be', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 32, 50, 'አሁንም በዚህ ዓለም የሚኖሩ ጐስቋሎች በኋላ ዘመን ብዙ መከራን ይቀበላሉ። በብዙ ትዕቢት ኖረዋልና።'),
  ('732e8932-664e-5ee1-ad59-8166653ed04d', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 33, 51, 'አንተ ግን ለራስህ ዕወቅ፤ እንደ አንተ ያሉትንም ክብር መርምር፤'),
  ('79d1141d-05ed-5a16-a486-d4ebfa28a263', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 34, 52, 'ገነት ለእናንተ ተከፍታለችና፥ ዕፀ ሕይወትም ተተክሏልና፥ የሚመጣውም ዓለም ተዘጋጅቶ ተሠርትዋልና፥ ደስታም ተሠርታለችና፥ ዕረፍትም ተነጥፋለችና፥ በጎ በረከትም ጸንታለችና፥ የጥበብ ሥርዋ ተገኝትዋልና።'),
  ('b55139e4-295c-5aa3-a315-ef8692efb7cf', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 35, 53, 'እንግዲህ ወዲህ ደዌ አበቃ፤ ሞትም ጠፋ፤ መቃብርም ተሰወረች፤ ሙስናም ጠፋ።'),
  ('b8ca2926-1132-524b-a54d-bf1b3082dd4a', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 36, 54, 'መከራም ተዘነጋ፤ የሕይወት መዝገብም ተገለጠ።'),
  ('98410592-9fd7-534f-a6e3-abc50530101f', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 37, 55, 'እንግዲህ ወዲህ ስለሚጠፉት ሰዎች ብዛት መመራመርን አትድገም።'),
  ('337f012a-19e0-5857-aa08-7c943b6a9213', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 38, 56, 'እነርሱ ነጻነትን አግኝተው ልዑልን ንቀውታልና፥ ሕጉንም አቃልለዋልና፥ ሥርዐቱንም ትተዋልና።'),
  ('d01bc88a-20e7-5032-a375-26bf98836234', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 39, 57, 'ጻድቃኑንም ረግጠዋቸዋልና።'),
  ('cd2686a8-8d6c-50fc-ad1e-205b9eba4b67', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 40, 58, 'እንደሚሞቱም እያወቁ በልቡናቸው እግዚአብሔርን አንፈልገውም ብለዋልና።'),
  ('125de1a7-367a-5db8-aef7-4b1df1d64186', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 41, 59, 'ስለዚህም ይህ በጎው ለእናንተ እንደ ሆነ እንዲሁም ይህ ጥፋት ለእነርሱ ነው።'),
  ('0ef2111a-d2f4-5ec8-a167-1e2e13e48614', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 42, 60, 'እነርሱ ከተፈጠሩ በኋላ የፈጣሪያቸውን ስም አሳድፈውታልና፥ ያዘጋጀላቸውን እግዚአብሔርንም አላመሰገኑትምና።'),
  ('73c41367-da01-51d5-a475-2ea6c91c4a62', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 43, 61, 'አሁንም ፍርዳቸው ይደርስባቸዋል።'),
  ('a67cb9fb-3b19-549a-a9eb-aa7f5137b307', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 44, 62, 'ለአንተና እንደ አንተ ለአሉ ለጥቂቶች እንጂ ይህን ለብዙዎች አልተናገርሁም።”'),
  ('4ba3e843-30aa-5c4b-a480-21c0170786d1', 'f25c16c8-f42b-53ee-aaa3-8f141ad2b2fb', 'd73195bc-0249-58b7-ab83-18a54a39f3ff', 45, 63, 'እኔም መለስሁለት፤ እንዲህም አልሁት፥ “አቤቱ! እነሆ፥ እስካሁን ድረስ በኋላ ዘመን ታደርገው ዘንድ ያለህን ብዙ ምልክት ነገርኸኝ፤ ነገር ግን ጊዜው መቼ እንደ ሆነ አልነገርኸኝም።”'),
  ('579b0449-3938-592c-ab29-931eea1224c7', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 1, 1, 'መልአኩም መለሰልኝ እንዲህም አለኝ፥ “አንተ ራስህ ገምግመው፤ እኔ ከነገርሁህ ምልክት ያለፈ ብታይ፥'),
  ('8405c9b1-f57a-5b6e-a98e-3fba26a505c2', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 2, 2, 'ልዑል የፈጠረውን ዓለም ይጐበኝበት ዘንድ ያለው ጊዜ እንደ ደረሰ ያንጊዜ ዕወቅ።'),
  ('8dd60d93-e597-5403-a4fe-f7c03ba63470', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 3, 3, 'በዓለም በየሀገሩ ሽብር በሆነ ጊዜ፥ አሕዛብም በታወኩ ጊዜ፥ ሕዝቡም በተሸበሩ ጊዜ፥ አለቆችም በተዋጉ ጊዜ፥ መሳፍንቱም በደነገጡ ጊዜ፥'),
  ('ece6ec0d-b531-57d1-a8f9-839e32a69c7a', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 4, 4, 'ስለዚህ ልዑል ከጊዜው አስቀድሞ እንደ ተናገረ ያንጊዜ ዕወቅ።'),
  ('e41dc195-4df3-5f56-a4b6-5e4e27b650d3', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 5, 5, 'በዓለም የሆነው ሁሉ አስቀድሞ በቃል፥ ኋላም በመገለጥ እንደ ሆነ፥'),
  ('87917ea7-e340-5b68-ac57-26aa3790f023', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 6, 6, 'እንዲሁም የልዑል ዓለም መጀመሪያ በቃል፥ በተአምርና በኀይል፥ ኋላ ግን በሥራና በድንቅ ነው።'),
  ('6e2ec461-abad-584d-a9c2-c34ec5a6909b', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 7, 7, 'በምግባሩና በአመነበት ሃይማኖቱ የዳነና ማምለጥ የቻለ፥'),
  ('05c6ae69-c38f-5729-a100-9a8d1356aee8', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 8, 8, 'ከነገርሁህ ሥቃይ የሚድን እርሱ ብቻ ነው፤ ከዚህ ዓለም ለእኔ በለየኋት በምድሬና በድንበሬም ሕይወትን ያያል።'),
  ('dcc50645-d0a6-51c1-ab68-1fcf9a21bcc4', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 9, 9, 'ዛሬ ትእዛዜን ቸል ያሉ ያንጊዜ መከራን ይቀበላሉ፤ እኔን መፍራትን የተዉና የናቁኝም በገሃነም ውስጥ ይጨነቃሉ።'),
  ('d5e46e80-c8f7-5272-a452-d1f3d81f421e', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 10, 10, 'እኔ እየረዳኋቸው በሕይወታቸው ሳሉ የማያውቁኝም ሁሉ፥'),
  ('e0dbdf65-71b8-54a8-a083-d0cb70478a50', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 11, 11, 'እነርሱ ነጻ ሳሉ በሕጌ ላይ የታበዩም ሁሉ፥'),
  ('a701dd47-bb6c-543a-ac93-672ae6c758bc', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 12, 12, 'የትዕግሥቴም ቦታ ክፍት ሆኖላቸው ሳለ ልብ ያላደረጉኝ፥ የናቁኝም ሁሉ፥ ከሞቱ በኋላ ያውቁኝ ዘንድ አላቸው።'),
  ('837a8c09-4a76-5ba6-aaf1-4d2ef0ee4158', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 13, 13, 'አንተ ግን ኃጥኣን እንዴት እንደሚፈረድባቸው አትመርምር፤ ጻድቃን በዓለማቸው እንዴት እንደሚድኑ መርምር እንጂ፤ የሚመጣው ዓለም ስለ እነርሱ ነውና።”'),
  ('3b1b520c-1be2-587d-a517-2898edd62a49', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 14, 14, 'እኔም መለስሁለት፤ እንዲህም አልሁት፦'),
  ('c75122da-1bfa-5eaa-a7ff-ad010d58e506', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 15, 15, '“ዝናም ከካፊያ እንደሚበዛ ከሚድኑት ኋለኞች ይልቅ የሚጠፉት እንደሚበዙ ቀድሞ ተናገርሁ፤ ዛሬም እናገራለሁ።”'),
  ('0f93da73-0bbe-5939-ab05-32400dd29420', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 16, 16, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “ዘሩ በእርሻው መጠን እንደ ሆነ ፍርዱም እንደ ሥራው ነው፤ አጫጁም በአራሹ መጠን ነው።'),
  ('0e948735-a8e6-536b-a347-974b68ded175', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 17, 17, 'ዛሬ በውስጡ የሚኖሩበት ዓለማቸው ሳይፈጠር ያዘጋጀሁት ዓለም በጊዜው ነውና።'),
  ('85995402-be16-533f-abe6-74af495f3e04', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 18, 18, 'ያንጊዜም የተከራከረኝ የለም፤ ማንም የነበረ የለምና።'),
  ('08bf91a0-27d6-5941-a19e-a257039bf5fd', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 19, 19, 'አሁንም በምግብና ፍለጋ በሌለው በዘለዓለማዊ ሕግ በተዘጋጀው ዓለም ከተፈጠሩ በኋላ በሥራቸው ሞት ነበር።'),
  ('53746b67-dd72-5223-a6ef-489286f5cc52', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 20, 20, 'ዓለሙንም ባየሁት ጊዜ እነሆ፥ እነርሱ ጠፉ። በምድር በተዘራው ሥራቸውም እነሆ፥ ዓለም ይጨነቃል።'),
  ('762daa18-0290-5395-ac62-0cde4cf91995', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 21, 21, 'ሄጄም ለጥቂቶቹ ራራሁላቸው፤ ከዘለላውም ውስጥ ፍሬዎችን ለእኔ አስቀረሁ። ከብዙ ዛፍም አንድ ተክል መረጥሁ።'),
  ('acf97948-7d97-59ae-a8f2-587a133d0d2d', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 22, 22, 'በከንቱ የተወለዱ ብዛታቸው ይጠፋል፤ በብዙ ሥራ የጸናች ፍሬዬም፥ ተክሌም ትጠበቃለች።'),
  ('2f6dc1dd-2fbd-594c-ae54-83bc8fcb63a2', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 23, 23, 'አንተ ግን ዳግመኛ ሰባት ቀን ብትጾምና ብትጸልይ፥'),
  ('8d7e1ec8-077e-579d-a56c-e55cee3394ee', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 24, 24, 'ግንብ ወደአልተሠራባት ምድረ በዳ ብትሄድና ከእንጨት ፍሬ ብቻ ብትበላ፥ ሥጋም ባትበላ፥ ከእንጨቱ ፍሬ ብቻ በቀርም ወይን ባትጠጣ፥'),
  ('f4a93d23-8c6a-532f-a34b-893bcc0b7742', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '4e4999f1-8153-5091-a728-87d52fa9b823', 25, 25, 'ወደ ልዑል ሁልጊዜ ብትጸልይ መጥቼ እነግርሃለሁ።”'),
  ('80fa7ae8-b9f1-5826-a128-fb7c8cf79aa5', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 1, 26, 'ከዚህ በኋላ እግዚአብሔር እንዳዘዘኝ ስሙ አርፋድ ወደሚባል ምድረ በዳ ሄድሁ።'),
  ('c88893a1-2fee-52f0-afb9-f660272eebbc', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 2, 27, 'በሣር ውስጥ ተቀመጥሁ፤ የምድረ በዳንም ፍሬ ተመገብሁ፤ የበላሁትም ያጠግበኝ ነበር።'),
  ('97170b64-204a-5943-a32e-e5561d66d4d6', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 3, 28, 'ከዚህም ከሰባተኛው ቀን በኋላ በሣር ውስጥ ተኝቼ ሳለሁ ልቤ እንደ ቀድሞው ታወከብኝ።'),
  ('b612655d-7c3e-5101-a1c0-f8fc61c10b14', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 4, 29, 'አንደበቴንም አቅንቼ በልዑል ፊት እናገር ጀመርሁ፤'),
  ('dc5798b3-de87-586c-a491-607ed7a8dbcd', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 5, 30, 'እንዲህም አልሁ፥ “አቤቱ ጌታዬ፥ ዛፍና ሣር በሌሉበት ምድረ በዳ ለአባቶቻችን ፈጽመህ ታየሃቸው።'),
  ('d6a373a9-573b-5f19-a846-934bb1b56a41', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 6, 31, 'እንዲህም አልሃቸው፦ ‘አንተ እስራኤል ስማኝ፤ ቃሌንም አድምጠኝ፤'),
  ('743d4aaa-738a-566f-a4cd-175fc75dae0d', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 7, 32, 'እነሆም እኔ ሕጌን በውስጣችሁ እዘራለሁና፥ በላያችሁም ፍሬን ያፈራልና፥ ለዘለዓለሙም ትከብሩበታላቸሁና።’'),
  ('554516cc-e9c2-5f21-a1e5-6d790dc99ddf', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 8, 33, 'አባቶቻችንም ሕግህን ተቀብለው አልጠበቁም፤ በሥርዐትህም አልጸኑም፤ የሕግህ ፍሬ ግን አልጠፋም፤ የአንተ ገንዘብ ስለሆነ ይጠፋ ዘንድ አይቻልምና።'),
  ('ac88a328-65dd-54ed-a486-610d82b165ce', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 9, 34, 'ሕግ ያንተ ገንዘብ ስለሆነች በውስጣቸው የተዘራውን ተግባራቸውን አልጠበቁምና ሕግህን ተቀብለው ያልጠበቁ ጠፉ።'),
  ('55970bfb-06f4-5d80-a40a-da801a3311dd', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 10, 35, 'ምድርም ዘርን ከተቀበለች በኋላ፥ ባሕርም መርከብ በውስጧ ከገባ በኋላ፥ ዕቃም በውስጡ መብልና መጠጥን ከጨመሩበት በኋላ፥'),
  ('bf050cce-a6c2-57e9-afbf-c11ddbb99f78', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '092477a6-d3b9-5c34-a401-79842e9121fe', 11, 36, 'ያንጊዜ የዚያ የዘሩ፥ የዚያም የመርከቡ፥ የዚያም የመብሉና የመጠጡ ይጠፋ ዘንድ ጊዜው ቢሆን እንደዚሁ የሚጠፋ ይሆናል። ነገር ግን የያዙት ይቀራሉ። ለእኛስ እንደዚሁ አይደለም። ሕግን ተቀብለን የበደልን እኛ እንጠፋለንና፥ የተቀበለው ልባችንም እንዲሁ ነው፤ ሕጉ ግን በክብሩ ይኖራል እንጂ አይጠፋም።”'),
  ('4e454282-305f-52be-afdb-4ed2b5c489b0', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 1, 37, 'በዐይኖችም በተመለከትሁ ጊዜ በቀኝ በኩል እነሆ፥ አንዲት የምታለቅስ ሴትን አየሁ፤ በታላቅ ድምፅም ትጮኽ ነበር፤ እጅግም አዝና ነበር፤ ልብሷም ተቀድዶ ነበር፤ በራሷም ላይ ዐመድ ነስንሳ ነበር።'),
  ('c7e19e11-1dbb-5f83-ac80-3388d78aba27', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 2, 38, 'ያ ቀድሞ የማስበው አሳቤም ተለየኝ፤ ወደ እርሷም ተመልሼ፥ “ምን ያስለቅስሻል? ልቡናሽንስ ለምን ታሳዝኛለሽ? አልኋት።”'),
  ('7b59c8b1-8ad7-516f-aa20-f989342197b8', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 3, 39, 'እርስዋም አለችኝ፥ “ጌታዬ ለራሴ አለቅስ ዘንድ በመከራዬም ላይ መከራን እጨምር ዘንድ ተወኝ፤ ፈጽሜ እኔ አዝኛለሁና፥ ልቡናዬም ተጨንቃለችና።”'),
  ('8892bbf7-d17a-5cf2-a282-cbb71a1c89b6', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 4, 40, 'እኔም፥ “ምን ሆነሻል? ንገሪኝ” አልኋት።'),
  ('23ca5e2d-00b4-5a12-aa0f-b44576567640', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 5, 41, 'እርስዋም አለችኝ፥ “እኔ ባሪያህ ከጥንት ጀምሮ መካን ነበርሁ፤ ሠላሳ ዘመን ከባሌ ጋር ስኖር ልጅ አልወለድሁም።'),
  ('7473a0e4-414d-5488-a472-e08db4b64d4f', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 6, 42, 'እኔም በዚያ በሠላሳው ዘመን ሁልጊዜ በየጊዜውና በየሰዓቱ በመዓልትና በሌሊት ወደ ልዑል እጸልይ ነበር።'),
  ('6729db25-3e55-511f-a4b5-4a0383bf25d5', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 7, 43, 'ከዚህም ከሠላሳ ዓመት በኋላ እግዚአብሔር የባሪያውን ልመና ሰማ፤ መከራዬንም አየ፤ ድካሜንና ሥቃዬን ተመልክቶ አንድ ልጅ ሰጠኝ፤ በእርሱም ፈጽሞ ደስ አለኝ፤ እኔም፥ ባሌም፥ ያገሬም ሰዎች ሁሉ ደስ አለን፤ እግዚአብሔርንም አመሰገንነው።'),
  ('6d466306-b89d-57cb-a0d4-9b22ba93d398', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 8, 44, 'በብዙ ድካምም አሳደግሁት።'),
  ('bd02e30a-a7dc-53dd-a908-cc83419eb3e0', '87d207cf-4911-5ab9-a9d9-a72fe48bf02d', '30b397c0-acb8-55f7-a3de-ba7dc76b67eb', 9, 45, 'ከዚህም በኋላ አካለ መጠን ባደረሰ ጊዜ ሚስት አጋባሁት፤ ሰርግንም ሰረግሁለት።'),
  ('d803e4b3-8a06-5f7b-a2e9-6b77e369e839', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 1, 1, '“ከዚህ በኋላ ወደ ጫጕላው በገባ ጊዜ ወድቆ ሞተ።'),
  ('4c3b73ab-ea7b-5348-af47-ae6661a73ec2', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 2, 2, 'ከዚህ በኋላም ፋናችንንና መብራታችንን አጠፋን፤ እናለቅስ ዘንድም ተቀመጥን፤ ያገሬ ሰዎችም ሁሉ ተነሥተው ይመክሩኝና ያረጋጉኝ ጀመሩ፤ ከዚህም በኋላ እስከ ማግሥትዋ ቀን ሌሊት ድረስ ዝም አልሁ።'),
  ('7fcab62e-6aa4-5328-a5b1-1975e9380788', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 3, 3, 'ከዚህ በኋላ ሁሉም ዝም ባሉ ጊዜ፥ እኔንም መምከር በተዉ ጊዜ እኔ ሌሊት ተነሥቼ ሸሸሁ፤ ወደዚህም ምድረ በዳ መጣሁ።'),
  ('11f37365-0798-564f-af51-f660c5d7d80d', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 4, 4, 'ለዘለዓለሙ በዚሁ እኖራለሁ እንጂ እንግዲህ ወዲህ ወደ ሀገሬ እንዳልመለስ ቈረጥሁ፤ ሁልጊዜ እጾማለሁ፤ እስክሞትም ድረስ አለቅሳለሁ እንጂ እህል አልበላም፤ ውኃም አልጠጣም።”'),
  ('e9ca07fa-9650-5c17-a77f-3b079ec1822c', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 5, 5, 'ያ የማስበው አሳቤም ተወኝ፤ እኔም መለስሁላት፤ እንዲህም አልኋት፦'),
  ('6275d75b-00e0-50e1-a590-ad4d5a4fbda1', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 6, 6, '“ከሴቶች ሁሉ አንቺ አላዋቂ ነሽ፤ ያገኘችንን የእኛን ልቅሶ አታዪምን?'),
  ('e54081c6-2861-5112-a1a8-48093d09669a', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 7, 7, 'ስለ ሁላችን እናት ስለ ጽዮን ሁላችን በኀዘን አለን፤ መከራንም ፈጽመን ተቀበልን።'),
  ('fa5bec57-e422-596a-a43b-4a65a95d5bc1', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 8, 8, 'አሁንም በእውነት ታዝኚና ታለቅሺ ዘንድ ይገባሻል፤ እኛ ሁላችንም ያዘንን ነንና፤ እኛም ስለ ብዙዎች እናዝናለን፤ አንቺ ግን ስለ አንዱ ልጅሽ ታዝኛለሽ።'),
  ('e226e5d9-978f-54ec-ad30-05d9b7dd55e0', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 9, 9, 'ምድርን ጠይቂአት፤ ትነግርሻለችም፤ በእርስዋ ላይ ይህን ያህል ስለ ተወለዱት ታለቅስ ዘንድ አግባብ ለእርስዋ ነው።'),
  ('ad98a076-3cd2-5e96-a7ed-389973d00d01', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 10, 10, 'ሁሉም ከጥንት ጀምሮ በእርስዋ ላይ ተፈጠሩ። እነሆም ሌሎች መጥተው ሁሉንም በሙሉ ፈጽሞ ለማጥፋት ወሰዷቸው።'),
  ('523b3324-644d-5b84-a89a-0df021f4bacc', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 11, 11, 'እንግዲህ ወዲህ ፈጽሞ ያለቅስ ዘንድ የሚገባው ማን ነው? ይህን ያህል ብዙ የጠፋበት ነውን? ወይስ አንቺ ስለ አንድ ልጅሽ ታዝኛለሽን?'),
  ('10440260-7d7a-58cb-ad55-0318e162106f', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 12, 12, 'ወይስ በጻዕርና በገዓር የወለድሁትን ልጄን አጥቻለሁና፤ የእኔ ልቅሶ እንደ ምድር ልቅሶ አይደለም ትያለሽን?'),
  ('f2521936-977e-50fe-a53f-28ced0c2d0c2', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 13, 13, 'ምድር ግን ብዙ አሕዛብ ወደ እርሷ እንደ መጡ እንደዚሁ ሄዱ።'),
  ('dbddf8a9-7a14-57c7-a947-2e7c077f4bd1', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 14, 14, 'ነገር ግን እኔ እንዲሁ እልሻለሁ፤ አንቺ አምጠሽ እንደ ወለድሽ እንዲሁም ምድር ከጥንት ጀምሮ በእርሷ ለተፈጠሩ ሰዎች ፈጣሪዋ የሰጣትን ፍሬዋን ሰጠቻቸው።'),
  ('1f46e247-9879-5393-a7a4-482853f38409', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 15, 15, 'አሁንም ይህን ኀዘንሽን ካንቺ አርቂ፤ ስለ አገኘችሽ ቅጣትና መከራም ትዕግሥተኛ ሁኚ።'),
  ('0944d52a-23db-5057-a616-2c25e326e1ad', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 16, 16, 'እግዚአብሔርን ብታመሰግኚው ይረዳሻልና፥ ልጅሽንም በጊዜው ታገኚዋለሽና፥ በሴቶችም ዘንድ መከራን የታገሠች ትባያለሽና፥'),
  ('0fb03149-0ddc-5e52-a0f5-8b54a7211815', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 17, 17, 'አሁንም ወደ ሀገርሽ ግቢ፤ ወደ ባልሽም ሂጂ።”'),
  ('c0136da7-e3f8-52d7-a4dc-b8c6a2ded6cd', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 18, 18, 'እርስዋም አለችኝ፥ “እንዲህስ አላደርግም፤ በዚህ እሞታለሁ እንጂ ወደ ሀገሬ አልገባም።”'),
  ('fa92f014-5a7c-5c09-a569-61fc2d4c0d3c', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 19, 19, 'ዳግመኛም ተናገርኋት፤ እንዲህም አልኋት፦'),
  ('561e7117-6a19-5e1f-a47e-308c97f3890d', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 20, 20, '“ይህን ነገር አታድርጊ፤ እሺ በዪኝ፤ ራስሽንም እንደ ጽዮን መከራ አድርጊ፤ ስለ ኢየሩሳሌምም ከተማ ተረጋጊ።'),
  ('207bf399-4f87-5836-a2e8-9a99e9099f2f', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 21, 21, 'ቤተ መቅደሳችን እንደ ፈረሰ፥ መሠዊያችን እንደ ተሰባበረ አታዪምን?'),
  ('dac7e208-5726-50c4-aec0-67cedba9f28a', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 22, 22, 'ግናያቱ እንደ ጠፋ፥ ምስጋናችን እንደ ቀረ፥ ዘመራ ዘውዳችን እንደ ወደቀ፥ የመቅረዛችን መብራት እንደ ጠፋ፥ የቃል ኪዳናችን ታቦት እንደ ተማረከች፥ ንዋየ ቅድሳታችን እንዳደፈ፥ ስማችን እንደ ረከሰ፥ ጌቶቻችን እንደ ተዋረዱ፥ ካህኖቻችን እንደ ተቃጠሉ፥ ሌዋውያኖቻችን እንደ ተማረኩ፥ ደናግሎቻችን እንደ ተገደሉ፥ ሚስቶቻችንን እንደ ቀሙን፥ ጻድቃኖቻችን እንደ ተጐተቱ፥ ጐልማሶቻችን እንደ ተገዙ፥ ወንዶች ልጆቻችን እንደ ተቀሙ፥ አርበኞቻችን እንደ ደከሙ አታዪምን?'),
  ('851169fd-c817-5507-a327-a3fa4a88b117', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 23, 23, 'ከዚህ ሁሉ የሚበልጥ ጽዮን ጠፋች፤ ክብርዋም ከእርስዋ ወጣ፤ በጠላቶቻችንም እጅ ወደቅን።'),
  ('58f5403a-424b-5794-aed1-de528988e4ae', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 24, 24, 'አንቺም ተዪ፥ ልዑልና ኀያል ይቅር ይልሽ ዘንድ፥ ከድካምሽም እግዚአብሔር ፈጽሞ ያሳርፍሽ ዘንድ ይህን ብዙ ኀዘንሽን አርቂ።”'),
  ('940d2fa1-fd2b-528d-aa86-2684758915ba', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 25, 25, 'ከዚህ በኋላ ይኽን ስናገራት ድንገት ፊትዋ ከፀሐይ ይልቅ በራ፤ መልኳም እንደ መብረቅ አንጸባረቀ፤ ወደ እርሷ መቅረብንም ፈራሁ፤ ልቡናዬም ደነገጠብኝ፤ ከዚህም በኋላ ይህ ምን እንደ ሆነ ሳስብ አስደነገጠችኝ።'),
  ('0f019547-635c-5bba-af3d-47a34f13c671', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 26, 26, 'በታላቅ ድምፅም ጮኸች፤ ከድምፅዋም የተነሣ ምድር እስክትነዋወጥ ድረስ ድምፅዋ እጅግ የሚያስፈራ ሆነ።'),
  ('a754cbcb-01ec-597d-a39b-94b4141089e6', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 27, 27, 'ባየኋትም ጊዜ እነሆ የከበረችና የታነጸች ከተማ ነበረች እንጂ ሴት አልነበረችም፤ ታላቅ የሆነ የመሠረቶችዋንም ቦታ አየሁ፤ ፈርቼም በታላቅ ድምፅ ጮህኹ። እንዲህም አልሁ፦'),
  ('8da0bd26-a82e-54b2-ade9-b5ba194d2f36', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', '891e51e5-c89a-5f43-ada1-5304a1ce7805', 28, 28, '“አስቀድሞ ወደ እኔ የመጣህ መልአኩ ዑርኤል፥ አንተ ወዴት ነህ? ወደ ብዙ ምርምር እገባ ዘንድ፥ ፍጻሜዬም ለጕስቍልናዬ ትሆን ዘንድ፥ ጸሎቴም ለተግዳሮት ይሆን ዘንድ እንዲህ ለምን አደረግኸኝ?”'),
  ('8a2ed2f2-8a9f-55f9-a43c-9586b74a096b', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 1, 29, 'እኔ እንደዚህ ስናገር እነሆ፥ ቀድሞ ወድ እኔ የመጣው ያ መልአክ ወደ እኔ መጣ።'),
  ('3359a8bb-e938-55d5-a40c-07949ed5e193', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 2, 30, 'እንደ ሬሳ ተኝቼ አገኘኝ፤ አእምሮዬም ከእኔ ጋር አልነበረም፤ ቀኝ እጄንም ይዞ አጸናኝ፤ በእግሮችም አቅንቶ አቆመኝ።'),
  ('e83a8756-7c3d-51f5-a593-815d6bc99b76', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 3, 31, 'መለሰልኝ፤ እንዲህም አለኝ፥ “ምን ሆንህ? ምንስ ያስደነግጥሃል? ልብህስ ካንተ ጋር ስለምን የለም?”'),
  ('73e09f5c-f886-50c6-a07a-b3787fa7239b', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 4, 32, 'እኔም አልሁት፥ “አንተ ጥለኸኛልና፥ ተለይተኸኛልምና፥ እኔ እንደ ነገርኸኝ ወደዚህ ምድረ በዳ መጣሁ፤ ወደዚህም ምድረ በዳ በመጣሁ ጊዜ እነሆ፥ ማወቅ የማይቻለኝን አየሁ።”'),
  ('f9b6ed14-a701-5320-a983-1305e45ee689', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 5, 33, 'እርሱም አለኝ፥ “እንግዲህስ እነግርህ ዘንድ እንደ ሰው ቁም።”'),
  ('470a41ac-d468-5d6a-a198-bec57f990675', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 6, 34, 'እኔም አቤቱ ተናገር አልሁት፥ “ድንገት እንዳልሞት እንግዲህ አትለየኝ እንጂ።'),
  ('4b139d08-9593-504b-adea-4480eb56fd84', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 7, 35, 'ያላየሁትን አይቻለሁና፥ የማላውቀውንም ሰምቻለሁና።'),
  ('a8549a69-5c80-5895-a297-5341135f8615', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 8, 36, 'ነገር ግን ምናልባት ልቡናዬ ይዘነጋ ይሆንን? ሰውነቴስ ትጨነቅ ይሆንን?'),
  ('2bd42b4c-b418-5c03-a2b5-2ff940d321e9', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 9, 37, 'አሁንም አቤቱ በጅ በለኝ፤ የዚህንም ራእይ ትርጓሜ ለባሪያህ ንገረው።”'),
  ('638737be-7915-54eb-afd9-2f5ed6cce651', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 10, 38, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “ስለምትፈራው ነገር አስተምርህ ዘንድ ስማኝ። ይህ የተሰወረ ምሥጢር ስለሆነ፦ ልዑል እግዚአብሔር ገልጦልሃልና።'),
  ('a2ae040f-062c-5cac-a981-03c997e810cc', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 11, 39, 'ጽድቅህንም አየ፤ ስለ ወገኖችህ ብዙ ታዝናለህና፤ ስለ ጽዮንም እጅግ ትቈረቈራለህና።'),
  ('a4b38cde-146b-5a5d-aa3a-a6620b3c49f9', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 12, 40, 'ነገሩ ይህ ነው፦'),
  ('c2007374-ac11-583e-ab7c-0137c8202688', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 13, 41, 'ቀድሞ እንደ አልቃሽ ሆና ያየሃት፥ ታረጋጋትም ዘንድ የጀመርህ ይች ሴት፥'),
  ('89c25f3b-4141-5244-adef-1aeebb2b93b4', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 14, 42, 'አሁን አንተ እንዳየሃት ሴት አይደለችም። የታነጸች ከተማ እንጂ።'),
  ('6b6fbd73-24b8-5b2a-a2d3-17017e2e7600', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 15, 43, 'ስለ ልጅዋ መከራ ነግራሃለችና።'),
  ('92df881b-e320-5812-a130-9cbbb59ae48c', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 16, 44, 'ያች ያየሃት ሴት ዛሬ እንደ ታነጸች ከተማ ሀገር ሁና የምታያት ጽዮን ናት።'),
  ('3708dea2-ba76-517a-afc8-4123266f1071', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 17, 45, 'ሠላሳ ዘመን መካን ሆንኹ ያለችህም ይህ ነው፤ የሚያቀርቡት መሥዋዕት ሳይኖር ዓለም ሦስት ሺህ ዘመን ኖሯልና።'),
  ('7d23061e-aaf4-57c3-a3dc-e4ed7901188c', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 18, 46, 'ከሦስት ሺህ ዓመት በኋላም ሰሎሞን ከተማን ሠራ፤ ያንጊዜም ቍርባንን አቀረበ። ያችም መካን ሴት የወለደችው ልጅ፥'),
  ('78c431b5-f192-5de5-a6ab-c24eb142019e', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 19, 47, 'ይህም በብዙ ድካም አሳደግሁት ያለችህ ኢየሩሳሌም የኖረችው ዘመን ነው።'),
  ('377ed1ff-2346-53cf-a783-4fc9a776b1af', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 20, 48, 'ይህም ልጅዋ ወደ ጫጕላው በገባ ጊዜ ወድቆ ሞተ፤ ይህም መከራ አገኘን ያለችህ የኢየሩሳሌም ጥፋትዋ ነው።'),
  ('a96fadcf-5884-5628-a45f-68ba9d503ec3', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 21, 49, 'እነሆ ለልጆችዋ እንዴት እንደምታለቅስላቸው ያየሃት፥ አንተም ከመከራዋ ታረጋጋት ዘንድ የጀመርህ ያች ሴት ኢየሩሳሌም ናት።'),
  ('01167394-a2c9-59af-ad07-aaf7ff0138e0', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 22, 50, 'አሁንም ልዑል እግዚአብሔር ስለ እርስዋ በፍጹም ሰውነትህ እንድታዝን፥ በፍጹም ልቡናህም እንድትቈረቈር ባየ ጊዜ የደስታዋን ጌጥና የክብሩዋን መገለጥ አሳየህ። የተሰወረ ምሥጢር ነውና።'),
  ('c78599fc-08d4-5859-a070-b2d1c3907b49', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 23, 51, 'ስለዚህ ነገር ቤት ባልተሠራበት በዚህ በምድረ በዳ ትኖር ዘንድ እነግርሃለሁ።'),
  ('02106046-9f15-5c25-ab6b-881d705ebefa', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 24, 52, 'ልዑል እግዚአብሔር ያሳይህ ዘንድ ያለውን ሁሉ አውቄአለሁና።'),
  ('ece73c45-d822-5d83-aaab-f397ebde2940', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 25, 53, 'ስለዚህም የግንብ መሠረት ወደሌለበት ወደዚህ ትመጣ ዘንድ እነግርሃለሁ።'),
  ('30eb4ea1-a210-5bd5-a7b0-dda572dd9577', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 26, 54, 'ልዑል ይገለጥበት ዘንድ ባለው ቦታ የሰው ሥራ ግንብ ሊኖር አይቻልምና።'),
  ('79f04969-2202-5541-a8dd-c349297c3307', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 27, 55, '“አንተስ እንግዲህ አትፍራ፤ ልብህም አይደንግጥ፤ ገብተህ ብርሃንዋንና የግንብዋን ጽናት እይ እንጂ።'),
  ('84cea846-c04a-5722-a533-288037f32557', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 28, 56, 'መስማት የምትችለውን ያህል በጆሮህ ስማ።'),
  ('19e44888-55c4-5eda-aa1c-92dd57cacc18', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 29, 57, 'አንተ ከብዙዎች ይልቅ ራስህን ብፁዕ አሰኝተሃልና፥ በልዑልም ዘንድ እንደ ጥቂቶች ተጠርተሃልና።'),
  ('3004e540-9bb2-545a-a8e1-62a680a3562f', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 30, 58, 'ዛሬም በዚህ እደር።'),
  ('119a3f61-1d1f-5410-a084-e8684f7fa627', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 31, 59, 'ልዑል እግዚአብሔር በዓለም በሚኖሩ ሰዎች ላይ በጊዜው የሚያደርገውን ራእይ ነገ በሕልም ያሳይሃል።”'),
  ('83c4de0b-9c0b-504f-a278-bf3b129b0e86', 'f4a3adaa-89c5-5be3-a369-7f35d5557525', 'ccdc6361-a4ee-5ca7-a6c7-323daee26924', 32, 60, 'በዚያችም ሌሊት፥ በማግሥቱም እንዳዘዘኝ አደርሁ።'),
  ('3e3d6acf-2f2e-5827-a1ca-7f1c3aa5bdd7', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 1, 1, 'ከዚህም በኋላ በማግሥቱ ሌሊት ንስር ከባሕር ሲወጣ በሕልም አየሁ፤ ክንፎቹም ዐሥራ ሁለት ናቸው፤ ራሶቹም ሦስት ናቸው።'),
  ('05446bde-9c35-5a5c-acf5-36aa23f7857c', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 2, 2, 'በክንፎቹም በዓለሙ ሁሉ ይበርራል፤ የሰማይ ነፋሳትም ሁሉ ይነፍሱበታል፤ ደመናትም በእርሱ ይሰበሰባሉ።'),
  ('d70a8a48-641d-5007-af5c-8b4818830bff', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 3, 3, 'ከእነዚያም ክንፎች ራሶች ይበቅላሉ፤ እነዚያም ራሶች ደቃቅና ታናናሽ ክንፍ ይሆናሉ፤'),
  ('c997a479-99d8-52fe-a744-31579350046f', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 4, 4, 'ራሶቹም ዝም ይላሉ፤ ከእነዚያም ራሶች መካከለኛው ራስ ይበልጣል፤ ነገር ግን እርሱም ከእነርሱ ጋር ዝም ይላል።'),
  ('ff992834-6c3d-5576-adcc-a1c0d3c8158d', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 5, 5, 'ያም ንስር ምድርንና በምድር የሚኖሩትን ይገዛ ዘንድ በክንፎቹ ይበርራል፤'),
  ('cf402966-8af3-545f-a421-1e4fb4690ff2', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 6, 6, 'ከሰማይ በታች ያለ ሁሉ ይገዛለት ዘንድ ያን ንስር በምድር ከተፈጠረው ፍጥረት የሚከራከረው ማንም የለም።'),
  ('c2da8161-59c8-51fc-aca0-a09b7cf78a50', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 7, 7, 'ከዚህ በኋላ ያ ንስር ተነሣ፤ በጥፍሮቹም ቆመ፤ በታላቅ ድምፅም ጮኸ፤ ክንፎቹንም እንዲህ አላቸው፦'),
  ('cb07f28d-86ed-5faf-a9db-d0088b2bd5ee', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 8, 8, '“በየቦታችሁ ተኙ እንጂ ሁላችሁ እያንዳንዳችሁ በአንድነት አትነሡ፤ በየጊዜውም ትነሣላችሁ።'),
  ('eb41092f-8cc1-59fc-a4a7-1c88d686a819', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 9, 9, 'የኋለኛዪቱ ራሱም ከሁሉ ትበልጣለች።”'),
  ('51cfa3ae-55a3-52ad-a401-1950aa3e7c50', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 10, 10, 'ባየሁ ጊዜም ድምፁ የሚወጣ ከሥጋው መካከል እንጂ ከራሱ ውስጥ አይደለም።'),
  ('b5660bbe-2887-50ab-a976-539f48f8478f', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 11, 11, 'የእነዚያ ራሶች ቍጥሮችም ስምንት ናቸው።'),
  ('f53ba4b8-3005-524c-a928-c627686e7444', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 12, 12, 'ከዚህ በኋላ በቀኝ በኩል ክንፍ ወጣ፤ ምድሩንም ሁሉ ገዛ።'),
  ('7874b28f-8c6f-5a42-ad7d-02911a8afcb0', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 13, 13, 'ከዚህ በኋላ ጥፋቱ በደረሰ ጊዜ ቦታው እስከማይታይ ድረስ እርሱም ጠፋ፤ ሁለተኛውም ወጣ፤ እርሱም ብዙ ዘመን አጽንቶ ገዛ።'),
  ('65ff0cf9-d8bb-5768-a467-7cdc792e9e14', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 14, 14, 'ከዚህም በኋላ ጥፋቱ በደረሰ ጊዜ እርሱም እንደ ፊተኛው ጠፋ።'),
  ('82a4c731-1f38-590b-a9db-c21fc59bdec5', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 15, 15, 'ቃልም መጣለት፤ እንዲህም አለው፦'),
  ('2ec35655-4307-564a-abd1-053789f28d45', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 16, 16, '“ምድርን ይህን ያህል ዘመን አጽንተህ የምትገዛ አንተ ንስር ሳትጠፋ ይኽን የምነግርህን ስማ።'),
  ('bc488398-8c58-52d6-a827-569daf58ca79', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 17, 17, 'ከአንተ በኋላ እንደ አንተ የሚጸና፥ የእኩሌታህንም ያህል የሚገዛ የለም።”'),
  ('ccc1484a-c511-5aad-a8b3-7cce3a0d5dd2', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 18, 18, 'ሦስተኛውም ወጣ፤ እርሱም እንደ መጀመሪያው አጽንቶ ገዛ፤ ከዚህ በኋላ እርሱም ጠፋ።'),
  ('e1b1de6c-0538-522c-a2fd-72c4f560ac7c', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 19, 19, 'ከዚህም በኋላ ዳግመኛ ክንፎቹ ሁሉ ወጡ፤ እያንዳንዳቸውም ገዙ፤ ዳግመኛ ሁሉም ጠፉ።'),
  ('30192477-55c4-5bcc-a565-71e804722140', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 20, 20, 'ከዚህ በኋላ ክንፎቹ አጽንተው ይገዙ ዘንድ በግራ በኩል በየጊዜያቸው ተነሡ፤ ነገር ግን ፈጥነው ጠፉ።'),
  ('fd52840e-e431-5d5f-a844-480d369433a0', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 21, 21, 'ከእነርሱም ውስጥ የተነሡ አሉ፤ ነገር ግን እነርሱ አልገዙም።'),
  ('6e322de9-9446-54f3-a5bb-eae8a937aeaf', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 22, 22, 'ከዚህ በኋላም እነዚያ ዐሥራ ሁለቱ ክንፎቹ ጠፉ፤ እኒያም ሁለቱ ራሶቹ ጠፉ።'),
  ('fa431995-c366-5bad-a6ba-73013d5d848f', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 23, 23, 'ዝም ከሚሉ ከሦስቱ ራሶቹና ከስድስቱ ራሶቹ በቀር ከዚህ ንስር ወገን የቀረ የለም።'),
  ('53c85663-4812-5963-af37-6ef85212cb8c', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 24, 24, 'ከዚህም በኋላ ከእነዚያ ከስድስቱ ራሶች ሁለቱ ተለይተው ሄዱ፤ በቀኝ በኩል ባለ ራሱ ውስጥም ተቀመጡ፤ አራቱ ግን በቦታቸው ቀሩ።'),
  ('79c67f14-da63-5246-a264-199362dc2114', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 25, 25, 'እኒህ አራቱ ራሶች ግን ይቆሙ ዘንድ፥ እነርሱም ይገዙ ዘንድ ተማከሩ።'),
  ('dd4924f7-ddea-5a03-ae5f-3bff32f79efa', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 26, 26, 'ከዚህም በኋላ አንዱ ተነሥቶ ቆመ፤ ነገር ግን ፈጥኖ ጠፋ።'),
  ('4508d7b5-c0f8-55ce-ac2d-d85d19a15fa4', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 27, 27, 'ሁለተኛውም እንዲሁ ከፊተኛው ይልቅ እርሱ ፈጥኖ ጠፋ።'),
  ('5267aa73-d322-5869-a77b-1639ef7cd108', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 28, 28, 'ከዚህ በኋላ የቀሩት እኒህ ሁለቱ ተተክተው ይገዙ ዘንድ እንዲሁ ተማከሩ።'),
  ('27ae5ae9-453d-5a5e-adee-9a7d529617bb', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 29, 29, 'ከዚህም በኋላ እኒህ ሲማከሩ ዝም ከሚሉ ከሦስቱ ራሶች መካከለኛ የሚሆን አንዱ ተነሣ፤ ከእነርሱም የሚበልጥ እርሱ ነው።'),
  ('62cfea82-a906-5ffd-afd9-cd682ab00996', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 30, 30, 'ከዚህም በኋላ እኒህን ሁለቱን ራሶች ከእርሱ ጋር ወሰዳቸው።'),
  ('580d0b04-7ccb-502e-a0be-aa1916cb6090', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 31, 31, 'ያም ራስ አብረውት ካሉት ጋራ ተመለሰ፤ ይገዙ ዘንድ የተማከሩ እኒህን ሁለቱንም ራሶች ዋጣቸው።'),
  ('cbc41998-4ee9-5c31-acd4-6043407207a5', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 32, 32, 'ያም ራስ ምድርን ሁሉ ያዛት፤ በውስጥዋም የሚኖሩትን በብዙ ድካምና መከራ አሠቃያቸው፤ ከቆሙት ከእኒያ ክንፎች ሁሉ ይልቅ ፈጽሞ ዓለምን ቀማ።'),
  ('9ccfc22d-106f-5223-ae47-899ec626ed79', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 33, 33, 'ከዚህም በኋላ መካከለኛው ራስ እንደ እነዚያ ጠፋ።'),
  ('cd6184f8-c01f-573e-a120-52ec17947373', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 34, 34, 'ሁለቱ ራሶችም ቀሩ፤ እነርሱም እንዲሁ ምድርንና በውስጧ የሚኖሩትን ገዙ።'),
  ('a7467376-40a7-596a-a62f-6fe4fca9f883', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '516b727e-b46d-53d2-a709-5770b18c383b', 35, 35, 'ከዚህ በኋላ ያ በቀኝ በኩል ያለው ራስ በግራ በኩል ያለውን ዋጠው።'),
  ('f6b31097-af7f-50c2-a2cd-6f8372391ef0', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 1, 36, '“ወደ ፊትህ ተመልከት፤ የምታየውንም ዕወቅ” የሚለኝን ቃል ሰማሁ።'),
  ('616a02c6-553d-5d1c-ad29-441a3fc8d488', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 2, 37, 'ባየሁም ጊዜ እነሆ አንበሳ እያገሣ ከዱር ተነሣ፤ እንደ ሰውም ድምፅ ሲናገር ሰማሁት፤ ያንም ንስር እንዲህ አለው፦'),
  ('b4d9d69e-40b9-5684-a89b-cdec550f044d', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 3, 38, '“የምነግርህንና ልዑል ያለህን አንተ ስማ።'),
  ('4be1a24e-7ef7-5f67-af77-214d5e450e78', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 4, 39, 'ምድርን ይገዟት ዘንድ ከፈጠርኋቸው፥ የዘመንም ፍጻሜ ከሚደርስባቸው ከእነዚያ ከአራቱ እንስሳ የቀረህ አንተ አይደለህምን?”'),
  ('f1f2211e-22b3-57ff-a446-4f89e41e2cf3', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 5, 40, 'አራተኛውም መጥቶ ያለፉትን በብዙ ድካምና ሕማም ይህን ዓለም የቀሙትን እነዚያን እንስሳ ሁሉ ድል ያደርጋቸዋል፤ ይህን ያህል ዘመን በዚህ ዓለም በተንኰል ኖረ።'),
  ('6add8418-ab50-590b-a262-dff314e18335', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 6, 41, 'ዓለምንም በክፉ አገዛዝ ገዛት።'),
  ('fd5c879b-1ea4-5cb1-adf5-cc08e175fb07', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 7, 42, 'ጻድቃንን ቀምቶአቸዋልና፥ ደጋጎቹንም በድሎአቸዋልና፥ ቅኖቹንም ጠልቶአቸዋልና፥ አሰተኞቹንም ወዶአቸዋልና፥ የጻድቃንንም አንባቸውን አፍርሶአልና፥ ያልበደሉትንም ቅጽራቸውን አፍርሶአልና።'),
  ('171691b4-a820-529e-afff-eeaf716da478', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 8, 43, 'ኀጢአቱም ወደ ልዑል ደርሳለችና፥ ትዕቢቱም ወደ ኀያል ደርሳለችና።'),
  ('2f2ad963-3722-5f37-a90a-11cc06cdb8dc', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 9, 44, 'ልዑልም የራሱን ሰዎች ተመልክትዋቸዋልና፥ እነሆም ዓመቱ ተፈጽሞአልና።'),
  ('0d175d72-2b3a-5d51-a15f-1722412803f0', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 10, 45, 'ስለዚህም አንተ ንስር ፈጽመህ ትጠፋለህ፤ ኀጢአተኞች ክንፎችህ፥ ዝንጉዎች ራሶችህ፥ ክፉዎች ጥፍሮችህና ዐመፀኛው ሥጋህ ይጠፋሉ።'),
  ('5208b4f8-90a4-5d52-a6f8-65d09d2b1f61', 'c22a2fa1-629c-591a-a3db-2ccfb0b4627d', '8bba220f-6877-541d-adae-c8a59631d64b', 11, 46, 'ምድርም ከመከራዋ ሁሉ እፎይ ብላ ካንተ ፈጽማ ታርፍ ዘንድ የፈጣሪዋን ፍርዱንና ቸርነቱን ተስፋ ታደርጋለች።'),
  ('acf2b11a-0a47-5217-a97c-6d17b14df5e2', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 1, 1, 'ከዚህም በኋላ ፈጣሪ ለዚያ ንስር ይህን ቃል በነገረው ጊዜ፥'),
  ('6e0cf7aa-b914-5528-add3-658f69c4400f', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 2, 2, 'የቀረው ያ ራስ ጠፋ፤ወደ እርሱ የመጡ እነዚያም ክንፎች ተነሡ፤ እነርሱም ይገዙ ዘንድ ተነሡ፤ በጥፍራቸውም ይታወኩ ነበር።'),
  ('ac2e2c5b-d75e-5d66-aa6c-e3f3ab0c1f97', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 3, 3, 'ከዚህ በኋላ እነርሱም ጠፉ፤ ሥጋቸውም ሁሉ ተቃጠለ፤ ምድርም ፈጽማ ደነገጠች። እኔም ከብዙ ምርምር የተነሣ ደነገጥሁ፤ በጽኑ ፍርሀትም ነቃሁ።'),
  ('8e56cba5-4fa9-5e10-ae2d-bf2c7973ccf4', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 4, 4, 'ልቡናዬንም እንዲህ አልኋት፥ “የልዑልን ሥራ ስትመረምሪ አንቺ ይህን ሁሉ አደረግሽኝ።'),
  ('c04f3fd3-6bd4-5a44-a4b8-8ac9704d47e7', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 5, 5, 'ሰውነቴም ደከመች፤ ልቡናዬም እጅግ ተጨነቀች፤ በብዙ ፍርሀት ተይዤ ምንም ኀይል የለኝም፤ በዚችም ሌሊት ደነገጥሁ።'),
  ('eb47128a-f27e-5159-a01d-a1d34b93e1e6', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 6, 6, 'አሁንም ለዘለዓለሙ ያጸናኝ ዘንድ ወደ ልዑል እጸልያለሁ።”'),
  ('1dd2b8d2-d077-5f36-a2a5-244976b1a7c0', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 7, 7, 'እንዲህም አልሁ፥ “አቤቱ ጌታዬ በዐይኖችህ ፊት ባለሟልነትን ካገኘሁ፥ በአንተም ዘንድ ራሴን ብፁዕ ካሰኘሁ፥ ጸሎቴም በፊትህ ከደረሰች፥'),
  ('ada0ca59-b25c-516b-a447-9d33dfb7a040', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 8, 8, 'አድነኝ፤ አጽናኝም፤ ነፍሴም ፈጽማ ደስ ይላት ዘንድ የሚያስፈራ የዚህን ሕልም ትርጓሜ ለባሪያህ ንገረው።'),
  ('a6b26780-e9a8-5216-a7f9-d6786c2aafa0', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'bf919fc4-aac1-5b12-a9bd-d7b5796be265', 9, 9, 'በኋላ ዘመን የሚደረገውንና የዓለሙን ኅልፈት ያሳየኸኝ አንተ ብፁዕ አድርገኸኛልና።”')
